// Auto-generated from bbm_marketplace_agreement.docx
// k: h1 = major section heading, h2 = numbered sub-heading, body = paragraph text
const TERMS_CONTENT = [{ "t": "B2B MARKETPLACE PARTICIPANT AGREEMENT", "k": "h1" }, { "t": "This B2B Marketplace Participant Agreement (“Agreement”) sets out the terms and conditions governing the registration and use of the Platform by a Participant and the purchase and/or sale of Products through the Platform.", "k": "body" }, { "t": "This Agreement takes effect for a Participant on the date such Participant completes registration and accepts these terms on the Platform (“Effective Date”).", "k": "body" }, { "t": "BY AND BETWEEN", "k": "h1" }, { "t": "BRAND BRIGADE MARKETING PRIVATE LIMITED, a company incorporated under the Companies Act, 2013, bearing CIN U74999GJ2017PTC097922, having its registered office at Shivshakti Auto Maninagar, Green Land Kuvada Road, Rajkot, Gujarat, India – 360003., acting through its duly authorised representative (hereinafter referred to as the “Marketplace” or “Company”, which expression shall, unless repugnant to the context, include its successors and permitted assigns);", "k": "body" }, { "t": "AND", "k": "body" }, { "t": "[PARTICIPANT / LEGAL ENTITY NAME], having its registered/business address at [Address], PAN [PAN], GSTIN [GSTIN, if applicable], and represented by [Authorized Representative Name], hereinafter referred to as the “Participant”, which expression shall, unless repugnant to the context, include its successors, legal representatives and permitted assigns.", "k": "body" }, { "t": "The Marketplace and the Participant are individually referred to as a “Party” and collectively as the “Parties.”", "k": "body" }, { "t": "DEFINITIONS AND INTERPRETATION", "k": "h1" }, { "t": "2.1 Definitions", "k": "h2" }, { "t": "For the purposes of this Agreement, unless the context otherwise requires, the following terms shall have the meanings set out below:", "k": "body" }, { "t": "“Account” means the account, profile, credentials and associated records created or maintained by a Participant for accessing and using the Platform.", "k": "body" }, { "t": "“Buyer” means a Participant who, in relation to a particular Transaction, places an Order or otherwise purchases or agrees to purchase a Product from a Seller through or using the Platform.", "k": "body" }, { "t": "“Business Day” means a day other than a Saturday, Sunday or public holiday on which commercial banks are generally open for business in India.", "k": "body" }, { "t": "“Company” or “Marketplace” means Brand Brigade Marketing Private Limited, including its permitted successors and assigns.", "k": "body" }, { "t": "“Fees” means all fees, commissions, service charges, transaction charges, logistics charges, payment processing charges, penalties, subscription charges, or other amounts payable by a Participant to the Marketplace under this Agreement, the applicable Commercial Terms, or any applicable Policy.", "k": "body" }, { "t": "“Order” means a request placed by a Buyer through the Platform for the purchase of one or more Products from a Seller, which may be accepted, rejected, confirmed, cancelled or otherwise processed in accordance with the Platform's applicable procedures and Policies.", "k": "body" }, { "t": "“Participant” means any person or legal entity whose registration, onboarding or Account has been accepted by the Marketplace for use of the Platform and who has agreed to be bound by this Agreement. A Participant may act as a Buyer, Seller, or both, depending upon the relevant Transaction.", "k": "body" }, { "t": "“Platform” means the digital marketplace and related technology infrastructure operated, owned, controlled or made available by the Marketplace, including its website, mobile applications, software, APIs, interfaces, communication systems, dashboards and other digital channels through which Marketplace Services are provided.", "k": "body" }, { "t": "“Marketplace Services” means the technology, marketplace, communication, payment facilitation, settlement, logistics facilitation, verification, customer support, dispute assistance and other services that the Marketplace may make available to Participants from time to time.", "k": "body" }, { "t": "“Product” means any goods, materials, equipment, components, consumables or other products offered, listed, purchased or sold through the Platform, including any related documentation, specifications, accessories, packaging or other items forming part of the applicable Transaction.", "k": "body" }, { "t": "“Seller” means a Participant who, in relation to a particular Transaction, offers, supplies or agrees to sell a Product to a Buyer through or using the Platform.", "k": "body" }, { "t": "“Settlement” means the process by which amounts payable in respect of a Transaction are calculated, adjusted and paid or credited to the relevant Party after accounting for applicable Fees, taxes, refunds, returns, cancellations, chargebacks, penalties, deductions, holds, adjustments and other applicable amounts.", "k": "body" }, { "t": "“Transaction” means any purchase, sale, supply, order or other commercial transaction involving a Product between a Buyer and a Seller that is initiated, concluded, recorded, facilitated or otherwise processed through or using the Platform.", "k": "body" }, { "t": "“Transaction Value” means the gross value attributable to a particular Transaction, as determined in accordance with the applicable Order, invoice, commercial terms or Platform records, before deductions or adjustments unless otherwise specified.", "k": "body" }, { "t": "“Policies” means the policies, rules, guidelines, procedures, standards, codes, schedules and operating requirements issued or adopted by the Marketplace from time to time in relation to the Platform or Marketplace Services, including policies relating to KYC/KYB, prohibited Products, pricing, orders, shipping, returns, refunds, payments, settlements, conduct, data protection, fraud prevention and dispute resolution.", "k": "body" }, { "t": "“Platform Records” means electronic records maintained by or on behalf of the Marketplace relating to Participants, Accounts, Products, Orders, Transactions, communications, payments, settlements, deliveries, complaints, disputes and other activities undertaken through the Platform.", "k": "body" }, { "t": "“Applicable Law” means all applicable laws, statutes, ordinances, rules, regulations, notifications, circulars, governmental directions, orders, judgments and legally binding requirements of any competent governmental, regulatory, judicial or statutory authority applicable to a Party, Product, Transaction or activity under this Agreement.", "k": "body" }, { "t": "“Personal Data” means information relating to an identified or identifiable natural person, to the extent such information is regulated as personal data or equivalent information under Applicable Law.\n\n“Wallet” means the electronic ledger or account maintained by the Marketplace for a Participant on the Platform for recording amounts credited to, payable by, receivable by, or otherwise attributable to such Participant in connection with Transactions, including payments received, refunds, adjustments, Fees, penalties, credits, deductions, settlements and other amounts. The Wallet is an internal accounting mechanism of the Platform and, unless expressly stated otherwise, does not constitute a bank account, deposit account, payment account or stored-value instrument.", "k": "body" }, { "t": "“Sales Order” or “SO” means a sales order, order confirmation or equivalent commercial document issued or generated by a Seller through or in connection with the Platform in respect of a proposed or confirmed sale of Products to a Buyer, setting out, as applicable, the Products, quantities, prices, taxes, delivery terms, payment terms and other applicable commercial terms.", "k": "body" }, { "t": "“Purchase Order” or “PO” means a purchase order or equivalent commercial document issued or generated by a Buyer through or in connection with the Platform requesting or confirming the purchase of Products from a Seller, setting out, as applicable, the Products, quantities, prices, taxes, delivery requirements, payment terms and other applicable commercial terms.", "k": "body" }, { "t": "“Pricing” means the price, rate, charge or other commercial consideration applicable to a Product or Transaction, including any applicable discounts, rebates, surcharges, taxes, transportation charges or other components expressly identified as part of the applicable commercial terms.", "k": "body" }, { "t": "“Quotation” means any quotation, price offer, proposal, commercial offer or other pricing communication submitted or displayed by a Seller to a Buyer through or in connection with the Platform, specifying the proposed price and other applicable commercial terms for the supply of one or more Products.", "k": "body" }, { "t": "“Transportation” means the movement, carriage, shipment, dispatch, loading, unloading, handling and delivery of Products from the Seller or any other agreed origin to the Buyer or any other agreed destination, whether arranged by the Seller, Buyer, Marketplace or a third-party logistics or transportation service provider.\n\n2.2 Interpretation", "k": "body" }, { "t": "Unless the context otherwise requires:", "k": "body" }, { "t": "(a) references to the singular shall include the plural and vice versa;", "k": "body" }, { "t": "(b) references to any gender shall include all genders;", "k": "body" }, { "t": "(c) references to a “person” shall include an individual, company, LLP, partnership, firm, association, trust, body corporate, governmental authority or other legal entity;", "k": "body" }, { "t": "(d) references to any law or legislation shall include any amendment, modification, re-enactment, replacement or subordinate legislation made under it;", "k": "body" }, { "t": "(e) the words “including”, “includes” and “in particular” shall be construed without limitation;", "k": "body" }, { "t": "(f) headings are for convenience only and shall not affect the interpretation of this Agreement;", "k": "body" }, { "t": "(g) references to “written” or “in writing” shall include electronic communications and electronic records, to the extent permitted by Applicable Law;", "k": "body" }, { "t": "(h) references to the Platform or Marketplace Services shall include any successor, replacement, modified or additional platform, service, application, interface or technology made available by the Marketplace; and", "k": "body" }, { "t": "(i) where any obligation or right under this Agreement is expressed to apply to a Buyer or Seller, such obligation or right shall apply to the Participant only in respect of the Transaction in which such Participant is acting in that capacity, unless expressly stated otherwise.\n\n3.1 Registration and Eligibility", "k": "body" }, { "t": "3.1.1 Any person or legal entity seeking to access or use the Platform shall be required to register with the Marketplace and complete such onboarding and verification process as may be prescribed by the Marketplace from time to time.", "k": "body" }, { "t": "3.1.2 The Participant represents and warrants that it is legally competent and duly authorised to enter into this Agreement and to purchase and/or sell Products through the Platform. Where the Participant is a company, LLP, partnership, firm, trust or other legal entity, the person accepting this Agreement on its behalf represents and warrants that he/she has the necessary authority to bind such entity.", "k": "body" }, { "t": "3.1.3 The Marketplace may, at its sole discretion and subject to Applicable Law, accept, reject, defer or condition any application for registration or access to the Platform, including on the basis of verification results, business profile, Product categories, regulatory requirements, commercial considerations, risk assessment or any other criteria determined by the Marketplace.", "k": "body" }, { "t": "3.1.4 Registration with the Platform shall not, by itself, create any obligation on the Marketplace to accept, facilitate or guarantee any particular Transaction, Order, Quotation, Purchase Order or Sales Order.", "k": "body" }, { "t": "3.1.5 The Marketplace may require a Participant to provide, update or re-submit information and documents at any time for the purpose of onboarding, verification, compliance, risk assessment, continued access to the Platform or participation in particular Products, categories or Transactions.", "k": "body" }, { "t": "3.1.6 The Participant shall ensure that all information and documents provided to the Marketplace, whether at the time of registration or subsequently, are true, accurate, complete, current and not misleading. The Participant shall promptly notify the Marketplace of any material change in such information.", "k": "body" }, { "t": "3.1.7 The Marketplace may restrict a Participant from acting as a Buyer, Seller, or both, or may impose conditions, limits or additional verification requirements on such activities, where reasonably required for compliance, risk management, fraud prevention, operational reasons or protection of Participants and the Platform.", "k": "body" }, { "t": "3.2 GST Verification and Official Communication Details", "k": "h2" }, { "t": "3.2.1 As part of registration, the Participant shall provide its valid Goods and Services Tax Identification Number (“GSTIN”), wherever applicable. The Marketplace may verify the GSTIN through its API, governmental records, authorised third-party services or other available verification mechanisms.", "k": "body" }, { "t": "3.2.2 The Participant represents and warrants that the GSTIN and other information provided by it during registration are true, accurate, complete and belong to the Participant. The Participant shall not use the GSTIN, business identity or credentials of any other person or entity for registration or for carrying out Transactions through the Platform.", "k": "body" }, { "t": "3.2.3 The Participant shall provide and verify a valid mobile telephone number and email address during registration. The verified mobile telephone number and email address recorded against the Participant's Account shall constitute the Participant's official communication details for purposes of communications, notices, alerts, confirmations, Orders, Transactions, payments, settlements, disputes and other matters relating to the Platform, unless otherwise provided under this Agreement.", "k": "body" }, { "t": "3.2.4 The Participant shall be responsible for ensuring continuous access to its registered mobile telephone number and email address and shall promptly update such details through the Platform if they change. The Marketplace shall be entitled to rely upon the latest verified contact details available in the Participant's Account.", "k": "body" }, { "t": "3.2.5 Verification of a GSTIN, mobile telephone number or email address by the Marketplace shall not constitute any representation, warranty, certification or endorsement by the Marketplace regarding the Participant's financial standing, creditworthiness, business conduct, solvency, reputation, Products, quality, capacity or compliance with Applicable Law.", "k": "body" }, { "t": "3.2.6 Where the GSTIN provided by the Participant is found to be invalid, inactive, cancelled, suspended, unverifiable or inconsistent with the information provided by the Participant, the Marketplace may refuse registration, restrict access, suspend buying or selling privileges, hold or restrict Settlement, or take such other action as may be permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "3.2.7 The Marketplace may require the Participant to re-verify its GSTIN, mobile telephone number or email address from time to time, including where the Marketplace reasonably considers such re-verification necessary for security, fraud prevention, compliance or operational purposes.", "k": "body" }, { "t": "3.3 Participant Account and Access Credentials", "k": "h2" }, { "t": "3.3.1 Upon successful registration and completion of the applicable verification process, the Marketplace may create or activate an Account for the Participant through which the Participant may access and use the Platform in accordance with this Agreement and applicable Policies.", "k": "body" }, { "t": "3.3.2 The Participant shall be responsible for maintaining the confidentiality and security of its Account credentials, including passwords, authentication codes, access links and other security credentials associated with the Account.", "k": "body" }, { "t": "3.3.3 The Participant shall not share, transfer, sell, assign, license or otherwise permit any unauthorised person to access or use its Account or Account credentials.", "k": "body" }, { "t": "3.3.4 The Participant shall be responsible for all activities, Orders, Transactions, communications and other actions carried out through its Account, except to the extent the Participant establishes that such activity resulted directly from a security failure attributable to the Marketplace.", "k": "body" }, { "t": "3.3.5 The Participant shall immediately notify the Marketplace if it becomes aware of or reasonably suspects any unauthorised access, misuse, compromise or loss of control of its Account or Account credentials.", "k": "body" }, { "t": "3.3.6 The Marketplace may require additional authentication, verification or security measures before permitting access to the Account or before allowing certain Transactions or other activities through the Platform.", "k": "body" }, { "t": "3.3.7 The Participant shall not create or operate multiple Accounts for the purpose of circumventing any restriction, suspension, limit, penalty, verification requirement or other measure imposed by the Marketplace, unless expressly permitted by the Marketplace.", "k": "body" }, { "t": "3.3.8 The Marketplace may suspend, restrict or disable an Account, temporarily or permanently, where it reasonably believes that the Account has been compromised, misused, accessed without authorisation, used in violation of this Agreement or Applicable Law, or presents a security, fraud or other material risk to the Marketplace or other Participants.", "k": "body" }, { "t": "3.4 Participant Authority and Responsibility", "k": "h2" }, { "t": "3.4.1 The Participant represents and warrants that all information provided by it to the Marketplace is true, accurate and complete and that it has the legal right and authority to enter into this Agreement and use the Platform.", "k": "body" }, { "t": "3.4.2 Where the Participant acts through any employee, representative, agent or other person using or accessing its Account, the Participant shall be responsible for the acts and omissions of such person in connection with the Account and the Platform.", "k": "body" }, { "t": "3.4.3 The Participant shall ensure that all Orders, Purchase Orders, Sales Orders, Quotations, Transaction confirmations, payment instructions and other communications or commitments made through its Account are authorised by the Participant and shall be responsible for the consequences thereof.", "k": "body" }, { "t": "3.4.4 The Participant shall comply with this Agreement, applicable Policies and Applicable Law in relation to all activities carried out through its Account, whether acting as a Buyer, Seller or in any other capacity.", "k": "body" }, { "t": "3.4.5 The Participant shall be solely responsible for determining whether it is legally permitted and commercially authorised to purchase, sell, supply, receive or otherwise deal in any Product through the Platform.", "k": "body" }, { "t": "3.4.6 The Participant shall not use the Platform or its Account for any unlawful, fraudulent, misleading, abusive or unauthorised purpose, or in any manner that may adversely affect the Marketplace, another Participant, any Transaction or the operation or security of the Platform.", "k": "body" }, { "t": "3.5 Buyer and Seller Capacity", "k": "h2" }, { "t": "3.5.1 A Participant may use the Platform as a Buyer, Seller, or both, subject to the features, permissions and conditions applicable to its Account.", "k": "body" }, { "t": "3.5.2 The capacity in which a Participant acts shall be determined separately for each Transaction. A Participant acting as a Seller in one Transaction may act as a Buyer in another Transaction, and neither capacity shall affect the rights or obligations of the Participant in any other Transaction.", "k": "body" }, { "t": "3.5.3 When acting as a Buyer, the Participant shall be responsible for complying with all obligations applicable to a Buyer under this Agreement, the applicable Transaction terms and the relevant Policies.", "k": "body" }, { "t": "3.5.4 When acting as a Seller, the Participant shall be responsible for complying with all obligations applicable to a Seller under this Agreement, the applicable Transaction terms and the relevant Policies.", "k": "body" }, { "t": "3.5.5 The Marketplace may independently enable, restrict, suspend or disable a Participant's ability to act as a Buyer or Seller without necessarily restricting the Participant's other capacity, subject to this Agreement and Applicable Law.", "k": "body" }, { "t": "3.5.6 Nothing in this Agreement shall be interpreted as making a Participant permanently or exclusively a Buyer or Seller. The rights, obligations and liabilities applicable to the Participant shall be determined according to the capacity in which it acts in the relevant Transaction.", "k": "body" }, { "t": "3.6 Participant Information and Account Records", "k": "h2" }, { "t": "3.6.1 The Participant authorises the Marketplace to collect, store, process and use the information provided by the Participant in connection with registration, Account creation, verification, use of the Platform and Transactions, in accordance with this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "3.6.2 The Marketplace may maintain electronic records relating to the Participant's Account, including registration details, verified contact details, GSTIN verification status, Orders, Purchase Orders, Sales Orders, Quotations, Transactions, payments, Wallet entries, Settlements, communications, complaints and other activities carried out through the Platform.", "k": "body" }, { "t": "3.6.3 The Participant acknowledges that Platform Records may be used by the Marketplace for purposes including operating the Platform, processing and administering Transactions, calculating Fees and Settlements, customer support, dispute resolution, fraud prevention, security, compliance, risk management and enforcement of this Agreement.", "k": "body" }, { "t": "3.6.4 The Participant shall be responsible for ensuring that information submitted through its Account remains accurate and up to date and shall promptly correct any material error or discrepancy identified by the Participant.", "k": "body" }, { "t": "3.6.5 Subject to Applicable Law, the Marketplace may retain Participant and Transaction records for such period as the Marketplace considers reasonably necessary for business, legal, regulatory, accounting, tax, dispute resolution, fraud prevention or other legitimate purposes.", "k": "body" }, { "t": "3.7 Platform Access and Availability", "k": "h2" }, { "t": "3.7.1 Subject to this Agreement and applicable Policies, the Marketplace shall provide the Participant with access to the Platform and such Marketplace Services as may be made available to the Participant from time to time.", "k": "body" }, { "t": "3.7.2 The Marketplace may modify, suspend, restrict, discontinue or replace any part of the Platform or any Marketplace Service from time to time, including for maintenance, upgrades, security, technical reasons, regulatory requirements or business reasons.", "k": "body" }, { "t": "3.7.3 The Participant acknowledges that access to the Platform may from time to time be unavailable, interrupted, delayed or restricted due to maintenance, technical issues, telecommunications or internet failures, third-party service failures, security incidents, force majeure events or other circumstances beyond the reasonable control of the Marketplace.", "k": "body" }, { "t": "3.7.4 The Marketplace does not warrant that the Platform or any Marketplace Service will be continuously available, uninterrupted, error-free or suitable for every particular business requirement of the Participant.", "k": "body" }, { "t": "3.7.5 Temporary unavailability or interruption of the Platform shall not, by itself, relieve the Participant of any payment, delivery, contractual or other obligation that has already arisen in connection with a Transaction, except to the extent otherwise expressly provided under this Agreement or Applicable Law.", "k": "body" }, { "t": "3.7.6 The Marketplace shall not be responsible for any failure, delay or interruption caused by the Participant's internet connection, equipment, software, systems, telecommunications provider or any other infrastructure or service not controlled by the Marketplace.", "k": "body" }, { "t": "3.8 Compliance with Platform Policies", "k": "h2" }, { "t": "3.8.1 The Participant shall comply with all applicable Policies issued or made available by the Marketplace in connection with the Platform, Marketplace Services and Transactions.", "k": "body" }, { "t": "3.8.2 The Policies may prescribe operational requirements, procedures, standards, restrictions and guidelines applicable to Participants, including in relation to Products, Orders, Quotations, Purchase Orders, Sales Orders, payments, Wallet, Settlement, returns, cancellations, conduct, fraud prevention, dispute resolution and other activities undertaken through the Platform.", "k": "body" }, { "t": "3.8.3 The Marketplace may introduce, modify, replace or withdraw any Policy from time to time where reasonably required for operational, commercial, security, compliance, regulatory or risk-management purposes.", "k": "body" }, { "t": "3.8.4 The Participant shall be responsible for reviewing and complying with the Policies applicable to its activities on the Platform. Where a Policy conflicts with an express provision of this Agreement, the provisions of this Agreement shall prevail unless the Agreement expressly provides otherwise.", "k": "body" }, { "t": "3.8.5 The Participant's continued use of the Platform after a Policy has been made applicable to the Participant shall constitute acceptance of such Policy, subject to Applicable Law.", "k": "body" }, { "t": "4. PRODUCT LISTING AND PRODUCT INFORMATION", "k": "h1" }, { "t": "4.1 A Participant acting as a Seller may offer Products for sale through the Platform only in accordance with this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "4.2 The Seller shall ensure that all information, specifications, descriptions, images, quantities, availability, Pricing, applicable taxes, delivery terms and other details provided or displayed in relation to its Products are accurate, complete, current and not misleading.", "k": "body" }, { "t": "4.3 The Seller shall be solely responsible for ensuring that the Products offered through the Platform are genuine, lawful, saleable and fit for the purpose for which they are ordinarily intended or expressly represented, and comply with all Applicable Laws, standards, licences, registrations and regulatory requirements applicable to such Products.", "k": "body" }, { "t": "4.4 The Seller shall not list, offer or sell any Product that is prohibited by Applicable Law or by the Marketplace's applicable Policies.", "k": "body" }, { "t": "4.5 The Seller shall maintain sufficient availability of Products represented as available for sale and shall promptly update the Platform where any Product becomes unavailable, discontinued, restricted or otherwise cannot be supplied in accordance with the applicable Transaction terms.", "k": "body" }, { "t": "4.6 The Marketplace may review, approve, reject, restrict, remove or suspend any Product listing where it reasonably considers that the Product or its listing may violate this Agreement, applicable Policies, Applicable Law, or may create legal, regulatory, safety, commercial or reputational risk.", "k": "body" }, { "t": "4.7 Any review, approval, publication or continued availability of a Product listing by the Marketplace shall not constitute a representation, warranty, certification or endorsement by the Marketplace regarding the legality, authenticity, quality, safety, suitability or fitness of the Product.", "k": "body" }, { "t": "4.8 The Seller shall be solely responsible for obtaining and maintaining all licences, registrations, permissions, certifications and approvals required for the manufacture, possession, storage, marketing, distribution, sale or supply of its Products, wherever applicable.", "k": "body" }, { "t": "4.2 Product Authenticity, Quality and Compliance", "k": "h2" }, { "t": "4.2.1 The Seller shall ensure that every Product offered, listed, supplied or sold through the Platform is genuine, authentic and conforms in all respects to the description, specifications, grade, quality, quantity, brand, model, batch, packaging and other particulars represented by the Seller on the Platform or otherwise agreed with the Buyer.", "k": "body" }, { "t": "4.2.2 The Seller shall not offer or supply any counterfeit, adulterated, expired, substituted, damaged, defective, tampered, unlawfully sourced or otherwise non-conforming Product through the Platform.", "k": "body" }, { "t": "4.2.3 The Seller shall ensure that Products supplied to a Buyer are properly packed, labelled, stored and handled in accordance with the nature of the Product, Applicable Law, applicable industry requirements and the manufacturer's or applicable regulatory requirements.", "k": "body" }, { "t": "4.2.4 Where a Product is subject to any applicable standard, certification, licence, specification, safety requirement or regulatory requirement, the Seller shall ensure that such Product complies with the same and shall maintain all records and supporting evidence required under Applicable Law.", "k": "body" }, { "t": "4.2.5 The Seller shall be solely responsible for any claim, loss, liability, penalty, damage, recall, rejection or other consequence arising from any defect, shortage, adulteration, counterfeit nature, misrepresentation, non-conformity or legal or regulatory violation relating to a Product supplied by the Seller.", "k": "body" }, { "t": "4.2.6 The Marketplace shall have no obligation to independently inspect, test, authenticate, certify or verify the quality, quantity, specifications, condition, origin or legality of any Product supplied by a Seller, unless the Marketplace expressly agrees in writing to perform a particular verification or inspection.", "k": "body" }, { "t": "4.2.7 Any inspection, verification, review or information made available by the Marketplace in relation to a Product shall not relieve the Seller of any obligation or liability relating to such Product.", "k": "body" }, { "t": "4.2.8 Where the Marketplace receives a complaint, notice or information indicating that a Product may be counterfeit, defective, unsafe, non-conforming or otherwise in breach of this Agreement, Applicable Law or applicable Policies, the Marketplace may suspend, restrict or remove the relevant listing or Transaction and take such other action as it reasonably considers necessary.", "k": "body" }, { "t": "4.3 Product Listing and Commercial Information", "k": "h2" }, { "t": "4.3.1 The Seller shall provide all information necessary for a Buyer to reasonably understand the Product and the applicable commercial terms before placing an Order, including, where applicable, Product name, description, specifications, grade, brand, model, quantity, unit of measurement, Pricing, applicable taxes, availability, delivery terms, payment terms and other material particulars.", "k": "body" }, { "t": "4.3.2 The Seller shall ensure that the Pricing and other commercial information displayed or communicated through the Platform accurately reflects the terms on which the Seller is willing to supply the Product, subject to any conditions, validity period or minimum order requirements expressly stated by the Seller.", "k": "body" }, { "t": "4.3.3 Where a Quotation is provided by the Seller, the Seller shall clearly specify the validity period of such Quotation and any material conditions attached to it. A Quotation shall not be treated as a confirmed Transaction unless and until accepted or otherwise confirmed in accordance with the applicable Platform process or agreed commercial terms.", "k": "body" }, { "t": "4.3.4 The Seller shall clearly indicate whether the quoted Product Pricing is inclusive or exclusive of Transportation/freight charges, wherever such option is provided by the Platform.", "k": "body" }, { "t": "4.3.5 Unless expressly agreed otherwise between the Buyer and Seller, the Marketplace shall not be responsible for determining or negotiating Product Pricing, discounts, credit terms, Transportation charges or other commercial terms between the Buyer and Seller.", "k": "body" }, { "t": "4.3.6 The Marketplace may display, organise, standardise or otherwise present Product and commercial information provided by the Seller for the purpose of operating the Platform, without assuming responsibility for the accuracy or completeness of such information.", "k": "body" }, { "t": "4.3.7 The Seller shall promptly correct or update any Product information that becomes inaccurate, misleading, unavailable or otherwise inconsistent with the actual Product or applicable commercial terms.", "k": "body" }, { "t": "4.4 Prohibited and Restricted Products", "k": "h2" }, { "t": "4.4.1 The Seller shall not list, offer, advertise, sell or supply through the Platform any Product that is prohibited under Applicable Law or under the Marketplace's applicable Policies.", "k": "body" }, { "t": "4.4.2 Without limiting the foregoing, the Marketplace may prohibit or restrict Products that are counterfeit, stolen, unlawfully sourced, adulterated, unsafe, expired, recalled, hazardous, restricted, or otherwise subject to specific licensing, regulatory or statutory requirements that have not been satisfied by the Seller.", "k": "body" }, { "t": "4.4.3 Where the sale, possession, storage, transportation or supply of a Product requires any licence, registration, permit, certification, authorisation or other regulatory approval, the Seller shall obtain and maintain the same and shall comply with all conditions attached thereto.", "k": "body" }, { "t": "4.4.4 The Marketplace may, at its discretion, designate certain Product categories as restricted categories and may impose additional conditions, eligibility requirements, transaction limits or approval requirements for such categories.", "k": "body" }, { "t": "4.4.5 The Marketplace may immediately remove, block or suspend any listing or Transaction involving a Product that it reasonably believes may be prohibited, restricted, unlawful, unsafe or otherwise in violation of this Agreement, applicable Policies or Applicable Law.", "k": "body" }, { "t": "4.4.6 The Seller shall remain solely responsible for the legality, regulatory compliance, sourcing, possession, storage, handling, sale and supply of all Products offered or supplied by it, notwithstanding any listing, publication, approval or continued availability of such Products on the Platform.", "k": "body" }, { "t": "This establishes the general restriction framework. We can later put the actual category-wise prohibited/restricted Product list into a Policy or Annexure, rather than making the main agreement unnecessarily rigid.", "k": "body" }, { "t": "4.5 Product Availability and Inventory", "k": "h2" }, { "t": "4.5.1 The Seller shall ensure that the quantity and availability of each Product represented on the Platform accurately reflects the quantity that the Seller is reasonably able and willing to supply in accordance with the applicable Transaction terms.", "k": "body" }, { "t": "4.5.2 The Seller shall promptly update or correct the availability, quantity or status of any Product where the Product becomes unavailable, insufficient in quantity, discontinued, restricted or otherwise cannot be supplied as represented.", "k": "body" }, { "t": "4.5.3 The Seller shall not accept or confirm an Order for a quantity of Product that it does not reasonably expect to be able to supply in accordance with the agreed terms, except where the Buyer expressly agrees to the revised quantity or terms.", "k": "body" }, { "t": "4.5.4 Where a Seller is unable to fulfil an accepted Order due to shortage, non-availability or any other reason attributable to the Seller, the Seller shall promptly inform the Buyer and the Marketplace and shall comply with the applicable cancellation, refund, replacement or other procedures prescribed under the Platform's Policies.", "k": "body" }, { "t": "4.5.5 The Marketplace shall not be responsible for maintaining, verifying or replenishing the Seller's inventory and shall not be liable for any shortage, over-selling, stock discrepancy or inability of the Seller to fulfil an Order.", "k": "body" }, { "t": "4.5.6 The Marketplace may impose quantity, category, value or other transaction limits where reasonably required for operational, risk-management, compliance, fraud-prevention or other legitimate purposes.", "k": "body" }, { "t": "4.6 Packaging, Labelling and Dispatch", "k": "h2" }, { "t": "4.6.1 The Seller shall ensure that all Products supplied through the Platform are appropriately packaged, sealed, labelled and prepared for dispatch in accordance with the nature of the Product, Applicable Law, applicable industry standards and the commercial terms agreed with the Buyer.", "k": "body" }, { "t": "4.6.2 The Seller shall ensure that the quantity, unit of measurement, batch or lot details, Product identification and other particulars stated on the packaging, label, invoice or accompanying documents, wherever applicable, correspond with the Products actually supplied.", "k": "body" }, { "t": "4.6.3 The Seller shall take reasonable precautions to prevent damage, contamination, leakage, deterioration, tampering, shortage or substitution of Products before the Products are handed over to the Buyer or the transportation provider, as applicable.", "k": "body" }, { "t": "4.6.4 The Seller shall dispatch Products within the time period agreed with the Buyer or specified in the applicable Order, Sales Order or other Transaction terms.", "k": "body" }, { "t": "4.6.5 Where the Seller is responsible for dispatch, the Seller shall provide or update such dispatch details and supporting information through the Platform as may reasonably be required for recording and administering the Transaction.", "k": "body" }, { "t": "4.6.6 The Seller shall be responsible for any loss, damage, shortage, delay or other issue occurring before the Products are handed over in accordance with the applicable agreed delivery or Transportation terms, to the extent attributable to the Seller.", "k": "body" }, { "t": "4.6.7 The Marketplace does not undertake any responsibility for packaging, labelling, loading, dispatch or handover of Products by the Seller, unless the Marketplace expressly agrees in writing to undertake a specific responsibility.", "k": "body" }, { "t": "4.7 Transportation and Delivery", "k": "h2" }, { "t": "4.7.1 The Seller may, through the Platform or the applicable Transaction terms, specify whether the quoted Product Pricing is inclusive of Transportation/freight charges or exclusive of Transportation/freight charges, as applicable.", "k": "body" }, { "t": "4.7.2 Unless expressly agreed otherwise between the Buyer and Seller, the responsibility for arranging Transportation shall rest entirely with the Buyer or Seller, as agreed between them, and the Marketplace shall not be responsible for arranging, providing or managing Transportation.", "k": "body" }, { "t": "4.7.3 Where Transportation is arranged by the Seller, the Seller shall be responsible for coordinating the dispatch and handover of the Products to the transporter or other carrier in accordance with the agreed Transaction terms.", "k": "body" }, { "t": "4.7.4 Where Transportation is arranged by the Buyer, the Buyer shall be responsible for coordinating the collection, carriage and delivery of the Products from the Seller in accordance with the agreed Transaction terms.", "k": "body" }, { "t": "4.7.5 The Buyer and Seller shall independently agree upon all applicable Transportation terms, including transporter or carrier, freight charges, loading and unloading responsibilities, delivery destination, delivery timelines, transit risk and other related matters.", "k": "body" }, { "t": "4.7.6 The Marketplace shall not be responsible or liable for the selection, appointment, acts or omissions of any transporter or carrier appointed by the Buyer or Seller, or for any loss, damage, shortage, delay, deterioration, accident or other event occurring during Transportation.", "k": "body" }, { "t": "4.7.7 Any indication or display on the Platform regarding Transportation or freight charges shall be for recording or communicating the commercial terms of the Transaction and shall not, by itself, constitute the Marketplace as a transporter, carrier, logistics provider, agent or guarantor of delivery.", "k": "body" }, { "t": "4.7.8 The Marketplace may facilitate communication or exchange of Transportation-related information between the Buyer and Seller where such functionality is available on the Platform; however, such facilitation shall not transfer responsibility for Transportation to the Marketplace.", "k": "body" }, { "t": "4.8 Inspection, Acceptance and Product Claims", "k": "h2" }, { "t": "4.8.1 The Buyer shall, upon receipt of the Products, inspect the Products within a reasonable period for quantity, visible damage, packaging condition and conformity with the applicable Order, PO, SO, Quotation or other agreed Transaction terms.", "k": "body" }, { "t": "4.8.2 The Buyer shall promptly notify the Seller of any shortage, visible damage, incorrect Product, apparent defect, non-conformity or other discrepancy identified during or after such inspection, together with reasonable supporting details or evidence where available.", "k": "body" }, { "t": "4.8.3 Any claim relating to Product quality, quantity, specifications, condition, authenticity, damage, shortage or other non-conformity shall be raised by the Buyer against the Seller, unless the Marketplace has expressly undertaken responsibility for the relevant matter in writing.", "k": "body" }, { "t": "4.8.4 The Seller shall reasonably cooperate with the Buyer in investigating and resolving any Product-related claim and shall provide such information or supporting documents as may reasonably be required.", "k": "body" }, { "t": "4.8.5 The Marketplace may facilitate communication, documentation or dispute assistance between the Buyer and Seller in relation to a Product claim where such functionality or assistance is available, but shall not thereby become responsible for the Product or the Seller's obligations.", "k": "body" }, { "t": "4.8.6 The Marketplace may, where reasonably necessary, place a Transaction, Settlement or related amount on hold, restrict access to the relevant Product or Transaction, or take other temporary measures pending investigation of a material complaint, suspected non-conformity, fraud, regulatory issue or breach of this Agreement or applicable Policies.", "k": "body" }, { "t": "4.8.7 Nothing in this Section limits any rights or remedies available to the Buyer or Seller under the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "4.9 Returns, Replacements and Refunds", "k": "h2" }, { "t": "4.9.1 Returns, replacements, refunds or other remedies relating to Products shall be governed by the applicable Transaction terms, the agreed commercial terms between the Buyer and Seller, and the applicable Policies of the Marketplace.", "k": "body" }, { "t": "4.9.2 A Buyer shall not return Products or seek replacement or refund except in accordance with the applicable return, replacement or refund terms, or where otherwise required under Applicable Law.", "k": "body" }, { "t": "4.9.3 Where a return, replacement or refund is agreed or required, the Buyer and Seller shall cooperate in completing the applicable process, including providing necessary information, documents, photographs, delivery records or other reasonable evidence.", "k": "body" }, { "t": "4.9.4 Unless expressly agreed otherwise, the Seller shall be responsible for any return, replacement, refund or related cost arising from defective, damaged, incorrect, counterfeit, short-supplied or otherwise non-conforming Products attributable to the Seller.", "k": "body" }, { "t": "4.9.5 The Marketplace may facilitate the processing or recording of returns, replacements, refunds or adjustments through the Platform, including making corresponding adjustments to the relevant Transaction, Wallet or Settlement.", "k": "body" }, { "t": "4.9.6 The Marketplace may withhold, adjust or recover amounts otherwise payable to a Participant where reasonably required to give effect to an agreed or applicable refund, return, replacement, cancellation, claim, adjustment or other Transaction-related liability.", "k": "body" }, { "t": "4.9.7 The Marketplace does not independently guarantee or assume responsibility for the quality, condition, suitability, returnability or replacement of any Product and shall not be responsible for any refund or replacement obligation of the Buyer or Seller, except to the extent expressly undertaken by the Marketplace in writing or required under Applicable Law.", "k": "body" }, { "t": "4.10 Product-Related Documentation and Records", "k": "h2" }, { "t": "4.10.1 The Seller shall provide, where applicable, all invoices, delivery documents, test certificates, certificates of analysis, warranty documents, batch or lot details, statutory declarations, licences, product literature and other documents required under the applicable Transaction terms, Policies or Applicable Law.", "k": "body" }, { "t": "4.10.2 The Seller shall ensure that all documents and information accompanying the Products are accurate, complete, authentic and correspond to the Products actually supplied to the Buyer.", "k": "body" }, { "t": "4.10.3 Where a Product is required under Applicable Law to carry specific labels, markings, declarations, warnings, instructions or other information, the Seller shall ensure that such requirements are duly complied with before dispatch.", "k": "body" }, { "t": "4.10.4 The Seller shall retain such records and documents relating to Products and Transactions as may be required under Applicable Law and shall provide reasonable supporting information to the Marketplace where required for verification, dispute resolution, compliance, investigation or other legitimate Platform purposes.", "k": "body" }, { "t": "4.10.5 The Marketplace may request or obtain copies of relevant Product-related documents from the Seller or Buyer where reasonably necessary for Transaction administration, verification, dispute resolution, fraud prevention, regulatory compliance or enforcement of this Agreement or applicable Policies.", "k": "body" }, { "t": "4.10.6 Submission, display, storage or processing of any Product-related document by the Marketplace shall not constitute verification, certification, approval or endorsement of the authenticity, accuracy, legality, quality or compliance of the Product or such document, unless expressly stated otherwise in writing by the Marketplace.", "k": "body" }, { "t": "4.11 Product Recalls and Safety Issues", "k": "h2" }, { "t": "4.11.1 The Seller shall promptly notify the Marketplace and the affected Buyer(s) if any Product supplied through the Platform becomes subject to a recall, withdrawal, safety warning, regulatory restriction, prohibition, investigation or other material safety or compliance concern.", "k": "body" }, { "t": "4.11.2 The Seller shall promptly take all actions required under Applicable Law and the applicable Transaction terms in relation to any such recall, withdrawal, restriction or safety issue, including notifying affected parties and arranging return, replacement, withdrawal or other appropriate corrective action where required.", "k": "body" }, { "t": "4.11.3 The Marketplace may, where reasonably necessary, suspend or remove the affected Product listing, restrict or suspend relevant Orders or Transactions, notify affected Participants, place relevant amounts on hold, or take other measures reasonably required to protect Participants, the Platform or comply with Applicable Law.", "k": "body" }, { "t": "4.11.4 The Seller shall be solely responsible for any costs, losses, claims, penalties, liabilities, recalls, replacements, refunds or other consequences arising from a Product recall, safety issue or regulatory action attributable to the Seller or the Product.", "k": "body" }, { "t": "4.11.5 The Marketplace's involvement in or facilitation of any recall, withdrawal, investigation or corrective action shall not constitute an assumption of responsibility for the Product or the Seller's obligations.", "k": "body" }, { "t": "4.12 Product Warranty and Manufacturer Responsibility", "k": "h2" }, { "t": "4.12.1 Where any Product is subject to a manufacturer's warranty, Seller warranty, guarantee or other assurance, the Seller shall clearly disclose the applicable warranty or guarantee terms to the Buyer where such disclosure is relevant to the Transaction.", "k": "body" }, { "t": "4.12.2 Unless expressly stated otherwise in writing, any warranty, guarantee or assurance relating to a Product shall be provided and honoured by the Seller or the applicable manufacturer or authorised party, and not by the Marketplace.", "k": "body" }, { "t": "4.12.3 The Seller shall be responsible for communicating applicable warranty conditions, exclusions, validity periods, claim procedures and other material warranty terms to the Buyer.", "k": "body" }, { "t": "4.12.4 The Marketplace may facilitate communication between the Buyer and Seller regarding warranty or guarantee claims but shall not be responsible for determining whether a warranty claim is valid or for fulfilling any warranty or guarantee obligation.", "k": "body" }, { "t": "4.12.5 Nothing in this Agreement shall prevent a Buyer from exercising any rights or remedies available against the Seller, manufacturer or other responsible party under the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "4.12.6 The Marketplace shall not be deemed to have provided, endorsed or guaranteed any warranty, guarantee, performance representation or after-sales commitment relating to a Product merely because such information is displayed, communicated or recorded through the Platform.", "k": "body" }, { "t": "4.13 Product Information and Intellectual Property", "k": "h2" }, { "t": "4.13.1 The Seller represents and warrants that it has the necessary rights, permissions and authorisations to offer, advertise, market, distribute and sell the Products and to use or provide any trademarks, brand names, product images, descriptions, specifications, technical information or other materials submitted or displayed by it through the Platform.", "k": "body" }, { "t": "4.13.2 The Seller shall not upload, display or provide through the Platform any Product information or other material that infringes or is likely to infringe any intellectual property, proprietary, contractual, privacy or other rights of any third party.", "k": "body" }, { "t": "4.13.3 The Seller grants the Marketplace a non-exclusive, royalty-free, worldwide licence, during the period in which the relevant information or Product is available through the Platform, to host, store, reproduce, display, communicate, format, adapt and otherwise use the Product information and related materials solely to operate, provide, promote and improve the Platform and Marketplace Services.", "k": "body" }, { "t": "4.13.4 The licence under this Section includes the right of the Marketplace to use Product names, descriptions, specifications, images, trademarks and other Product-related information for displaying and facilitating Transactions through the Platform.", "k": "body" }, { "t": "4.13.5 The Seller shall be solely responsible for any claim, loss, liability, cost or proceeding arising from any allegation that a Product or any Product-related information or material supplied by the Seller infringes the rights of a third party.", "k": "body" }, { "t": "4.13.6 The Marketplace may remove, disable, modify or restrict access to any Product information or material where it reasonably believes that such material may violate this Agreement, applicable Policies, Applicable Law or the rights of any third party.", "k": "body" }, { "t": "4.14 Seller Indemnity for Product-Related Matters", "k": "h2" }, { "t": "4.14.1 The Seller shall be solely responsible for, and shall indemnify and hold harmless the Marketplace, its directors, officers, employees, representatives and agents from and against any claims, losses, damages, liabilities, penalties, costs and expenses arising out of or relating to:", "k": "body" }, { "t": "(a) any defect, deficiency, shortage, damage, adulteration, contamination, counterfeit, substitution or non-conformity of any Product supplied by the Seller;", "k": "body" }, { "t": "(b) any breach by the Seller of its representations, warranties or obligations relating to Products, Product information, packaging, labelling, storage, dispatch or supply;", "k": "body" }, { "t": "(c) any violation of Applicable Law, regulatory requirement, licence, permit, certification or standard applicable to the Product or its manufacture, possession, storage, distribution or sale by the Seller;", "k": "body" }, { "t": "(d) any infringement or alleged infringement of intellectual property or other proprietary rights arising from the Products or materials supplied by the Seller; or", "k": "body" }, { "t": "(e) any recall, withdrawal, safety issue, regulatory action or other Product-related claim attributable to the Seller or the Products supplied by the Seller.", "k": "body" }, { "t": "4.14.2 The obligations under this Section shall apply notwithstanding that the relevant Product was listed, displayed, processed or otherwise made available through the Platform.", "k": "body" }, { "t": "4.14.3 The Marketplace may require the Seller to cooperate in defending, investigating or resolving any Product-related claim and to provide such information, documents and assistance as may reasonably be required for that purpose.", "k": "body" }, { "t": "4.15 Marketplace Role and Product Responsibility", "k": "h2" }, { "t": "4.15.1 The Marketplace operates the Platform as a technology-enabled B2B marketplace that facilitates interactions and Transactions between Participants. Unless expressly agreed otherwise in writing, the Marketplace is not the manufacturer, owner, Seller, Buyer, distributor, dealer, transporter or agent of any Product merely by providing the Platform or Marketplace Services.", "k": "body" }, { "t": "4.15.2 The contract of sale or supply for a Product is between the Buyer and Seller participating in the relevant Transaction. The Seller remains responsible for supplying the Product in accordance with the applicable Order, PO, SO, Quotation and other agreed commercial terms, and the Buyer remains responsible for its obligations as Buyer.", "k": "body" }, { "t": "4.15.3 The Marketplace does not acquire ownership, title or possession of Products merely because Products are listed, ordered, invoiced, paid for, recorded or otherwise processed through the Platform, except where the Marketplace expressly agrees otherwise in writing.", "k": "body" }, { "t": "4.15.4 The Marketplace does not guarantee or warrant the availability, quality, authenticity, legality, safety, suitability, merchantability, fitness, performance or conformity of any Product offered or supplied by a Seller.", "k": "body" }, { "t": "4.15.5 The Marketplace may provide technology, communication, verification, record-keeping, payment facilitation, Settlement, dispute assistance and other Marketplace Services, but such services shall not make the Marketplace responsible for the underlying Product or the commercial obligations of the Buyer or Seller.", "k": "body" }, { "t": "4.15.6 Nothing in this Agreement shall be construed as creating a partnership, joint venture, agency, employment, fiduciary or other similar relationship between the Marketplace and any Participant, Buyer or Seller, except to the limited extent expressly stated in this Agreement.", "k": "body" }, { "t": "4.16 Product-Related Disputes", "k": "h2" }, { "t": "4.16.1 Any dispute, claim or disagreement between a Buyer and Seller concerning the Product, including its quality, quantity, specifications, authenticity, condition, pricing, delivery, shortage, damage, warranty, return, replacement or refund, shall primarily be resolved between the Buyer and Seller in accordance with their applicable Transaction terms.", "k": "body" }, { "t": "4.16.2 The Marketplace may, where requested or where it considers reasonably necessary, facilitate communication between the Buyer and Seller and provide reasonable assistance in reviewing Platform Records and Transaction information relevant to the dispute.", "k": "body" }, { "t": "4.16.3 The Marketplace may request information, documents, photographs, delivery records, invoices, communications or other evidence from either Party for the purpose of reviewing or facilitating resolution of a Product-related dispute.", "k": "body" }, { "t": "4.16.4 Any assistance, review or facilitation provided by the Marketplace shall not constitute an admission of liability, determination that either Party is at fault, or assumption by the Marketplace of any obligation arising from the underlying Transaction.", "k": "body" }, { "t": "4.16.5 Where the Parties are unable to resolve a Product-related dispute, the dispute shall be dealt with in accordance with the dispute resolution provisions of this Agreement, without prejudice to any rights or remedies available under Applicable Law.", "k": "body" }, { "t": "4.17 Seller's Continuing Responsibility", "k": "h2" }, { "t": "4.17.1 The Seller's obligations and responsibilities under this Section 4 shall continue notwithstanding the listing, sale, dispatch, delivery, payment, Settlement, return or completion of any Transaction.", "k": "body" }, { "t": "4.17.2 The Seller shall remain responsible for Products supplied through the Platform to the extent any claim, defect, non-conformity, regulatory issue, warranty obligation, recall, intellectual property claim or other liability relates to the Seller or the Products supplied by the Seller.", "k": "body" }, { "t": "4.17.3 Completion of a Transaction or Settlement of amounts through the Platform shall not, by itself, release the Seller from any obligation or liability arising under the applicable Transaction terms, this Agreement or Applicable Law.", "k": "body" }, { "t": "4.17.4 The Marketplace may retain or use relevant Platform Records after completion of a Transaction for purposes including dispute resolution, claims, refunds, adjustments, compliance, fraud prevention, audit, accounting, taxation and enforcement of this Agreement, subject to Applicable Law.", "k": "body" }, { "t": "4.17.5 Nothing in this Section shall make the Marketplace responsible for any obligation that is expressly allocated to the Buyer or Seller under this Agreement or the applicable Transaction terms.", "k": "body" }, { "t": "5. ORDERS, QUOTATIONS AND TRANSACTIONS", "k": "h1" }, { "t": "5.1 Quotations and Commercial Offers", "k": "h2" }, { "t": "5.1.1 A Seller may submit or publish Quotations through the Platform specifying the Products offered, Pricing, quantity, validity period and other applicable commercial terms.", "k": "body" }, { "t": "5.1.2 The Seller shall ensure that each Quotation is accurate, complete, current and capable of being fulfilled in accordance with the terms stated therein.", "k": "body" }, { "t": "5.1.3 A Quotation shall remain valid only for the period and subject to the conditions specified by the Seller. If no validity period is specified, the Quotation may be treated as subject to availability and Seller confirmation.", "k": "body" }, { "t": "5.1.4 A Quotation shall not, by itself, constitute a confirmed Transaction unless and until it is accepted or otherwise confirmed in accordance with the applicable Platform process or agreed commercial terms.", "k": "body" }, { "t": "5.1.5 The Seller may specify minimum order quantities, delivery conditions, payment terms, credit terms, Transportation terms and other commercial conditions applicable to a Quotation.", "k": "body" }, { "t": "5.1.6 The Marketplace may display, organise, transmit or otherwise facilitate Quotations between Participants but shall not be responsible for the accuracy, validity, availability or fulfilment of any Quotation submitted by a Seller.", "k": "body" }, { "t": "5.1.7 Where a Buyer accepts a Quotation or proceeds with an Order based on a Quotation, the resulting Transaction shall be governed by the applicable confirmed commercial terms, subject to this Agreement and the applicable Policies.", "k": "body" }, { "t": "5.1.8 The Seller shall not submit or maintain a Quotation that it knows, or reasonably should know, cannot be fulfilled in accordance with the stated commercial terms.", "k": "body" }, { "t": "5.2 Purchase Orders and Sales Orders", "k": "h2" }, { "t": "5.2.1 A Buyer may place a Purchase Order (“PO”) through the Platform in response to a Quotation or other commercial offer made by a Seller, specifying the Products, quantities, Pricing, delivery requirements, payment terms and other applicable commercial terms.", "k": "body" }, { "t": "5.2.2 The Seller may issue or generate a Sales Order (“SO”) through or in connection with the Platform confirming the Products and commercial terms that the Seller agrees to supply.", "k": "body" }, { "t": "5.2.3 A PO submitted by a Buyer shall constitute a request or offer to purchase the specified Products and shall not, by itself, constitute a confirmed Transaction unless accepted or confirmed by the Seller in accordance with the applicable Platform process or agreed commercial terms.", "k": "body" }, { "t": "5.2.4 An SO issued or generated by the Seller shall constitute confirmation of the Seller's agreement to supply the Products only to the extent and subject to the terms stated therein and otherwise applicable to the Transaction.", "k": "body" }, { "t": "5.2.5 The Buyer and Seller shall review the applicable PO, SO, Quotation and other Transaction details before accepting or confirming the Transaction and shall promptly notify the other Party of any material discrepancy.", "k": "body" }, { "t": "5.2.6 Once a Transaction is confirmed in accordance with the applicable Platform process or agreed commercial terms, the Buyer and Seller shall be bound by the applicable commercial terms, subject to this Agreement, the applicable Policies and Applicable Law.", "k": "body" }, { "t": "5.2.7 The Marketplace may record, generate, transmit or display POs, SOs and related Transaction documents through the Platform for operational and record-keeping purposes.", "k": "body" }, { "t": "5.2.8 The Marketplace shall not be responsible for any discrepancy, error, omission or unauthorised commitment contained in a PO or SO arising from information submitted by the Buyer or Seller, except to the extent directly caused by an error attributable to the Marketplace.", "k": "body" }, { "t": "5.3 Order Confirmation and Transaction Formation", "k": "h2" }, { "t": "5.3.1 A Transaction shall be considered confirmed when the Buyer and Seller have completed the applicable acceptance, confirmation or order process prescribed through the Platform or otherwise agreed between them.", "k": "body" }, { "t": "5.3.2 The Platform may generate or record an Order confirmation or other electronic record identifying the relevant Buyer, Seller, Products, quantities, Pricing, applicable taxes, Transportation terms, payment terms and other material Transaction details.", "k": "body" }, { "t": "5.3.3 The Buyer and Seller shall be responsible for reviewing the Transaction details before confirmation and shall be deemed to have accepted the recorded commercial terms upon confirmation, subject to any express conditions stated in the applicable PO, SO, Quotation or other Transaction record.", "k": "body" }, { "t": "5.3.4 Where the Buyer and Seller have agreed different commercial terms outside the Platform, they shall ensure that such terms are accurately communicated or recorded through the Platform where required for processing, Settlement, compliance or record-keeping.", "k": "body" }, { "t": "5.3.5 The Marketplace may rely on the Transaction details recorded through the Platform for purposes of processing Orders, calculating Fees, maintaining Platform Records, administering Wallet and Settlement and providing Marketplace Services.", "k": "body" }, { "t": "5.3.6 The Marketplace does not guarantee that a Transaction will be completed, supplied, delivered or paid merely because an Order has been placed or recorded on the Platform. The Buyer and Seller remain responsible for performing their respective obligations under the confirmed Transaction.", "k": "body" }, { "t": "5.3.7 Any amendment, cancellation or modification of a confirmed Transaction shall be subject to the applicable Transaction terms, the consent or approval required from the Buyer or Seller, and the applicable Platform procedures and Policies.", "k": "body" }, { "t": "5.4 Order Acceptance, Rejection and Cancellation", "k": "h2" }, { "t": "5.4.1 A Seller may accept, reject or conditionally accept a Buyer's Order in accordance with the applicable Quotation, commercial terms, Platform process and Policies.", "k": "body" }, { "t": "5.4.2 A Seller shall not reject or cancel an accepted Order in a manner that is contrary to the agreed Transaction terms, except where permitted under this Agreement, applicable Policies, or Applicable Law.", "k": "body" }, { "t": "5.4.3 A Buyer may request cancellation of an Order before fulfilment, subject to the applicable Transaction terms, Seller's acceptance where required, and any applicable cancellation charges, deductions or other consequences.", "k": "body" }, { "t": "5.4.4 The Marketplace may permit or process cancellation of an Order where required by the Platform process, applicable Policies, mutual agreement between Buyer and Seller, non-availability of Products, failure to fulfil, suspected fraud, regulatory concerns, or other legitimate operational or compliance reasons.", "k": "body" }, { "t": "5.4.5 Where an Order is cancelled after any payment, credit, Fee, adjustment or other amount has been recorded, the resulting refund, adjustment, deduction or Settlement shall be processed in accordance with the applicable Transaction terms and Policies.", "k": "body" }, { "t": "5.4.6 The Marketplace may suspend, restrict or cancel an Order where it reasonably believes that processing or completing the Order may violate this Agreement, applicable Policies or Applicable Law, or may expose the Marketplace or Participants to material fraud, security, regulatory or other risk.", "k": "body" }, { "t": "5.4.7 Cancellation or rejection of an Order shall not affect any rights, liabilities, Fees, penalties, claims or obligations that accrued before such cancellation or rejection.", "k": "body" }, { "t": "5.5 Changes to Confirmed Orders", "k": "h2" }, { "t": "5.5.1 Any change to the Products, quantity, Pricing, delivery terms, payment terms, credit terms, Transportation terms or other material commercial terms of a confirmed Order shall be subject to the consent or confirmation required from the Buyer and Seller under the applicable Transaction terms and Platform process.", "k": "body" }, { "t": "5.5.2 A Participant requesting any change to a confirmed Order shall communicate the proposed change through the Platform or through another agreed communication channel and shall provide sufficient details for the other Party to evaluate the proposed change.", "k": "body" }, { "t": "5.5.3 No proposed change shall be binding on the other Party unless accepted or confirmed in accordance with the applicable Platform process or agreed Transaction terms.", "k": "body" }, { "t": "5.5.4 Where a change is accepted, the Marketplace may update or record the revised Order, PO, SO or other Transaction details on the Platform, and the revised details may be used for subsequent processing, Fees, Settlement and Platform Records.", "k": "body" }, { "t": "5.5.5 The Marketplace shall not be responsible for any loss, cost, delay or other consequence arising from a change requested, accepted or implemented by the Buyer or Seller, except to the extent directly caused by the Marketplace's failure to accurately record an accepted change.", "k": "body" }, { "t": "5.5.6 Any change to a confirmed Order shall not affect rights, liabilities, Fees, penalties, claims or obligations that accrued before the effective date of such change, unless expressly agreed otherwise by the affected Parties.", "k": "body" }, { "t": "5.6 Transaction Records and Electronic Confirmation", "k": "h2" }, { "t": "5.6.1 The Buyer and Seller acknowledge that Orders, POs, SOs, Quotations, confirmations, communications and other Transaction-related records generated, submitted, accepted or maintained through the Platform may be recorded electronically as part of the Platform Records.", "k": "body" }, { "t": "5.6.2 The Buyer and Seller agree that electronic records maintained by the Marketplace may be used as evidence of the relevant instructions, communications, confirmations, Transactions and other activities undertaken through the Platform, subject to Applicable Law.", "k": "body" }, { "t": "5.6.3 A Participant shall promptly review Transaction information and notify the Marketplace of any material error, discrepancy or unauthorised activity identified in the Platform Records.", "k": "body" }, { "t": "5.6.4 Unless disputed by a Participant within a reasonable period after becoming aware of the relevant record, the Marketplace may rely on the information recorded through the Platform for operational processing, Fees, Wallet entries, Settlement, dispute assistance, compliance and record-keeping purposes.", "k": "body" }, { "t": "5.6.5 The Marketplace may retain Transaction Records for such period as it considers reasonably necessary for business, accounting, taxation, compliance, dispute resolution, fraud prevention, audit or other legitimate purposes, subject to Applicable Law.", "k": "body" }, { "t": "5.6.6 The Marketplace may provide Transaction Records or relevant extracts to the Buyer, Seller, their authorised representatives, regulators, governmental authorities or other persons where reasonably required for Platform operations, dispute resolution, compliance or as otherwise permitted or required by Applicable Law.", "k": "body" }, { "t": "5.7 Invoicing and Tax Documents", "k": "h2" }, { "t": "5.7.1 The Seller shall issue a valid tax invoice, bill of supply, delivery challan or other applicable tax or commercial document to the Buyer in accordance with the Transaction terms and Applicable Law.", "k": "body" }, { "t": "5.7.2 The Seller shall ensure that all invoices and tax documents issued in connection with a Transaction contain accurate and complete information, including, where applicable, the Seller's and Buyer's legal details, GSTIN, Product description, quantity, Pricing, applicable taxes, HSN/SAC classification, place of supply and other particulars required under Applicable Law.", "k": "body" }, { "t": "5.7.3 The Seller shall be solely responsible for determining and correctly applying applicable taxes, tax rates, exemptions, classifications, input tax requirements and other tax obligations relating to the sale or supply of Products.", "k": "body" }, { "t": "5.7.4 The Buyer shall provide accurate billing, GST and other information reasonably required by the Seller for issuing invoices and other applicable tax documents.", "k": "body" }, { "t": "5.7.5 The Marketplace may generate, transmit, store or display invoices or other Transaction-related documents where such functionality is available on the Platform; however, such facilitation shall not make the Marketplace responsible for the accuracy, validity, tax treatment or statutory compliance of documents issued by the Seller.", "k": "body" }, { "t": "5.7.6 The Seller shall be responsible for correcting any incorrect, incomplete or non-compliant invoice or tax document issued by it and shall cooperate with the Buyer and Marketplace in making any necessary correction, amendment, cancellation or replacement.", "k": "body" }, { "t": "5.7.7 Any tax deduction, withholding, collection or other statutory adjustment required to be made by a Participant under Applicable Law shall be the responsibility of the Participant legally required to make such deduction, withholding, collection or payment.", "k": "body" }, { "t": "5.8 Payment Terms", "k": "h2" }, { "t": "5.8.1 The Buyer shall make payment for Products in accordance with the payment terms agreed for the relevant Transaction, including any advance payment, payment on delivery, deferred payment, credit period or other agreed arrangement.", "k": "body" }, { "t": "5.8.2 The payment terms applicable to a Transaction shall be determined between the Buyer and Seller and may be recorded through the Platform, PO, SO, Quotation or other Transaction records.", "k": "body" }, { "t": "5.8.3 Where a Transaction is undertaken on credit or with deferred payment terms, such credit or deferred payment is extended solely at the discretion and responsibility of the Seller. The Marketplace does not provide, guarantee or underwrite such credit.", "k": "body" }, { "t": "5.8.4 A Seller may approve, reject, modify or withdraw credit or deferred payment terms for a Buyer, subject to the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "5.8.5 The Marketplace shall not be responsible for the Buyer's ability or willingness to pay, delayed payment, default, non-payment, recovery, collection, insolvency, creditworthiness or financial condition of the Buyer in relation to any credit or deferred-payment Transaction.", "k": "body" }, { "t": "5.8.6 The Marketplace shall not be deemed to be a lender, creditor, guarantor, co-obligor, debtor, insurer or financial service provider merely because a credit or deferred-payment Transaction is initiated, recorded, facilitated or processed through the Platform.", "k": "body" }, { "t": "5.8.7 The Buyer remains solely responsible for payment of all amounts due to the Seller under the applicable Transaction, notwithstanding the involvement of the Marketplace in recording, facilitating or administering the Transaction.", "k": "body" }, { "t": "5.8.8 Any payment made through a payment mechanism or facility made available on the Platform shall be subject to the applicable payment process, Policies and Transaction terms.", "k": "body" }, { "t": "5.9 Payment Processing and Payment Failure", "k": "h2" }, { "t": "5.9.1 Where payment is to be made through a payment mechanism made available or facilitated by the Platform, the Buyer shall complete the payment in accordance with the applicable payment instructions and Transaction terms.", "k": "body" }, { "t": "5.9.2 The Marketplace may use third-party payment processors, banks, financial institutions or other authorised service providers for processing or facilitating payments. Such payment processing shall be subject to the applicable terms and requirements of the relevant service provider.", "k": "body" }, { "t": "5.9.3 A payment shall be treated as received or successfully processed only when the applicable payment system or Platform Records indicate successful receipt or confirmation, subject to subsequent reversal, chargeback, fraud review or other applicable adjustment.", "k": "body" }, { "t": "5.9.4 If a payment fails, is reversed, is rejected, is disputed, is charged back or is otherwise not successfully received, the Buyer shall remain responsible for the corresponding amount due under the applicable Transaction.", "k": "body" }, { "t": "5.9.5 The Marketplace may restrict, suspend or withhold further Transactions, Wallet credits, Settlement or other Marketplace Services where a payment failure, reversal, chargeback, suspected fraud or other payment-related risk occurs.", "k": "body" }, { "t": "5.9.6 The Marketplace shall not be responsible for payment failure, delay or interruption caused by the Buyer's bank, payment instrument, payment service provider, payment processor, network, technical infrastructure or any other third party not under the Marketplace's reasonable control.", "k": "body" }, { "t": "5.9.7 The Marketplace may make reasonable deductions, adjustments or recoveries from amounts otherwise payable to a Participant where required to account for payment reversals, chargebacks, refunds, Fees, penalties or other amounts properly due under this Agreement or the applicable Transaction terms.", "k": "body" }, { "t": "5.10 Credit Transactions and Seller Credit Responsibility", "k": "h2" }, { "t": "5.10.1 The Platform may facilitate Transactions in which the Seller permits the Buyer to purchase Products on credit or deferred payment terms, subject to the Seller's approval and the applicable Transaction terms.", "k": "body" }, { "t": "5.10.2 Credit approval, credit limits, credit periods and other credit terms shall be determined solely by the Seller. The Marketplace shall have no obligation to provide or arrange credit to any Participant.", "k": "body" }, { "t": "5.10.3 The Seller may, at its sole discretion and subject to Applicable Law, approve, reject, reduce, modify, suspend or withdraw credit facilities or deferred payment terms offered to a Buyer.", "k": "body" }, { "t": "5.10.4 The Seller shall remain solely responsible for assessing the Buyer's creditworthiness, determining the credit terms and bearing the risk of delayed payment, default, non-payment, recovery, collection, insolvency or other financial failure of the Buyer.", "k": "body" }, { "t": "5.10.5 The Marketplace shall not be responsible for collecting or recovering any amount payable by a Buyer to a Seller under a credit or deferred-payment Transaction, unless the Marketplace expressly undertakes a specific collection responsibility in writing.", "k": "body" }, { "t": "5.10.6 The Marketplace shall not be deemed to have guaranteed, insured, financed, funded or otherwise assumed any credit exposure arising between the Buyer and Seller.", "k": "body" }, { "t": "5.10.7 The Seller shall not represent to any Buyer that the Marketplace has approved, guaranteed or secured the Buyer's credit obligation merely because the Transaction is processed or recorded through the Platform.", "k": "body" }, { "t": "5.10.8 The Buyer remains solely liable to the Seller for all amounts due under a credit or deferred-payment Transaction, irrespective of whether the Marketplace facilitates, records or provides technology relating to such Transaction.", "k": "body" }, { "t": "5.10.9 The Marketplace may record credit terms, due dates, outstanding amounts, payment status and related information on the Platform for Transaction administration, record-keeping, dispute assistance, risk management and other legitimate Platform purposes, without assuming responsibility for the underlying credit obligation.", "k": "body" }, { "t": "5.11 Payment Due Dates and Outstanding Amounts", "k": "h2" }, { "t": "5.11.1 The Buyer shall pay all amounts due under a Transaction on or before the applicable due date specified in the Quotation, PO, SO, invoice, credit terms or other agreed Transaction terms.", "k": "body" }, { "t": "5.11.2 In a credit or deferred-payment Transaction, the applicable credit period and due date shall be determined by the Seller and shall be communicated or recorded as part of the applicable Transaction terms.", "k": "body" }, { "t": "5.11.3 The Buyer shall ensure that sufficient funds are available and that payment instructions provided through the Platform or otherwise agreed with the Seller are accurate and valid.", "k": "body" }, { "t": "5.11.4 Any delay or failure by the Buyer to pay an amount when due shall constitute a payment default under the relevant Transaction, without prejudice to any rights or remedies available to the Seller under the Transaction terms or Applicable Law.", "k": "body" }, { "t": "5.11.5 The Seller shall be responsible for taking such commercial or legal action as it considers appropriate for recovery of amounts due from the Buyer, including in relation to credit or deferred-payment Transactions.", "k": "body" }, { "t": "5.11.6 The Marketplace may record outstanding amounts, payment due dates and payment status on the Platform based on information available to it, but such records shall not constitute a guarantee by the Marketplace of payment or recovery of any amount due between the Buyer and Seller.", "k": "body" }, { "t": "5.11.7 The Marketplace may, subject to this Agreement and applicable Policies, restrict or suspend a Participant's access to relevant Platform features where payment defaults or other material payment-related risks are identified.", "k": "body" }, { "t": "5.12 Wallet and Settlement", "k": "h2" }, { "t": "5.12.1 The Marketplace may maintain a Wallet for each Participant to record amounts arising in connection with Transactions, including payments received, amounts payable or receivable, Fees, refunds, penalties, credits, deductions, adjustments and Settlement amounts.", "k": "body" }, { "t": "5.12.2 Entries in the Wallet may be made based on Transactions, payment confirmations, refunds, cancellations, returns, disputes, chargebacks, Fees, penalties, adjustments or other events recognised under this Agreement, applicable Policies or the relevant Transaction terms.", "k": "body" }, { "t": "5.12.3 Settlement shall be carried out in accordance with the applicable Settlement process, including any applicable payment terms, deductions, Fees, taxes, refunds, returns, chargebacks, penalties, holds or other adjustments.", "k": "body" }, { "t": "5.12.4 The Marketplace may withhold, delay, adjust or set off amounts otherwise payable to a Participant where reasonably required due to a pending dispute, refund, return, chargeback, payment reversal, suspected fraud, regulatory requirement, outstanding Fee, penalty, or other amount properly due under this Agreement or applicable Policies.", "k": "body" }, { "t": "5.12.5 A Participant shall review its Wallet and Settlement records and promptly notify the Marketplace of any material discrepancy or unauthorised entry identified therein.", "k": "body" }, { "t": "5.12.6 The Marketplace may correct errors or make reasonable adjustments to Wallet or Settlement records where required to reflect the underlying Transaction, payment, refund, deduction, Fee, reversal or other applicable event.", "k": "body" }, { "t": "5.12.7 The Marketplace shall not be responsible for any failure by a Buyer to pay amounts due to a Seller under a credit or deferred-payment Transaction, and recording such amounts in the Wallet or Settlement records shall not constitute a guarantee of payment or recovery by the Marketplace.", "k": "body" }, { "t": "5.12.8 The Wallet is an internal accounting mechanism of the Platform and shall not, unless expressly stated otherwise and permitted under Applicable Law, constitute a bank account, deposit account, payment account, loan account or stored-value instrument.", "k": "body" }, { "t": "5.12.9 Settlement of amounts through the Platform shall not by itself release a Buyer or Seller from any underlying obligation, liability, claim or responsibility arising from the relevant Transaction.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "5.13 Fees, Charges and Deductions", "k": "h2" }, { "t": "5.13.1 The Participant shall pay all Fees applicable to its use of the Platform and Marketplace Services and to Transactions undertaken through the Platform, as specified in the applicable Commercial Terms, Policies, Platform records or otherwise communicated by the Marketplace.", "k": "body" }, { "t": "5.13.2 Fees may include, as applicable, transaction charges, service charges, commissions, subscription charges, payment processing charges, penalties, administrative charges or other amounts payable in connection with the Platform or a Transaction.", "k": "body" }, { "t": "5.13.3 The Marketplace may deduct applicable Fees, charges, penalties, refunds, adjustments, taxes or other amounts properly payable by a Participant from amounts otherwise payable or credited to that Participant through the Wallet or Settlement process.", "k": "body" }, { "t": "5.13.4 Where an applicable Fee or charge cannot be deducted through the Wallet or Settlement process, the Participant shall pay the outstanding amount within the period specified by the Marketplace.", "k": "body" }, { "t": "5.13.5 The Marketplace may revise, introduce, remove or modify Fees and charges from time to time by updating the applicable Commercial Terms, Policies or Platform records, subject to Applicable Law.", "k": "body" }, { "t": "5.13.6 Unless expressly stated otherwise, all Fees are exclusive of applicable taxes, duties, levies or other statutory charges, which shall be borne by the Participant legally responsible for such amounts.", "k": "body" }, { "t": "5.13.7 A Participant shall not withhold, set off or deduct any amount payable to the Marketplace on account of any claim or dispute with another Participant unless such deduction or set-off is expressly permitted under this Agreement or required by Applicable Law.", "k": "body" }, { "t": "5.13.8 The Marketplace's collection or deduction of any Fee, charge, penalty or other amount shall not make the Marketplace responsible for any underlying obligation between the Buyer and Seller.", "k": "body" }, { "t": "5.14 Taxes and Statutory Deductions", "k": "h2" }, { "t": "5.14.1 Each Participant shall be solely responsible for determining, collecting, reporting and paying all taxes, duties, levies, cess, withholding taxes and other statutory amounts applicable to its activities and Transactions undertaken through the Platform, in accordance with Applicable Law.", "k": "body" }, { "t": "5.14.2 The Seller shall be responsible for correctly determining and charging applicable GST and other taxes on the sale or supply of Products and for issuing the appropriate tax documents to the Buyer.", "k": "body" }, { "t": "5.14.3 The Buyer shall be responsible for providing accurate GSTIN, billing details, place of supply and other information required for correct invoicing and tax treatment of the Transaction.", "k": "body" }, { "t": "5.14.4 Where a Participant is required under Applicable Law to deduct, withhold, collect or deposit any tax or other statutory amount from a payment to another Participant or to the Marketplace, such Participant shall make the required deduction, withholding, collection or deposit and comply with the applicable reporting and documentation requirements.", "k": "body" }, { "t": "5.14.5 The Marketplace may make or facilitate any deduction, withholding, collection or statutory adjustment that it is required or permitted to make under Applicable Law and may reflect the same in the relevant Wallet, Settlement or Transaction records.", "k": "body" }, { "t": "5.14.6 The Marketplace shall not be responsible for determining the tax liability of a Participant or for any tax liability arising from the underlying sale, purchase, supply, receipt or use of Products, except to the extent expressly imposed on the Marketplace under Applicable Law.", "k": "body" }, { "t": "5.14.7 Each Participant shall indemnify the Marketplace against any tax, interest, penalty, liability, claim or cost arising from the Participant's failure to comply with its own tax or statutory obligations under Applicable Law.", "k": "body" }, { "t": "5.15 Transaction Completion and Closure", "k": "h2" }, { "t": "5.15.1 A Transaction shall be treated as completed when the applicable Products have been supplied or delivered in accordance with the agreed Transaction terms and the corresponding payment and Settlement obligations have been completed, subject to any pending return, refund, warranty, dispute, claim, chargeback, adjustment or other surviving obligation.", "k": "body" }, { "t": "5.15.2 Completion or closure of a Transaction on the Platform shall not prevent a Buyer or Seller from raising a claim or exercising any right or remedy that accrued before or survives such completion under this Agreement, the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "5.15.3 The Marketplace may mark a Transaction as completed, closed or otherwise concluded in its Platform Records based on the information available to it and the applicable Platform procedures.", "k": "body" }, { "t": "5.15.4 The Marketplace may continue to process or adjust Wallet and Settlement entries after a Transaction has been marked completed or closed where required to account for refunds, returns, chargebacks, payment reversals, disputes, Fees, penalties, tax adjustments, errors or other amounts properly arising from the Transaction.", "k": "body" }, { "t": "5.15.5 Neither the marking of a Transaction as completed or closed nor the release of any Settlement amount shall constitute a representation or guarantee by the Marketplace that all obligations between the Buyer and Seller have been fully performed or that no subsequent claim may arise.", "k": "body" }, { "t": "5.15.6 The Buyer and Seller remain responsible for maintaining and fulfilling any obligations that, by their nature or under the applicable Transaction terms, survive completion or closure of the Transaction.", "k": "body" }, { "t": "5.16 Transaction Modification, Suspension and Platform Intervention", "k": "h2" }, { "t": "5.16.1 The Marketplace may, where reasonably necessary, suspend, restrict, pause or otherwise intervene in the processing of a Transaction where it reasonably believes that the Transaction may involve fraud, unauthorised activity, violation of this Agreement or applicable Policies, regulatory or legal concerns, payment irregularities, Product-related risks, security risks or other material risk to the Marketplace or Participants.", "k": "body" }, { "t": "5.16.2 The Marketplace may request information, documents, confirmations or other cooperation from the Buyer or Seller before allowing a Transaction to proceed or before releasing, adjusting or completing a related Settlement.", "k": "body" }, { "t": "5.16.3 During any such review or intervention, the Marketplace may temporarily restrict relevant Platform functionality, including placing an Order or Settlement on hold, without being liable for any resulting delay to the extent such action is reasonably required for the relevant review, compliance, security or risk-management purpose.", "k": "body" }, { "t": "5.16.4 The Marketplace may cancel or prevent completion of a Transaction where it reasonably determines that continuation may violate Applicable Law, applicable Policies or this Agreement, or may expose the Marketplace or Participants to material legal, financial, fraud, safety or security risk.", "k": "body" }, { "t": "5.16.5 Any action taken by the Marketplace under this Section shall not relieve the Buyer or Seller of obligations or liabilities that arose before such action, except to the extent expressly determined under the applicable Transaction terms, this Agreement or Applicable Law.", "k": "body" }, { "t": "5.16.6 The Marketplace shall, where reasonably practicable and subject to Applicable Law, Platform security and confidentiality requirements, communicate material reasons for any suspension, restriction or cancellation to the affected Participant.", "k": "body" }, { "t": "5.17 Buyer and Seller Responsibilities in Transactions", "k": "h2" }, { "t": "5.17.1 The Buyer and Seller acknowledge that the Marketplace primarily provides the Platform and Marketplace Services for facilitating and administering Transactions, and that the commercial relationship relating to the purchase and sale of Products is between the Buyer and Seller.", "k": "body" }, { "t": "5.17.2 The Buyer shall be responsible for:\n(a) providing accurate Order, billing, delivery and other required information;\n(b) making payments in accordance with the applicable Transaction terms;\n(c) receiving and inspecting Products;\n(d) complying with applicable payment, credit, delivery and other obligations; and\n(e) providing reasonable cooperation in relation to claims, returns, disputes and other matters concerning the Transaction.", "k": "body" }, { "t": "5.17.3 The Seller shall be responsible for:\n(a) providing accurate Product and commercial information;\n(b) accepting and fulfilling Orders in accordance with the agreed Transaction terms;\n(c) supplying Products that conform to the applicable specifications and requirements;\n(d) issuing applicable invoices and tax documents;\n(e) complying with applicable laws, licences and regulatory requirements; and\n(f) providing reasonable cooperation in relation to claims, returns, replacements, refunds, disputes and other matters concerning the Transaction.", "k": "body" }, { "t": "5.17.4 The Buyer and Seller shall independently satisfy themselves regarding the identity, authority, commercial terms, Product requirements and other matters relevant to a Transaction before confirming the Transaction.", "k": "body" }, { "t": "5.17.5 Neither the Buyer nor Seller shall rely upon the Marketplace as a substitute for its own commercial, legal, financial, tax, technical or Product-related due diligence.", "k": "body" }, { "t": "5.17.6 The Marketplace may facilitate communication, provide Platform Records and offer other Marketplace Services in relation to a Transaction, but shall not thereby assume the obligations of the Buyer or Seller.", "k": "body" }, { "t": "5.17.7 Where a Participant acts as both Buyer and Seller in different Transactions, its obligations and responsibilities under this Section shall apply separately according to the capacity in which it acts in each relevant Transaction.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "5.18 Marketplace Records and Transaction Authority", "k": "h2" }, { "t": "5.18.1 The Buyer and Seller acknowledge that the Platform may record Orders, Quotations, POs, SOs, confirmations, payment instructions, Transaction status, delivery information, communications and other Transaction-related activities undertaken through the Platform.", "k": "body" }, { "t": "5.18.2 Each Participant authorises the Marketplace to rely upon instructions, confirmations and other actions submitted through its Account by the Participant or by any person authorised or permitted by the Participant to access or use the Account.", "k": "body" }, { "t": "5.18.3 A Participant shall promptly notify the Marketplace if it disputes any Order, Transaction, instruction, confirmation or other record appearing in its Account or Platform Records.", "k": "body" }, { "t": "5.18.4 Subject to Applicable Law, the Marketplace may treat electronic instructions, confirmations and records generated through the Platform as valid and binding records of the relevant Participant unless the Participant establishes that the relevant activity was unauthorised and did not result from any failure or negligence attributable to the Participant.", "k": "body" }, { "t": "5.18.5 The Marketplace may use Platform Records as the basis for processing Transactions, calculating Fees, maintaining Wallet and Settlement records, resolving operational issues and administering Marketplace Services.", "k": "body" }, { "t": "5.18.6 Nothing in this Section makes the Marketplace a party to the underlying sale or purchase contract between the Buyer and Seller or transfers to the Marketplace any obligation that this Agreement or the applicable Transaction terms place upon either Participant.", "k": "body" }, { "t": "5.19 Participant's Independent Commercial Relationship", "k": "h2" }, { "t": "5.19.1 The Buyer and Seller shall independently determine and agree upon the commercial terms applicable to each Transaction, including Product requirements, Pricing, quantities, payment terms, credit terms, Transportation arrangements, delivery requirements and other commercial conditions, subject to this Agreement and applicable Policies.", "k": "body" }, { "t": "5.19.2 The Marketplace does not act as an intermediary in determining the commercial suitability or financial terms of a Transaction and does not guarantee that the commercial terms agreed between the Buyer and Seller are favourable, reasonable or suitable for either Party.", "k": "body" }, { "t": "5.19.3 Each Participant shall conduct its own due diligence regarding the other Participant and the relevant Product before entering into a Transaction, including where appropriate verification of business credentials, Product requirements, commercial capability and applicable legal or regulatory requirements.", "k": "body" }, { "t": "5.19.4 The Marketplace shall not be responsible for any loss, dispute, claim or liability arising solely from the commercial decisions, negotiations, representations, commitments or agreements made between the Buyer and Seller, except to the extent directly caused by a breach of this Agreement by the Marketplace.", "k": "body" }, { "t": "5.19.5 The Buyer and Seller remain independently responsible for complying with all obligations applicable to them under the confirmed Transaction, including payment, supply, delivery, taxation, credit, Transportation and Product-related obligations.", "k": "body" }, { "t": "5.19.6 No Participant shall represent to any third party that the Marketplace has guaranteed the performance, payment, creditworthiness, Product quality, delivery or other obligations of another Participant merely because the Transaction was initiated, recorded or facilitated through the Platform.", "k": "body" }, { "t": "5.20 Transaction Completion Does Not Limit Independent Claims", "k": "h2" }, { "t": "5.20.1 Completion, closure or Settlement of a Transaction shall not prevent a Buyer or Seller from raising any claim that arises from or relates to the Transaction and that is permitted under this Agreement, the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "5.20.2 Without limiting the foregoing, claims relating to Product defects, shortages, damage, non-conformity, warranty, returns, refunds, payment obligations, tax matters, fraud, misrepresentation or intellectual property may survive completion of the Transaction where permitted under Applicable Law.", "k": "body" }, { "t": "5.20.3 The Marketplace may continue to maintain relevant Platform Records and process applicable refunds, adjustments, deductions, claims or other post-Transaction matters in accordance with this Agreement and applicable Policies.", "k": "body" }, { "t": "5.20.4 Nothing in this Section shall extend or create any claim beyond the period or rights permitted under Applicable Law or the applicable Transaction terms.", "k": "body" }, { "t": "6. TRANSPORTATION, DELIVERY AND TRANSIT RISK", "k": "h1" }, { "t": "6.1 Responsibility for Transportation", "k": "h2" }, { "t": "6.1.1 Transportation of Products shall be arranged solely by the Buyer or Seller, as agreed between them for the relevant Transaction.", "k": "body" }, { "t": "6.1.2 The Marketplace does not arrange, provide or undertake Transportation of Products and shall not be responsible for appointing or managing any transporter, carrier, logistics provider or other person engaged for Transportation.", "k": "body" }, { "t": "6.1.3 The Buyer and Seller shall independently agree upon the applicable Transportation terms, including the transporter or carrier, freight charges, loading and unloading responsibilities, pickup or delivery location, delivery timelines and allocation of transit risk.", "k": "body" }, { "t": "6.1.4 The Seller may specify Pricing as inclusive of freight or exclusive of freight, as applicable to the relevant Quotation, Order or Transaction.", "k": "body" }, { "t": "6.1.5 Where Pricing is exclusive of freight, the applicable freight or Transportation charges shall be determined in accordance with the commercial terms agreed between the Buyer and Seller.", "k": "body" }, { "t": "6.1.6 The Marketplace shall not be liable for any loss, damage, shortage, deterioration, delay, misdelivery, non-delivery, accident or other event arising during Transportation, except to the extent the Marketplace has expressly undertaken responsibility for the specific matter in writing.", "k": "body" }, { "t": "6.1.7 The fact that Transportation-related information, charges or delivery status may be displayed, recorded or communicated through the Platform shall not make the Marketplace a transporter, carrier, logistics provider, agent or guarantor of delivery.", "k": "body" }, { "t": "6.2 Dispatch and Handover", "k": "h2" }, { "t": "6.2.1 The Seller shall make the Products available for pickup, collection or dispatch within the time period specified in the applicable Order, SO or other Transaction terms.", "k": "body" }, { "t": "6.2.2 Where the Seller is responsible for dispatch, the Seller shall ensure that the Products are properly packed, labelled and prepared for handover to the transporter or carrier in accordance with the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.2.3 Where the Buyer is responsible for arranging Transportation, the Buyer shall ensure that its nominated transporter or carrier collects the Products within the agreed period and in accordance with the applicable Transaction terms.", "k": "body" }, { "t": "6.2.4 The Seller shall provide reasonable dispatch and handover information through the Platform where such information is required for Transaction processing or record-keeping.", "k": "body" }, { "t": "6.2.5 The Seller shall ensure that the Products handed over to the transporter or carrier correspond with the applicable Order, including the agreed Product, quantity, packaging and other material particulars.", "k": "body" }, { "t": "6.2.6 The Buyer and Seller shall be responsible for verifying the condition and quantity of Products at the time of handover or receipt, as applicable, and shall promptly record or communicate any visible shortage, damage or discrepancy.", "k": "body" }, { "t": "6.2.7 The Marketplace may record dispatch, pickup, handover or delivery information provided by the Buyer, Seller or transporter through the Platform, but such recording shall not constitute verification or acceptance by the Marketplace of the actual condition, quantity or status of the Products.", "k": "body" }, { "t": "6.2.8 The Marketplace shall not be responsible for any failure, delay, loss, damage, shortage or other event occurring before, during or after handover to a transporter or carrier, except to the extent expressly undertaken by the Marketplace in writing.", "k": "body" }, { "t": "6.3 Delivery and Receipt of Products", "k": "h2" }, { "t": "6.3.1 The Seller shall make reasonable efforts to ensure that the Products are delivered to the destination specified in the applicable Transaction terms within the agreed delivery period, where delivery is the Seller's responsibility.", "k": "body" }, { "t": "6.3.2 Where delivery or collection is the Buyer's responsibility, the Buyer shall ensure that the necessary arrangements are made to receive or collect the Products within the agreed period.", "k": "body" }, { "t": "6.3.3 The Buyer shall provide accurate delivery information, including delivery address, contact details and any reasonable site-specific instructions required for delivery or receipt of the Products.", "k": "body" }, { "t": "6.3.4 The Buyer shall ensure that the delivery location is reasonably accessible and that an authorised person is available to receive the Products where required.", "k": "body" }, { "t": "6.3.5 The Buyer shall promptly inspect the Products upon receipt, to the extent reasonably practicable, for visible damage, shortage, incorrect Products or other apparent discrepancies and shall record or notify the Seller of such issues without unreasonable delay.", "k": "body" }, { "t": "6.3.6 A delivery confirmation, acknowledgment, proof of delivery, transporter record or similar record may be used as evidence of delivery or receipt of the Products, subject to any contrary evidence or applicable Transaction terms.", "k": "body" }, { "t": "6.3.7 The Marketplace may facilitate the exchange or recording of delivery-related information through the Platform but does not guarantee delivery, receipt, delivery timelines or the performance of any transporter or carrier.", "k": "body" }, { "t": "6.3.8 Any delay, failure or inability to deliver or receive Products caused by inaccurate information, unavailability of the Buyer or Seller, transporter or carrier issues, site restrictions, force majeure or other circumstances beyond the reasonable control of the relevant Party shall be dealt with in accordance with the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.4 Transit Risk and Responsibility", "k": "h2" }, { "t": "6.4.1 Unless otherwise expressly agreed between the Buyer and Seller, responsibility for Products during Transportation shall be determined by the delivery and risk terms agreed for the relevant Transaction.", "k": "body" }, { "t": "6.4.2 The Buyer and Seller shall independently determine and record when and upon whom the risk of loss, damage, shortage or deterioration of Products passes during Transportation, including, where applicable, upon dispatch, handover to the transporter, delivery at destination or receipt by the Buyer.", "k": "body" }, { "t": "6.4.3 Where Transportation is arranged by the Seller, the Seller shall remain responsible for the Products until the point at which risk passes to the Buyer in accordance with the agreed Transaction terms.", "k": "body" }, { "t": "6.4.4 Where Transportation is arranged by the Buyer, the Buyer shall be responsible for the Products from the point at which risk passes to the Buyer in accordance with the agreed Transaction terms.", "k": "body" }, { "t": "6.4.5 Neither the arrangement of Transportation by a Party nor the use of a third-party transporter or carrier shall, by itself, transfer any responsibility to the Marketplace.", "k": "body" }, { "t": "6.4.6 The Marketplace shall not be responsible for any loss, damage, shortage, deterioration, delay, misdelivery or non-delivery occurring during Transportation, irrespective of whether the relevant Transportation information or status is recorded on the Platform, except to the extent expressly undertaken by the Marketplace in writing.", "k": "body" }, { "t": "6.4.7 Any claim relating to loss, damage, shortage, deterioration, delay, misdelivery or non-delivery during Transportation shall be raised by the affected Buyer or Seller against the Party or transporter responsible under the agreed Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.5 Delivery Delays and Failed Delivery", "k": "h2" }, { "t": "6.5.1 The Buyer and Seller shall comply with the delivery timelines and delivery-related obligations agreed for the relevant Transaction.", "k": "body" }, { "t": "6.5.2 If a Seller is responsible for delivery and becomes aware that the Products are unlikely to be delivered within the agreed period, the Seller shall promptly inform the Buyer and, where applicable, update the relevant information through the Platform.", "k": "body" }, { "t": "6.5.3 If a Buyer is responsible for receiving or collecting the Products and becomes aware that it may be unable to receive or collect them within the agreed period, the Buyer shall promptly inform the Seller.", "k": "body" }, { "t": "6.5.4 Any additional Transportation costs, storage charges, re-delivery charges or other costs arising from a failed or delayed delivery shall be borne by the Party responsible for the relevant failure, subject to the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.5.5 The Marketplace may facilitate communication between the Buyer and Seller regarding delayed, failed or disputed deliveries and may record the relevant information on the Platform.", "k": "body" }, { "t": "6.5.6 The Marketplace shall not be responsible for any delivery delay, failed delivery, re-delivery, storage, detention, demurrage or other Transportation-related consequence arising from circumstances attributable to the Buyer, Seller, transporter, carrier or other third party.", "k": "body" }, { "t": "6.5.7 Where a delivery failure or delay materially affects a Transaction, the Buyer and Seller shall follow the applicable cancellation, return, refund, replacement or dispute procedures under this Agreement, the Transaction terms and applicable Policies.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "6.6 Loading, Unloading and Handling", "k": "h2" }, { "t": "6.6.1 Responsibility for loading, unloading, handling and related activities shall be determined by the Buyer and Seller in accordance with the applicable Transaction terms.", "k": "body" }, { "t": "6.6.2 Where the Seller is responsible for loading or preparing Products for Transportation, the Seller shall carry out such activities with reasonable care and in accordance with the nature of the Products, Applicable Law and agreed Transaction terms.", "k": "body" }, { "t": "6.6.3 Where the Buyer is responsible for unloading or handling Products at the delivery location, the Buyer shall carry out such activities with reasonable care and in accordance with the nature of the Products, Applicable Law and agreed Transaction terms.", "k": "body" }, { "t": "6.6.4 The Party responsible for loading, unloading or handling shall bear the related costs and risks to the extent allocated to it under the applicable Transaction terms.", "k": "body" }, { "t": "6.6.5 Where loading, unloading or handling is performed by a transporter, carrier or other third party, the Buyer or Seller responsible for engaging or controlling such third party shall remain responsible for that arrangement in accordance with the applicable Transaction terms.", "k": "body" }, { "t": "6.6.6 The Marketplace shall not be responsible for loading, unloading, handling or any resulting loss, damage, shortage, delay or other consequence, unless the Marketplace has expressly undertaken the relevant responsibility in writing.", "k": "body" }, { "t": "6.7 Transportation Documentation and Proof of Delivery", "k": "h2" }, { "t": "6.7.1 The Party responsible for arranging Transportation shall ensure that all applicable transportation, dispatch and delivery documents are prepared and maintained in accordance with the Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.7.2 Where required, the Seller shall provide the Buyer with applicable dispatch documents, delivery challans, e-way bills, invoices, consignment notes, transporter details and other documents required for lawful movement and delivery of the Products.", "k": "body" }, { "t": "6.7.3 The Buyer shall provide such information and documents as may reasonably be required for delivery, receipt, transportation or compliance relating to the Products.", "k": "body" }, { "t": "6.7.4 The Buyer and Seller shall ensure that information provided to a transporter or carrier, including pickup location, delivery location, Product details, quantity and other material particulars, is accurate and complete.", "k": "body" }, { "t": "6.7.5 Proof of delivery, delivery acknowledgment, transporter records, electronic delivery confirmation or other equivalent records may be used by the Buyer, Seller and Marketplace for establishing the status of delivery, subject to applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.7.6 The Marketplace may request, receive, store or display Transportation-related documents or delivery records where reasonably required for Transaction administration, dispute resolution, Settlement, compliance or record-keeping.", "k": "body" }, { "t": "6.7.7 The Marketplace's receipt, storage or display of any Transportation or delivery document shall not constitute verification, certification or acceptance of the accuracy, validity or legal sufficiency of such document.", "k": "body" }, { "t": "6.8 Transportation Claims and Disputes", "k": "h2" }, { "t": "6.8.1 Any claim relating to loss, damage, shortage, deterioration, delay, misdelivery or non-delivery of Products during Transportation shall be raised by the Buyer or Seller against the Party, transporter, carrier or other person responsible under the applicable Transaction terms.", "k": "body" }, { "t": "6.8.2 The Party raising a Transportation-related claim shall provide reasonable details and supporting evidence, including, where available, photographs, delivery records, consignment documents, proof of delivery, inspection records and other relevant information.", "k": "body" }, { "t": "6.8.3 The Buyer and Seller shall reasonably cooperate with each other and with the relevant transporter or carrier in investigating and resolving Transportation-related claims.", "k": "body" }, { "t": "6.8.4 The Marketplace may facilitate communication, exchange of information or review of Platform Records relating to a Transportation dispute where such assistance is available through the Platform.", "k": "body" }, { "t": "6.8.5 Any assistance or facilitation provided by the Marketplace shall not make the Marketplace responsible for the Transportation, transporter, carrier, Products or outcome of the claim.", "k": "body" }, { "t": "6.8.6 The Marketplace shall not be required to independently investigate, determine or compensate any Transportation-related claim unless it has expressly undertaken such responsibility in writing or is required to do so under Applicable Law.", "k": "body" }, { "t": "6.8.7 Any refund, replacement, compensation, adjustment or other remedy arising from a Transportation-related claim shall be the responsibility of the Party against whom such obligation properly lies under the applicable Transaction terms, Applicable Law or other applicable arrangement.", "k": "body" }, { "t": "6.9 Transportation Costs and Freight Charges", "k": "h2" }, { "t": "6.9.1 Unless otherwise expressly agreed in the applicable Transaction, the Buyer and Seller shall determine which Party is responsible for Transportation costs, freight charges and other transportation-related expenses.", "k": "body" }, { "t": "6.9.2 Where the Seller quotes Product Pricing inclusive of freight or Transportation charges, such charges shall be treated as included in the Pricing to the extent specified in the applicable Quotation, SO, Order or other agreed Transaction terms.", "k": "body" }, { "t": "6.9.3 Where Product Pricing is quoted exclusive of freight or Transportation charges, the applicable freight and Transportation costs shall be payable by the Party specified in the Quotation, PO, SO or other agreed Transaction terms.", "k": "body" }, { "t": "6.9.4 Unless expressly agreed otherwise, any additional Transportation-related costs arising from changes in delivery location, failed delivery, re-delivery, storage, detention, demurrage, waiting time, special handling or other circumstances attributable to the Buyer or Seller shall be borne by the Party responsible for such circumstances.", "k": "body" }, { "t": "6.9.5 The Marketplace may record or display freight charges or Transportation-related amounts communicated by the Buyer or Seller, but such recording or display shall not constitute verification, approval or assumption of responsibility by the Marketplace.", "k": "body" }, { "t": "6.9.6 The Marketplace shall not be responsible for the calculation, collection, payment, refund or dispute of freight or Transportation charges between the Buyer, Seller and any transporter or carrier, except to the extent the Marketplace expressly agrees otherwise in writing.", "k": "body" }, { "t": "6.9.7 Any dispute concerning freight charges, Transportation costs or other transportation-related expenses shall be resolved between the Buyer and Seller in accordance with the applicable Transaction terms, without prejudice to any rights or remedies available under this Agreement or Applicable Law.", "k": "body" }, { "t": "6.10 Transportation Responsibilities of Buyer and Seller", "k": "h2" }, { "t": "6.10.1 The Buyer and Seller shall comply with all Transportation-related responsibilities allocated to them under the applicable Quotation, PO, SO, Order, Transaction terms or other agreed commercial arrangement.", "k": "body" }, { "t": "6.10.2 The Party responsible for arranging Transportation shall select and appoint the transporter or carrier and shall be responsible for providing such transporter or carrier with accurate and complete information necessary for Transportation.", "k": "body" }, { "t": "6.10.3 The Seller shall ensure that Products are ready for dispatch, appropriately packed, labelled and accompanied by applicable documents within the time and manner agreed for the Transaction.", "k": "body" }, { "t": "6.10.4 The Buyer shall ensure that the delivery location, contact details, receiving arrangements and other information provided for delivery are accurate and sufficient for completion of Transportation.", "k": "body" }, { "t": "6.10.5 Each Party shall reasonably cooperate with the other Party and the relevant transporter or carrier in relation to pickup, dispatch, delivery, receipt, documentation, inspection and resolution of Transportation-related issues.", "k": "body" }, { "t": "6.10.6 A Party shall not unreasonably delay, obstruct or prevent pickup, dispatch, delivery or receipt of Products where such activity is its responsibility under the applicable Transaction terms.", "k": "body" }, { "t": "6.10.7 Each Party shall bear the consequences and costs arising from its own failure to perform Transportation-related responsibilities, to the extent attributable to that Party and subject to the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.10.8 The Marketplace may facilitate communication or exchange of Transportation-related information between Participants, but such facilitation shall not transfer any Transportation responsibility to the Marketplace.", "k": "body" }, { "t": "6.11 Transportation Compliance and Legal Requirements", "k": "h2" }, { "t": "6.11.1 The Buyer and Seller shall each comply with all Applicable Laws, permits, licences, registrations, documentation requirements, safety requirements and other regulatory requirements applicable to the Transportation of Products to the extent such requirements apply to that Party.", "k": "body" }, { "t": "6.11.2 The Party responsible for arranging Transportation shall ensure that the selected transporter or carrier is appropriately authorised, where such authorisation is required under Applicable Law.", "k": "body" }, { "t": "6.11.3 The Seller shall ensure that Products are lawfully packed, labelled, documented and prepared for Transportation, including compliance with any applicable requirements relating to hazardous, restricted, regulated or specially handled Products.", "k": "body" }, { "t": "6.11.4 The Buyer shall provide accurate and lawful delivery, receiving and destination information and shall obtain any permissions or approvals required for receipt, unloading or handling of Products at the delivery location, where applicable.", "k": "body" }, { "t": "6.11.5 Each Party shall promptly provide information or documents reasonably required for compliance with applicable Transportation, tax, invoicing, e-way bill, delivery or other statutory requirements relating to the Transaction.", "k": "body" }, { "t": "6.11.6 Neither Buyer nor Seller shall instruct, arrange or permit Transportation in a manner that violates Applicable Law or creates an unreasonable safety, regulatory or legal risk.", "k": "body" }, { "t": "6.11.7 Each Party shall be solely responsible for any loss, liability, penalty, claim, cost or regulatory consequence arising from its failure to comply with Transportation-related obligations applicable to it.", "k": "body" }, { "t": "6.11.8 The Marketplace shall not be responsible for determining whether the Transportation arrangements made by the Buyer, Seller or their transporter or carrier comply with Applicable Law, except to the extent such responsibility is expressly assumed by the Marketplace in writing.", "k": "body" }, { "t": "6.12 Transportation Insurance", "k": "h2" }, { "t": "6.12.1 The Buyer and Seller shall independently determine whether insurance is required for the Transportation of Products and, where applicable, which Party shall arrange and bear the cost of such insurance.", "k": "body" }, { "t": "6.12.2 Where Transportation insurance is arranged by the Buyer, Seller, transporter or carrier, the Party arranging such insurance shall be responsible for selecting the insurer, determining the coverage and complying with the applicable terms and conditions of the insurance policy.", "k": "body" }, { "t": "6.12.3 The Marketplace does not provide, arrange, underwrite or guarantee Transportation insurance and shall not be responsible for any insurance premium, coverage, exclusion, claim, rejection, delay in settlement or other matter relating to such insurance.", "k": "body" }, { "t": "6.12.4 A Party seeking compensation for loss or damage during Transportation shall pursue the applicable claim against the responsible Party, transporter, carrier or insurer, as appropriate under the Transaction terms and Applicable Law.", "k": "body" }, { "t": "6.12.5 The Marketplace may, where reasonably required for administration of a Transaction or resolution of a dispute, facilitate the exchange of available Transportation or insurance-related information between the Buyer and Seller, without assuming any liability under the relevant insurance arrangement.", "k": "body" }, { "t": "6.12.6 The absence of Transportation insurance shall not, by itself, make the Marketplace responsible for any loss, damage, shortage, deterioration, delay or other Transportation-related event.", "k": "body" }, { "t": "6.13 Force Majeure Affecting Transportation", "k": "h2" }, { "t": "6.13.1 Neither the Buyer nor the Seller shall be liable for delay or failure in Transportation to the extent directly caused by events beyond its reasonable control, including natural disasters, floods, earthquakes, fire, war, riots, civil disturbances, strikes, governmental restrictions, road closures, transportation disruptions or other events constituting Force Majeure under this Agreement.", "k": "body" }, { "t": "6.13.2 The Party affected by such event shall, where reasonably practicable, promptly inform the other Party of the event, its expected impact on Transportation and any material change in the expected delivery or receipt timeline.", "k": "body" }, { "t": "6.13.3 The affected Party shall use reasonable efforts to mitigate the effect of the event and resume or complete the Transportation as soon as reasonably practicable.", "k": "body" }, { "t": "6.13.4 A Force Majeure event shall not, by itself, relieve a Party from payment obligations or other obligations that had already accrued before the occurrence of such event, except to the extent otherwise provided under this Agreement, the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "6.13.5 The Marketplace shall not be liable for any Transportation delay, disruption, loss or additional cost arising from a Force Majeure event affecting the Buyer, Seller, transporter, carrier or other third party.", "k": "body" }, { "t": "6.14 Transportation-Related Communication and Coordination", "k": "h2" }, { "t": "6.14.1 The Buyer and Seller shall promptly communicate with each other regarding any material issue that may affect pickup, dispatch, Transportation, delivery, receipt or return of Products.", "k": "body" }, { "t": "6.14.2 Where a Party becomes aware of any actual or anticipated delay, loss, damage, shortage, misdelivery, failed delivery or other material Transportation issue, it shall promptly notify the other Party and, where applicable, the relevant transporter or carrier.", "k": "body" }, { "t": "6.14.3 The Buyer and Seller shall reasonably cooperate in providing information, documents, acknowledgements, photographs, delivery records, transporter details and other evidence reasonably required to investigate or resolve a Transportation-related issue.", "k": "body" }, { "t": "6.14.4 The Marketplace may facilitate communication between the Buyer and Seller and may record relevant Transportation-related communications, status updates and documents through the Platform.", "k": "body" }, { "t": "6.14.5 Any communication, coordination or record maintained by the Marketplace under this Section is for administrative, operational, record-keeping or dispute-assistance purposes and shall not constitute an assumption by the Marketplace of responsibility for Transportation.", "k": "body" }, { "t": "6.14.6 The Marketplace may rely on information and status updates provided by the Buyer, Seller, transporter or carrier unless there is a reasonable basis to believe that such information is materially inaccurate or misleading.", "k": "body" }, { "t": "6.14.7 Failure by a Buyer or Seller to provide timely information or cooperation shall not make the Marketplace responsible for any resulting Transportation delay, loss, damage, shortage, additional cost or other consequence.", "k": "body" }, { "t": "6.15 Transportation-Related Costs, Losses and Indemnification", "k": "h2" }, { "t": "6.15.1 Each Party shall bear the Transportation-related costs and expenses allocated to it under the applicable Transaction terms, including freight, loading, unloading, storage, detention, demurrage, re-delivery, special handling and other related charges.", "k": "body" }, { "t": "6.15.2 Where any additional Transportation-related cost, loss, damage, penalty or liability arises due to the act, omission, negligence, breach or inaccurate information provided by a Buyer or Seller, such Party shall be responsible for the same to the extent attributable to it.", "k": "body" }, { "t": "6.15.3 Without limiting any other rights or remedies available under this Agreement, a Party responsible for a Transportation-related breach shall reimburse or indemnify the affected Party for losses, costs, claims, damages, penalties and reasonable expenses arising directly from such breach, subject to Applicable Law.", "k": "body" }, { "t": "6.15.4 Where a transporter or carrier is responsible for a Transportation-related loss or incident, the Buyer or Seller who appointed or engaged such transporter or carrier shall pursue the applicable claim or remedy against such transporter or carrier, as appropriate.", "k": "body" }, { "t": "6.15.5 The Marketplace shall not be responsible for Transportation-related costs, losses, damages, penalties, claims or liabilities arising from arrangements made by the Buyer, Seller, transporter, carrier or any other third party, except to the extent expressly assumed by the Marketplace in writing.", "k": "body" }, { "t": "6.15.6 Nothing in this Section shall limit any liability of the Marketplace that cannot lawfully be excluded or limited under Applicable Law.", "k": "body" }, { "t": "6.16 Survival of Transportation Obligations", "k": "h2" }, { "t": "6.16.1 Completion, delivery, receipt, payment or Settlement of a Transaction shall not, by itself, release the Buyer or Seller from any Transportation-related obligation, liability, claim or responsibility that has accrued or is otherwise intended to survive under the applicable Transaction terms, this Agreement or Applicable Law.", "k": "body" }, { "t": "6.16.2 Transportation-related claims concerning loss, damage, shortage, non-delivery, misdelivery, delay, deterioration, documentation, insurance or other matters may be raised after completion of the Transaction to the extent permitted by the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "6.16.3 The Marketplace may retain and use relevant Platform Records, communications, delivery records, acknowledgements and other information after completion of a Transaction for the purposes of resolving claims, processing adjustments, handling disputes, compliance, audit, fraud prevention and enforcement of this Agreement.", "k": "body" }, { "t": "6.16.4 Any post-Transaction assistance, record maintenance, adjustment or dispute facilitation by the Marketplace shall not constitute an assumption of Transportation responsibility or liability by the Marketplace.", "k": "body" }, { "t": "6.16.5 The rights and obligations of the Buyer, Seller and Marketplace under this Section shall be subject to the limitation, exclusion and dispute-resolution provisions of this Agreement and Applicable Law.", "k": "body" }, { "t": "7. PAYMENT PROCESSING, FUND HOLDING AND SETTLEMENT", "k": "h1" }, { "t": "7.1 Advance Payments and Holding of Transaction Funds", "k": "h2" }, { "t": "7.1.1 Where a Buyer elects or is required to make advance payment for a Transaction, the Buyer shall make such payment through the payment mechanism specified by the Marketplace and in accordance with the applicable Transaction terms, Platform procedures and Policies.", "k": "body" }, { "t": "7.1.2 Amounts received in respect of an advance-paid Transaction may be received into and held in a bank account maintained by the Marketplace until the applicable Transaction is completed and the amount becomes eligible for Settlement to the Seller in accordance with this Agreement and the applicable Policies.", "k": "body" }, { "t": "7.1.3 For an advance-paid Transaction, payment shall be treated as received by the Marketplace when the Buyer submits the required payment details or payment confirmation through the Platform and the Marketplace confirms such payment through its administrative system, subject to verification and confirmation of the payment.", "k": "body" }, { "t": "7.1.4 The Marketplace shall hold the advance payment until the applicable conditions for release to the Seller under this Agreement and the applicable Policies are satisfied.", "k": "body" }, { "t": "7.1.5 A Transaction shall become eligible for automatic release of the amount payable to the Seller when:\n(a) the Seller has delivered the confirmed quantity of Products to the Buyer;\n(b) the Seller has marked the Transaction as delivered through the Platform; and\n(c) the Buyer has not raised a dispute in respect of the Transaction within one (1) Business Day from the time the Seller marks the Transaction as delivered through the Platform.", "k": "body" }, { "t": "7.1.6 Where the Seller is unable to dispatch or deliver the confirmed quantity of Products within the applicable committed timeline due to Transportation delay or any other reason, the Seller may request one (1) extension through the Platform before expiry of the applicable timeline. Such extension shall be subject to the applicable Platform process and, once accepted or recorded through the Platform, the revised timeline shall apply to the Transaction.", "k": "body" }, { "t": "7.1.7 If the Seller fails to dispatch or deliver the confirmed quantity of Products within the original or duly extended timeline, as applicable, the Marketplace may cancel the Transaction and refund the advance payment to the Buyer in accordance with this Agreement and the applicable Policies.", "k": "body" }, { "t": "7.1.8 Where the Buyer raises a dispute within the applicable dispute period, the amount relating to the Transaction may be placed on hold until the dispute is resolved in accordance with this Agreement, the applicable Transaction terms and Policies.", "k": "body" }, { "t": "7.1.9 The Marketplace may review Platform Records, communications, Transaction information, delivery records, documents and other relevant evidence and may take an administrative decision for the purposes of determining the appropriate Settlement, refund, adjustment or other action in relation to a dispute.", "k": "body" }, { "t": "7.1.10 Where the Marketplace determines that an amount is required to be refunded, compensated or otherwise adjusted in favour of the Buyer, the Marketplace may deduct such amount from the amount otherwise payable to the Seller and credit or refund the applicable amount to the Buyer in accordance with the applicable circumstances and Policies.", "k": "body" }, { "t": "7.1.11 Upon satisfaction of the conditions specified in Clause 7.1.5, the applicable amount payable to the Seller shall be automatically released through the Marketplace's Settlement process without any additional reconciliation or approval period, subject only to any deductions, adjustments, refunds, disputes, chargebacks, penalties or other amounts properly recoverable under this Agreement or the applicable Policies.", "k": "body" }, { "t": "7.1.12 The Marketplace shall endeavour to complete Settlement at the earliest practicable time and shall not unnecessarily retain or delay release of funds once the applicable conditions for Settlement have been satisfied.", "k": "body" }, { "t": "7.1.13 The Marketplace's receipt and holding of advance payment under this Section is solely for the purposes of administering and completing the applicable Platform Transaction and Settlement process and shall not, by itself, make the Marketplace the Buyer, Seller, owner of the Products, financier, lender, guarantor or party to the underlying sale contract between the Buyer and Seller.", "k": "body" }, { "t": "7.1.14 The provisions of this Section relating to holding and release of funds shall apply only to Transactions for which advance payment is made through the Marketplace. Where a Seller grants credit to a Buyer, the payment obligation shall remain directly between the Buyer and Seller, and the Marketplace shall not hold such payment or assume responsibility for collection, recovery or payment of such credit amount.", "k": "body" }, { "t": "7.1.15 The Marketplace may refund, cancel or return advance payment to the Buyer where required or considered appropriate under the circumstances of the Transaction, this Agreement, the applicable Policies or Applicable Law.", "k": "body" }, { "t": "7.2 Credit Transactions and Direct Seller Payments", "k": "h2" }, { "t": "7.2.1 Where a Seller offers credit or deferred payment terms for a Transaction, such credit shall be granted solely by the Seller to the Buyer and shall be subject to the credit limit, payment period and other terms approved by the Seller.", "k": "body" }, { "t": "7.2.2 The Marketplace does not provide, arrange, finance, underwrite, guarantee or insure any credit extended by a Seller to a Buyer and shall not be responsible for the Buyer's ability or willingness to make payment within the applicable credit period.", "k": "body" }, { "t": "7.2.3 Payments relating to a credit Transaction shall be made directly by the Buyer to the Seller in accordance with the credit terms agreed between them. The Marketplace shall not receive, hold or settle such payment on behalf of the Seller.", "k": "body" }, { "t": "7.2.4 The Seller shall be solely responsible for determining the Buyer's eligibility for credit, including the credit limit, credit period, payment terms, security or other conditions that the Seller may require, subject to Applicable Law.", "k": "body" }, { "t": "7.2.5 The Seller may, at its discretion and subject to Applicable Law, approve, reject, reduce, modify, suspend or withdraw credit facilities offered to a Buyer.", "k": "body" }, { "t": "7.2.6 The Buyer shall remain directly liable to the Seller for all amounts payable under a credit Transaction, irrespective of the Marketplace's involvement in recording, facilitating or communicating the Transaction.", "k": "body" }, { "t": "7.2.7 The Marketplace shall not be responsible for collection, recovery, delayed payment, default, insolvency, credit loss or other consequences arising from a Buyer's failure to pay the Seller under a credit Transaction.", "k": "body" }, { "t": "7.2.8 A Seller shall not represent or imply that any credit facility provided to a Buyer has been approved, guaranteed, financed or secured by the Marketplace.", "k": "body" }, { "t": "7.2.9 The Marketplace may restrict or suspend a Participant's access to credit-related or other Platform features where the Marketplace considers such action reasonably necessary due to payment default, risk, fraud, misuse, violation of this Agreement or Policies, or other legitimate operational or compliance reasons.", "k": "body" }, { "t": "7.2.10 The provisions relating to holding and release of advance payments under Clause 7.1 shall not apply to credit Transactions where payment is made directly between the Buyer and Seller.", "k": "body" }, { "t": "7.3 Participant Wallet and Prepaid Commission", "k": "h2" }, { "t": "7.3.1 The Marketplace may maintain a Wallet for each Participant for the sole purpose of recording and administering commissions, Fees, charges, penalties, adjustments and other amounts payable by or attributable to the Participant under this Agreement or applicable Policies.", "k": "body" }, { "t": "7.3.2 The Wallet is an internal accounting and settlement ledger maintained by the Marketplace and shall not constitute a bank account, deposit account, payment account, escrow account, credit facility, loan, stored-value instrument or other financial account of the Participant, unless expressly provided otherwise in accordance with Applicable Law.", "k": "body" }, { "t": "7.3.3 Where required by the Marketplace, a Participant shall maintain sufficient prepaid funds in its Wallet to meet applicable commissions and other amounts payable in connection with its use of the Platform.", "k": "body" }, { "t": "7.3.4 The Marketplace may deduct applicable commissions and other amounts due from the Participant's Wallet in accordance with the applicable Commercial Terms, Transaction terms and Policies.", "k": "body" }, { "t": "7.3.5 The Marketplace may specify the applicable commission amount, rate, basis of calculation and timing of deduction for Transactions or other Marketplace Services through the applicable Commercial Terms, Platform records or Policies.", "k": "body" }, { "t": "7.3.6 The Participant shall be responsible for ensuring that its Wallet contains sufficient funds to meet amounts payable to the Marketplace.", "k": "body" }, { "t": "7.3.7 Where the amount payable exceeds the available Wallet balance, the Wallet may reflect a negative balance representing the amount due and payable by the Participant to the Marketplace.", "k": "body" }, { "t": "7.3.8 The Marketplace may restrict, suspend or prevent the Participant from initiating or completing further Transactions or accessing specified Platform features where the Participant has an outstanding negative Wallet balance, until such outstanding amount is paid or otherwise resolved.", "k": "body" }, { "t": "7.3.9 The Marketplace may recover an outstanding Wallet balance from amounts otherwise payable or becoming payable to the Participant, including Settlement amounts, subject to this Agreement, applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "7.3.10 Wallet entries may include prepaid commissions, commission deductions, Fees, penalties, refunds, adjustments, reversals, credits and other amounts properly attributable to the Participant.", "k": "body" }, { "t": "7.3.11 The Participant shall review its Wallet records and promptly notify the Marketplace of any material discrepancy. The Marketplace may investigate and correct any genuine accounting or recording error identified in the Wallet.", "k": "body" }, { "t": "7.3.12 The Wallet shall not be treated as holding advance payment amounts received from Buyers for Transactions. Advance payments covered under Clause 7.1 and the Participant's Wallet maintained for commissions are separate mechanisms.", "k": "body" }, { "t": "7.3.13 The Marketplace may modify the manner in which Wallet balances, commissions or other amounts are recorded or administered for operational, commercial, security, compliance or technical reasons, subject to Applicable Law and the applicable terms communicated to the Participant.", "k": "body" }, { "t": "7.4 Settlement to Seller", "k": "h2" }, { "t": "7.4.1 Subject to the terms of this Agreement, the applicable Transaction terms and Policies, the Marketplace shall settle and release to the Seller the amount payable from an advance-paid Transaction after the Transaction becomes eligible for Settlement under Clause 7.1.", "k": "body" }, { "t": "7.4.2 The amount payable to the Seller shall be calculated after giving effect to any applicable commission, Fees, refund, compensation, penalty, adjustment, deduction, chargeback or other amount properly recoverable from the Seller under this Agreement, the applicable Transaction terms or Policies.", "k": "body" }, { "t": "7.4.3 Where no dispute has been raised by the Buyer within the applicable dispute period and the conditions for Settlement have been satisfied, the Seller's applicable Settlement amount shall be released automatically without any additional approval or reconciliation period.", "k": "body" }, { "t": "7.4.4 Where a dispute has been raised by the Buyer within the applicable dispute period, the Marketplace may place the relevant Settlement amount on hold until the dispute is resolved or an appropriate administrative decision is made under this Agreement and the applicable Policies.", "k": "body" }, { "t": "7.4.5 Where a dispute results in a refund, compensation or other amount being payable to the Buyer, the Marketplace may deduct such amount from the Seller's Settlement and release the remaining eligible amount to the Seller.", "k": "body" }, { "t": "7.4.6 If the amount available for Settlement to the Seller is insufficient to satisfy an amount properly recoverable from the Seller, the remaining amount may be recorded as an amount due from the Seller and reflected as a negative Wallet balance in accordance with Clause 7.3.", "k": "body" }, { "t": "7.4.7 The Marketplace may recover any outstanding amount due from a Seller by adjustment against subsequent Settlement amounts or other amounts payable to the Seller, subject to this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "7.4.8 The Marketplace shall endeavour to process and release eligible Settlement amounts at the earliest practicable time and shall not intentionally delay Settlement once the applicable conditions for release have been satisfied.", "k": "body" }, { "t": "7.4.9 Settlement of an amount to the Seller shall not constitute confirmation that all obligations of the Seller under the relevant Transaction have been fully discharged, and shall not prevent the Marketplace from making any subsequent adjustment, recovery or action permitted under this Agreement, the applicable Transaction terms, Policies or Applicable Law.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "7.5 Refunds, Reversals and Adjustments", "k": "h2" }, { "t": "7.5.1 The Marketplace may initiate, process or facilitate a refund of an advance payment to the Buyer where a Transaction is cancelled, the Seller fails to fulfil the Transaction within the applicable committed or extended timeline, a valid dispute is upheld, or a refund is otherwise required or permitted under this Agreement, the applicable Transaction terms, Policies or Applicable Law.", "k": "body" }, { "t": "7.5.2 Where a refund is required, the Marketplace may refund the applicable amount to the Buyer through the payment mechanism or account determined by the Marketplace, subject to the applicable payment process and Applicable Law.", "k": "body" }, { "t": "7.5.3 Where the amount payable to the Buyer is attributable to a Seller's failure, breach, Product-related issue, Transportation responsibility or other matter for which the Seller is responsible, the Marketplace may recover or adjust such amount against the Seller's Settlement, Wallet balance or other amounts payable to the Seller.", "k": "body" }, { "t": "7.5.4 Where a refund or adjustment is made after an amount has already been settled to the Seller, the Marketplace may recover the applicable amount from the Seller through adjustment against subsequent Settlement amounts, deduction from the Seller's Wallet or by requiring the Seller to pay the outstanding amount.", "k": "body" }, { "t": "7.5.5 Where a payment is reversed, failed, charged back, duplicated or otherwise incorrectly credited or recorded, the Marketplace may make corresponding adjustments to the relevant Transaction, Settlement or Wallet records.", "k": "body" }, { "t": "7.5.6 The Marketplace may cancel or reverse a Transaction or payment where reasonably necessary due to fraud, unauthorised activity, technical error, payment failure, regulatory requirement, breach of this Agreement or Policies, or other circumstances warranting such action.", "k": "body" }, { "t": "7.5.7 A refund, reversal or adjustment shall not, by itself, determine or extinguish any underlying rights or liabilities between the Buyer and Seller except to the extent expressly provided by the applicable Transaction terms, this Agreement or Applicable Law.", "k": "body" }, { "t": "7.5.8 The Marketplace shall endeavour to process eligible refunds and adjustments at the earliest practicable time, subject to payment processing requirements, verification, dispute resolution and other circumstances beyond the reasonable control of the Marketplace.", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.6 Fees, Commissions and Payment Charges", "k": "h2" }, { "t": "7.6.1 The Participant shall pay all commissions, Fees and other charges applicable to its use of the Platform and Marketplace Services in accordance with the applicable Commercial Terms, Transaction terms, Policies and Platform records.", "k": "body" }, { "t": "7.6.2 The commission applicable to a Transaction may be specified as a fixed amount, percentage of Transaction Value or such other basis as communicated by the Marketplace.", "k": "body" }, { "t": "7.6.3 Where a commission is required to be prepaid, the Participant shall maintain sufficient funds in its Wallet in accordance with Clause 7.3. The Marketplace may deduct the applicable commission from the Wallet upon the relevant Transaction or at such other stage specified in the applicable Commercial Terms or Policies.", "k": "body" }, { "t": "7.6.4 The Marketplace may deduct any commission, Fee, penalty, compensation, refund, adjustment or other amount properly payable by or recoverable from a Participant from amounts otherwise payable to that Participant, including Settlement amounts, subject to this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "7.6.5 Where the Participant does not maintain sufficient Wallet balance to meet an amount payable to the Marketplace, the unpaid amount may result in a negative Wallet balance and the Marketplace may restrict further Transactions or Platform functionality in accordance with Clause 7.3.", "k": "body" }, { "t": "7.6.6 The Marketplace shall bear payment gateway, payment processing and ordinary bank charges incurred by the Marketplace in receiving or processing advance payments through the Platform, unless otherwise expressly stated in the applicable commercial terms or required by Applicable Law.", "k": "body" }, { "t": "7.6.7 Any taxes, duties, levies, withholding or statutory charges applicable to commissions, Fees or other amounts payable to the Marketplace shall be borne or dealt with by the Party legally responsible for the same in accordance with Applicable Law.", "k": "body" }, { "t": "7.6.8 The Marketplace may revise, introduce, reduce, increase or otherwise modify commissions or Fees from time to time by communicating the applicable changes through the Platform, Commercial Terms or Policies.", "k": "body" }, { "t": "7.6.9 Payment or deduction of a commission or Fee shall not make the Marketplace a party to the underlying sale or purchase contract between the Buyer and Seller and shall not transfer any Buyer or Seller obligation to the Marketplace.", "k": "body" }, { "t": "7.7 Payment Records and Transaction Accounting", "k": "h2" }, { "t": "7.7.1 The Marketplace may maintain electronic records of advance payments, payment confirmations, Transaction amounts, commissions, Fees, refunds, adjustments, deductions, Settlement amounts and other payment-related entries arising from Transactions processed through the Platform.", "k": "body" }, { "t": "7.7.2 The Marketplace may rely on its Platform Records, administrative system records, payment confirmations and information received from relevant payment service providers, banks or financial institutions for recording and administering payment and Settlement activities.", "k": "body" }, { "t": "7.7.3 The Participant shall promptly notify the Marketplace of any material discrepancy, duplicate payment, incorrect payment, unauthorised payment or other material error relating to a Transaction or payment recorded on the Platform.", "k": "body" }, { "t": "7.7.4 The Marketplace may investigate and correct any genuine accounting, payment or recording error identified in its records and may make corresponding adjustments to the relevant Transaction, Settlement or Wallet.", "k": "body" }, { "t": "7.7.5 The Marketplace may retain payment and Settlement records for such period as it considers reasonably necessary for accounting, taxation, audit, dispute resolution, fraud prevention, regulatory compliance, legal requirements and enforcement of this Agreement.", "k": "body" }, { "t": "7.7.6 Platform Records relating to payments, Transactions, Settlements, refunds and adjustments may be used as evidence for administering Transactions and resolving disputes, subject to Applicable Law.", "k": "body" }, { "t": "7.7.7 The Marketplace may provide relevant payment or Transaction records to the concerned Participant, payment service provider, bank, governmental or regulatory authority, or other authorised person where reasonably required for administration, dispute resolution, compliance, legal or regulatory purposes.", "k": "body" }, { "t": "7.7.8 The maintenance or display of payment, Wallet or Settlement records by the Marketplace shall not constitute a representation or guarantee that the underlying payment obligation between a Buyer and Seller has been fulfilled, except to the extent expressly recorded as received or settled through the Platform.", "k": "body" }, { "t": "7.8 Payment Security, Authorisation and Fraud Prevention", "k": "h2" }, { "t": "7.8.1 The Participant shall use only its own authorised payment methods, bank accounts, credentials and other payment instruments when making or receiving payments through or in connection with the Platform.", "k": "body" }, { "t": "7.8.2 The Participant shall ensure that all payment instructions, payment details and confirmations submitted through the Platform are accurate, authorised and lawfully provided.", "k": "body" }, { "t": "7.8.3 The Participant shall not use the Platform to initiate, receive, route or facilitate any payment arising from fraud, unauthorised activity, unlawful transactions, money laundering, misrepresentation or any other prohibited activity.", "k": "body" }, { "t": "7.8.4 The Marketplace may undertake reasonable checks, verification or review of payment-related activity where it identifies or reasonably suspects fraud, unauthorised activity, unusual activity, payment misuse, security risk or violation of this Agreement or Applicable Law.", "k": "body" }, { "t": "7.8.5 Where reasonably necessary, the Marketplace may delay, restrict, suspend, reject or place a hold on a payment, Transaction or Settlement while conducting such review or taking measures required for security, fraud prevention, compliance or protection of Participants and the Platform.", "k": "body" }, { "t": "7.8.6 The Participant shall reasonably cooperate with the Marketplace in relation to payment verification, fraud investigation, disputed payments, chargebacks, reversals or other payment-related reviews and shall provide information or evidence reasonably requested for such purposes.", "k": "body" }, { "t": "7.8.7 The Marketplace shall not be responsible for any loss arising from a Participant's unauthorised disclosure, misuse or compromise of its Account credentials, payment credentials, authentication information or other security information, except to the extent directly caused by the Marketplace's failure to comply with its obligations under Applicable Law.", "k": "body" }, { "t": "7.8.8 Any action taken by the Marketplace under this Section shall be without prejudice to its rights to recover amounts, restrict Accounts, suspend Transactions, adjust Wallet balances or take any other action available under this Agreement, Policies or Applicable Law.", "k": "body" }, { "t": "7.9 Payment Disputes and Chargebacks", "k": "h2" }, { "t": "7.9.1 Any dispute relating to a payment, including an unauthorised payment, duplicate payment, incorrect payment, payment failure, reversal or chargeback, shall be addressed in accordance with the applicable payment process, Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.9.2 Where a payment relating to an advance-paid Transaction is disputed by the Buyer or is subject to a chargeback, reversal or payment-related investigation, the Marketplace may place the relevant Transaction and Settlement amount on hold until the matter is resolved or an appropriate action is determined.", "k": "body" }, { "t": "7.9.3 The Marketplace may review relevant Platform Records, payment confirmations, Transaction records, communications and information received from the applicable bank, payment gateway, payment service provider or other relevant party in determining the appropriate action.", "k": "body" }, { "t": "7.9.4 Where a chargeback, reversal or other payment adjustment results in an amount becoming recoverable from the Seller, the Marketplace may deduct or recover such amount from the Seller's Settlement, Wallet balance or other amounts payable to the Seller.", "k": "body" }, { "t": "7.9.5 If the amount recoverable from the Seller exceeds the amount available in the Seller's Settlement or Wallet, the remaining amount may be recorded as an outstanding amount and reflected as a negative Wallet balance in accordance with Clause 7.3.", "k": "body" }, { "t": "7.9.6 The Marketplace may take reasonable measures to protect the Buyer, Seller and Platform from payment fraud, unauthorised transactions or other payment-related risks, including withholding, reversing, cancelling or adjusting a Transaction or payment where reasonably necessary.", "k": "body" }, { "t": "7.9.7 The Marketplace shall not be responsible for any loss, delay, rejection, reversal, chargeback or other consequence arising from the acts, omissions, decisions, systems or failures of a bank, payment gateway, payment service provider, financial institution or other third party, except to the extent such liability cannot be excluded under Applicable Law.", "k": "body" }, { "t": "7.9.8 A payment dispute or chargeback shall not, by itself, extinguish the underlying payment or other contractual obligation of the Buyer or Seller, except to the extent such obligation is discharged, adjusted or otherwise affected pursuant to the applicable Transaction terms, settlement decision or Applicable Law.", "k": "body" }, { "t": "7.10 Payment and Settlement Limitations", "k": "h2" }, { "t": "7.10.1 The Marketplace's role in receiving, holding, processing, recording and releasing advance payments is limited to administering the applicable Platform Transaction and Settlement process in accordance with this Agreement, the applicable Policies and Applicable Law.", "k": "body" }, { "t": "7.10.2 The Marketplace does not guarantee the financial performance, solvency, creditworthiness or payment obligations of any Buyer or Seller and shall not be responsible for any payment obligation that remains directly between the Buyer and Seller.", "k": "body" }, { "t": "7.10.3 The Marketplace shall not be deemed to have provided credit, financing, lending, insurance or any financial accommodation merely because it receives or holds an advance payment pending completion of a Transaction.", "k": "body" }, { "t": "7.10.4 The Marketplace shall not be responsible for any delay, failure, loss or interruption in payment processing or Settlement caused by circumstances beyond its reasonable control, including failure of banks, payment service providers, payment gateways, financial institutions, communication networks or other third-party systems.", "k": "body" }, { "t": "7.10.5 Nothing in this Agreement shall be interpreted as excluding, restricting or overriding any mandatory requirement imposed upon the Marketplace, a Participant or any payment-related activity under Applicable Law.", "k": "body" }, { "t": "7.10.6 The Marketplace may modify the manner, mechanism or process through which payments, Wallet balances, refunds or Settlements are administered where reasonably required for operational, technical, security, regulatory, legal or commercial reasons, subject to Applicable Law.", "k": "body" }, { "t": "7.10.7 Except for amounts actually received and held by the Marketplace in connection with an advance-paid Transaction, the Marketplace shall have no responsibility for payments made directly between Participants, including payments made under credit or deferred-payment arrangements.", "k": "body" }, { "t": "7.10.8 Nothing in this Section shall limit any liability or obligation of the Marketplace that cannot lawfully be excluded or limited under Applicable Law.", "k": "body" }, { "t": "7.11 Participant Responsibility for Payment Obligations", "k": "h2" }, { "t": "7.11.1 The Buyer shall remain solely responsible for making all amounts payable in respect of its Transactions, including advance payments, credit payments, applicable taxes, charges and other amounts agreed with the Seller.", "k": "body" }, { "t": "7.11.2 The Seller shall remain solely responsible for all amounts payable or refundable by the Seller in connection with a Transaction, including refunds, compensation, penalties, commissions, Fees, adjustments and other amounts recoverable under this Agreement or the applicable Transaction terms.", "k": "body" }, { "t": "7.11.3 Where a Buyer makes an advance payment through the Platform, the Marketplace's receipt and holding of such amount shall not relieve the Buyer or Seller of their respective contractual obligations relating to the underlying Transaction.", "k": "body" }, { "t": "7.11.4 Where a Seller provides credit to a Buyer, the Seller shall remain solely responsible for managing, monitoring and recovering amounts payable under such credit arrangement.", "k": "body" }, { "t": "7.11.5 The Marketplace shall have no obligation to advance, fund, guarantee or otherwise make payment on behalf of a Buyer or Seller in respect of any amount that is not actually received or otherwise payable through the Marketplace's applicable Settlement process.", "k": "body" }, { "t": "7.11.6 A Participant shall not represent to any other Participant that the Marketplace has guaranteed, insured, financed or otherwise assumed responsibility for its payment obligations, credit obligations or other financial commitments.", "k": "body" }, { "t": "7.11.7 Nothing in this Section shall prevent the Marketplace from exercising its rights to hold, release, refund, deduct, adjust, recover or otherwise administer amounts in accordance with this Agreement, applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.12 Payment Processing Errors and Corrections", "k": "h2" }, { "t": "7.12.1 Where an error occurs in relation to a payment, Transaction, Settlement, refund, deduction, adjustment or Wallet entry, the Marketplace may investigate the relevant records and make such correction or adjustment as is reasonably necessary to reflect the correct amount.", "k": "body" }, { "t": "7.12.2 Where the Marketplace has incorrectly credited, released, refunded, deducted or otherwise accounted for an amount, the Marketplace may correct the relevant records and recover or adjust the resulting difference against the Participant's Wallet, Settlement or other amounts payable to the Participant.", "k": "body" }, { "t": "7.12.3 Where an amount has been incorrectly credited to a Participant due to a technical error, duplicate payment, incorrect recording, payment reversal or other reason, the Participant shall be liable to return or permit adjustment of the incorrectly credited amount.", "k": "body" }, { "t": "7.12.4 Where an error results in an amount being payable to a Participant, the Marketplace may make the necessary correction and credit or release such amount through the applicable Settlement or Wallet process.", "k": "body" }, { "t": "7.12.5 The Participant shall reasonably cooperate with the Marketplace in investigating payment discrepancies and shall provide such information or evidence as may reasonably be required to identify and correct the error.", "k": "body" }, { "t": "7.12.6 Correction of a payment or accounting error shall not affect any valid underlying obligation between the Buyer and Seller, except to the extent that such obligation is discharged, refunded or otherwise adjusted as a result of the correction.", "k": "body" }, { "t": "7.12.7 The Marketplace may make corrections to payment, Settlement or Wallet records after completion of a Transaction where such correction is reasonably necessary to address an error, reversal, refund, chargeback, dispute, fraud, statutory requirement or other legitimate adjustment.", "k": "body" }, { "t": "7.12.8 Nothing in this Section shall prevent a Participant from raising a genuine dispute regarding a payment or accounting correction in accordance with the applicable dispute procedures under this Agreement.", "k": "body" }, { "t": "7.13 Set-Off and Recovery of Amounts Due", "k": "h2" }, { "t": "7.13.1 The Marketplace may set off, deduct or adjust any amount due and payable by a Participant against any amount otherwise payable or becoming payable by the Marketplace to such Participant, including any Settlement amount, Wallet balance, refund, credit or other amount.", "k": "body" }, { "t": "7.13.2 Amounts that may be recovered or adjusted under this Section include, without limitation, commissions, Fees, penalties, refunds, compensation, chargebacks, payment reversals, Transaction adjustments, damages, costs, amounts incorrectly credited and other amounts properly due under this Agreement, applicable Transaction terms or Policies.", "k": "body" }, { "t": "7.13.3 Where an amount remains outstanding after adjustment against available Settlement or Wallet balances, the Participant shall remain liable for the outstanding amount and shall pay such amount within the period specified by the Marketplace.", "k": "body" }, { "t": "7.13.4 The Marketplace may continue to recover an outstanding amount by adjusting it against subsequent Settlement amounts or other amounts payable to the Participant until the outstanding amount has been fully recovered.", "k": "body" }, { "t": "7.13.5 Where a Participant has an outstanding amount or negative Wallet balance, the Marketplace may restrict, suspend or prevent the Participant from initiating or completing further Transactions or accessing specified Platform features until the outstanding amount is paid or otherwise resolved.", "k": "body" }, { "t": "7.13.6 A Participant shall not set off or withhold any amount claimed to be payable by the Marketplace against amounts due from the Participant, except where such right is expressly agreed by the Marketplace in writing or is mandatorily available under Applicable Law.", "k": "body" }, { "t": "7.13.7 The exercise of any right of deduction, adjustment, set-off or recovery by the Marketplace shall be without prejudice to any other rights or remedies available to the Marketplace under this Agreement, applicable Transaction terms, Policies or Applicable Law.", "k": "body" }, { "t": "7.14 Payment-Related Participant Obligations", "k": "h2" }, { "t": "7.14.1 Each Participant shall provide accurate and complete payment, billing, banking and other financial information wherever such information is required for processing, Settlement, refund, reconciliation or other Platform purposes.", "k": "body" }, { "t": "7.14.2 A Participant shall ensure that any bank account or payment instrument provided to the Marketplace is lawfully held or authorised for use by that Participant and is capable of receiving or making the applicable payments.", "k": "body" }, { "t": "7.14.3 The Participant shall promptly notify the Marketplace of any change, suspension, closure or restriction affecting its relevant bank account, payment instrument or other payment details.", "k": "body" }, { "t": "7.14.4 The Participant shall not provide false, misleading, fraudulent or unauthorised payment information or use another person's or entity's bank account, payment instrument or payment credentials without lawful authority.", "k": "body" }, { "t": "7.14.5 The Participant shall be responsible for any loss, cost, liability, delay or other consequence arising from inaccurate, incomplete, outdated or unauthorised payment information provided by it, to the extent attributable to such information.", "k": "body" }, { "t": "7.14.6 The Participant shall comply with all applicable payment, taxation, invoicing, accounting, anti-fraud and other statutory requirements applicable to its Transactions and payment obligations.", "k": "body" }, { "t": "7.14.7 The Marketplace may request updated or additional payment-related information where reasonably required for Settlement, refunds, payment security, fraud prevention, accounting, compliance or other legitimate Platform purposes.", "k": "body" }, { "t": "7.14.8 Failure by a Participant to provide required or valid payment information may result in delay or inability to process a Settlement, refund or other payment, and the Marketplace shall not be responsible for such delay to the extent caused by the Participant.", "k": "body" }, { "t": "7.15 Finality of Settlement", "k": "h2" }, { "t": "7.15.1 Subject to the provisions of this Agreement, a Settlement made to a Seller following successful completion of the applicable Transaction shall constitute the Marketplace's Settlement of the amount determined to be payable to the Seller for that Transaction.", "k": "body" }, { "t": "7.15.2 Settlement of a Transaction shall not prevent the Marketplace from making any subsequent deduction, adjustment or recovery arising from a refund, return, chargeback, payment reversal, fraud, dispute, accounting error, statutory requirement, penalty or other amount properly recoverable under this Agreement, the applicable Transaction terms or Policies.", "k": "body" }, { "t": "7.15.3 Where any subsequent deduction or recovery is required after Settlement, the Marketplace may recover the applicable amount from the Seller's subsequent Settlement amounts, Wallet balance or otherwise as permitted under this Agreement.", "k": "body" }, { "t": "7.15.4 The Marketplace shall endeavour to process eligible Settlements, refunds and adjustments at the earliest practicable time and shall not unnecessarily delay amounts that have become payable.", "k": "body" }, { "t": "7.15.5 Settlement or release of funds by the Marketplace shall not constitute a representation or warranty regarding the quality, quantity, authenticity, legality, conformity or performance of the Products, nor shall it release the Buyer or Seller from obligations that survive completion of the Transaction.", "k": "body" }, { "t": "7.15.6 The rights of the Marketplace to make post-Settlement adjustments, deductions or recoveries shall survive completion, closure or Settlement of the relevant Transaction to the extent permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.16 Payment and Settlement Disputes", "k": "h2" }, { "t": "7.16.1 A Participant may raise a dispute concerning a payment, refund, deduction, Settlement, Wallet entry or other payment-related matter by using the dispute mechanism or communication channel specified by the Marketplace.", "k": "body" }, { "t": "7.16.2 A payment or Settlement dispute shall be supported by such information, documents or other evidence as may reasonably be required by the Marketplace for reviewing the matter.", "k": "body" }, { "t": "7.16.3 The Marketplace may review Platform Records, Transaction records, payment confirmations, delivery records, communications, Wallet entries and other relevant information available to it in connection with a payment or Settlement dispute.", "k": "body" }, { "t": "7.16.4 The Marketplace may, based on its review, make an administrative determination for the purposes of processing the applicable refund, deduction, adjustment or Settlement, without thereby becoming a party to or assuming responsibility for the underlying commercial relationship between the Buyer and Seller.", "k": "body" }, { "t": "7.16.5 During review of a payment or Settlement dispute, the Marketplace may temporarily hold or restrict the relevant amount, Settlement or Transaction where reasonably necessary to protect the interests of the Parties, prevent wrongful release of funds or complete the review.", "k": "body" }, { "t": "7.16.6 The Marketplace may communicate the outcome of its administrative review and implement the corresponding refund, deduction, adjustment or Settlement in accordance with this Agreement and applicable Policies.", "k": "body" }, { "t": "7.16.7 A Marketplace determination for payment or Settlement purposes shall not prevent a Buyer or Seller from exercising any right or remedy available against the other Party under the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "7.16.8 The Marketplace shall not be required to hold funds longer than reasonably necessary for reviewing and resolving a payment or Settlement dispute and shall endeavour to release any undisputed or otherwise eligible amount at the earliest practicable time.", "k": "body" }, { "t": "7.17 No Assumption of Banking or Financial Services", "k": "h2" }, { "t": "7.17.1 Except for receiving and holding advance payments for the limited purpose of administering the applicable Platform Transaction and completing the Settlement process, the Marketplace does not undertake to provide banking, lending, financing, credit, insurance or other financial services to Participants.", "k": "body" }, { "t": "7.17.2 The Marketplace does not create or maintain any credit facility for a Buyer or Seller. Any credit or deferred payment facility offered in connection with a Transaction is provided solely by the Seller to the Buyer in accordance with Clause 7.2.", "k": "body" }, { "t": "7.17.3 The Marketplace's receipt or holding of an advance payment shall not create a debtor-creditor relationship between the Marketplace and the Buyer or Seller beyond the obligations expressly arising under this Agreement and the applicable Transaction.", "k": "body" }, { "t": "7.17.4 The Marketplace shall not be responsible for any payment obligation that is required to be performed directly between a Buyer and Seller, including any amount payable under a credit or deferred-payment arrangement.", "k": "body" }, { "t": "7.17.5 Nothing in this Agreement shall be interpreted as requiring the Marketplace to undertake any activity that is prohibited or restricted under Applicable Law, and the Marketplace may modify its payment, fund-holding or Settlement mechanism where reasonably necessary to comply with Applicable Law.", "k": "body" }, { "t": "7.17.6 Where any provision of this Agreement relating to payment, fund holding or Settlement is inconsistent with a mandatory requirement of Applicable Law, such requirement shall prevail to the extent of the inconsistency, without otherwise affecting the remaining provisions of this Agreement.", "k": "body" }, { "t": "7.18 Completion of Payment and Settlement Obligations", "k": "h2" }, { "t": "7.18.1 The payment and Settlement obligations applicable to a Transaction shall be determined by whether the Transaction is an advance-paid Transaction or a credit Transaction.", "k": "body" }, { "t": "7.18.2 For an advance-paid Transaction, the Marketplace shall administer the receipt, holding, release, refund and adjustment of funds in accordance with Clause 7.1 and the applicable Transaction terms and Policies.", "k": "body" }, { "t": "7.18.3 For a credit Transaction, the Buyer and Seller shall independently perform their respective payment obligations in accordance with the credit terms agreed between them, and the Marketplace shall have no obligation to receive, hold or settle such payment.", "k": "body" }, { "t": "7.18.4 Completion of a Settlement by the Marketplace shall not affect any continuing obligation of the Buyer or Seller relating to the Products, warranty, returns, refunds, claims, taxes, indemnities, disputes or any other obligation that survives completion of the Transaction.", "k": "body" }, { "t": "7.18.5 The Marketplace may continue to maintain relevant payment, Transaction, Wallet and Settlement records after completion of a Transaction for the purposes permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.18.6 Any amount remaining payable by a Participant following completion of a Transaction, including an amount arising from a refund, compensation, chargeback, reversal, adjustment, penalty or other valid claim, shall remain recoverable by the Marketplace in accordance with this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "7.19 Marketplace's Right to Suspend or Restrict Settlement", "k": "h2" }, { "t": "7.19.1 The Marketplace may temporarily withhold, suspend or restrict a Settlement amount where reasonably necessary due to a pending dispute, refund, return, chargeback, payment reversal, suspected fraud, suspected unauthorised activity, regulatory requirement, breach of this Agreement or Policies, or any other circumstance that may materially affect the proper Settlement of the relevant Transaction.", "k": "body" }, { "t": "7.19.2 Any hold imposed under this Section shall, to the extent practicable, be limited to the amount reasonably connected with the relevant dispute, claim, adjustment, risk or outstanding obligation.", "k": "body" }, { "t": "7.19.3 The Marketplace may release any portion of the Settlement that is not subject to such hold once the applicable conditions for release have been satisfied.", "k": "body" }, { "t": "7.19.4 The Marketplace shall endeavour to resolve the circumstances giving rise to a hold at the earliest practicable time and shall release the applicable Settlement promptly once the basis for withholding has ceased to exist.", "k": "body" }, { "t": "7.19.5 A temporary hold or restriction under this Section shall not constitute a forfeiture of the Seller's funds and shall not, by itself, extinguish any rights or obligations of the Buyer or Seller under the relevant Transaction.", "k": "body" }, { "t": "7.19.6 The Marketplace may communicate the reason for a Settlement hold to the affected Participant where reasonably practicable and where such disclosure is not prohibited by Applicable Law, security requirements, confidentiality obligations or fraud-prevention considerations.", "k": "body" }, { "t": "7.20 Participant's Responsibility for Bank and Payment Details", "k": "h2" }, { "t": "7.20.1 Each Participant shall provide accurate and complete bank account, payment and other Settlement-related information wherever required by the Marketplace for processing Settlement, refunds or other payments.", "k": "body" }, { "t": "7.20.2 The Participant shall ensure that the bank account and other payment details provided to the Marketplace belong to or are lawfully authorised for use by the Participant.", "k": "body" }, { "t": "7.20.3 The Participant shall be solely responsible for ensuring that the bank account provided for receiving Settlement is active, valid and capable of receiving the applicable payment.", "k": "body" }, { "t": "7.20.4 The Participant shall promptly update the Marketplace regarding any change, closure, suspension, restriction or other circumstance affecting its bank account or Settlement-related information.", "k": "body" }, { "t": "7.20.5 The Marketplace may rely on the latest bank and payment details provided or verified by the Participant when processing Settlement or other payments.", "k": "body" }, { "t": "7.20.6 The Marketplace shall not be responsible for any delay, failure, misdirection or loss resulting from incorrect, incomplete, outdated or unauthorised bank or payment information provided by the Participant.", "k": "body" }, { "t": "7.20.7 Where a Settlement cannot be completed because the bank account or payment details provided by the Participant are invalid, inactive, restricted or otherwise incapable of receiving the payment, the Marketplace may hold the applicable amount until valid payment details are provided and verified.", "k": "body" }, { "t": "7.20.8 The Participant shall reasonably cooperate with the Marketplace in relation to verification, correction or updating of bank and payment details where required for Settlement, refund, security, fraud prevention, accounting or compliance purposes.", "k": "body" }, { "t": "7.21 Payment Processing by Third-Party Providers", "k": "h2" }, { "t": "7.21.1 The Marketplace may use banks, payment gateways, payment processors or other authorised third-party service providers for processing advance payments, payment confirmations, refunds or other payment-related activities connected with the Platform.", "k": "body" }, { "t": "7.21.2 Where a third-party payment provider is used, the applicable payment transaction may also be subject to the terms, conditions, privacy policies and operational procedures of that provider.", "k": "body" }, { "t": "7.21.3 The Marketplace may rely on payment status, confirmation, reversal, failure or other transaction information received from the relevant bank, payment gateway, payment processor or other authorised service provider.", "k": "body" }, { "t": "7.21.4 A payment may be treated as successfully received only after the Marketplace receives or records the applicable payment confirmation in accordance with its Platform and payment-processing procedures.", "k": "body" }, { "t": "7.21.5 Where a payment is delayed, rejected, reversed, failed, refunded or otherwise affected due to circumstances attributable to a bank, payment gateway, payment processor, payment network or other third-party provider, the Marketplace may take such corresponding action as is reasonably necessary to update the Transaction, Settlement or payment records.", "k": "body" }, { "t": "7.21.6 The Marketplace shall not be responsible for failures, delays, outages, errors or interruptions caused by third-party payment providers or financial institutions, except to the extent such liability cannot lawfully be excluded.", "k": "body" }, { "t": "7.21.7 The Marketplace may provide relevant payment or Transaction information to such third-party providers where reasonably necessary to process payments, refunds, verification, fraud prevention, reconciliation, compliance or other authorised payment-related activities.", "k": "body" }, { "t": "7.21.8 Use of a third-party payment provider shall not alter the allocation of payment obligations between Buyer, Seller and Marketplace under this Agreement.", "k": "body" }, { "t": "7.22 Payment Instructions and Authorisation", "k": "h2" }, { "t": "7.22.1 The Marketplace may provide payment instructions, payment links, bank details, payment references or other payment-related information to a Participant through the Platform or the Participant's registered communication details.", "k": "body" }, { "t": "7.22.2 The Participant shall make payments only through the payment methods and payment instructions specified or authorised by the Marketplace for the relevant Transaction.", "k": "body" }, { "t": "7.22.3 The Participant shall verify the relevant Transaction amount, payment reference and other payment details before initiating payment and shall promptly notify the Marketplace of any suspected error, unauthorised instruction or suspicious payment request.", "k": "body" }, { "t": "7.22.4 The Marketplace may require additional verification, confirmation or information before recognising, processing, releasing, refunding or adjusting a payment where reasonably necessary for security, fraud prevention, compliance or operational purposes.", "k": "body" }, { "t": "7.22.5 A payment made by a Participant through an unauthorised method, to an unauthorised account or contrary to the payment instructions provided through the Platform shall be made at the Participant's own risk, unless otherwise required under Applicable Law.", "k": "body" }, { "t": "7.22.6 The Marketplace may refuse to recognise or process a payment where it has reasonable grounds to believe that the payment is fraudulent, unauthorised, incorrectly identified, unlawful or otherwise inconsistent with the applicable Transaction.", "k": "body" }, { "t": "7.22.7 The Participant shall reasonably cooperate with the Marketplace in verifying the source, purpose, status or authorisation of any payment where such verification is reasonably required.", "k": "body" }, { "t": "7.23 Payment Confirmation and Proof of Payment", "k": "h2" }, { "t": "7.23.1 A Participant making an advance payment shall provide such payment details, transaction reference, payment confirmation or other information as may be required through the Platform.", "k": "body" }, { "t": "7.23.2 Submission of a payment reference, screenshot, bank transaction details or other proof by a Participant shall not, by itself, constitute confirmation that the payment has been successfully received by the Marketplace.", "k": "body" }, { "t": "7.23.3 For purposes of an advance-paid Transaction, payment shall be treated as received only when the Marketplace confirms or records the payment through its applicable administrative or payment-processing system in accordance with Clause 7.1.", "k": "body" }, { "t": "7.23.4 The Marketplace may verify payment information against its bank records, payment processor records, Platform records or other available information before confirming receipt.", "k": "body" }, { "t": "7.23.5 Where payment cannot be verified or the information provided is inconsistent, incomplete or disputed, the Marketplace may defer confirmation of payment and may request additional information or evidence from the Participant.", "k": "body" }, { "t": "7.23.6 The Participant shall not instruct or require the Seller to treat an advance payment as received solely on the basis of a payment initiation, screenshot, reference number or other unverified payment evidence.", "k": "body" }, { "t": "7.23.7 Any payment confirmation issued or displayed by the Platform shall relate only to the receipt or processing status of the payment and shall not constitute confirmation of Product quality, delivery, acceptance, Transaction completion or fulfilment of any other obligation.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.24 Payment Reconciliation and Mismatch", "k": "h2" }, { "t": "7.24.1 The Marketplace may compare payment information received from the Participant with Platform Records, bank records, payment processor records and other relevant records for the purpose of confirming and accounting for advance payments.", "k": "body" }, { "t": "7.24.2 Where any mismatch is identified between the amount paid, the amount recorded, the applicable Transaction Value or any other payment information, the Marketplace may investigate and determine the appropriate accounting treatment.", "k": "body" }, { "t": "7.24.3 The Marketplace may request additional information or supporting evidence from the Participant where reasonably necessary to resolve a payment mismatch.", "k": "body" }, { "t": "7.24.4 Until a material payment mismatch is resolved, the Marketplace may defer confirmation of the payment or restrict the related Order, Transaction or Settlement to the extent reasonably necessary.", "k": "body" }, { "t": "7.24.5 Any excess amount received may be refunded, credited or otherwise adjusted by the Marketplace in accordance with the applicable Transaction terms and Policies.", "k": "body" }, { "t": "7.24.6 Any shortfall in payment shall remain payable by the Buyer, and the Marketplace may require the Buyer to complete the outstanding payment before proceeding with the relevant Transaction.", "k": "body" }, { "t": "7.24.7 Correction of a payment mismatch shall not, by itself, modify the agreed Product quantity, Pricing, delivery terms or other commercial terms of the Transaction unless expressly agreed by the Buyer and Seller or otherwise permitted under this Agreement.", "k": "body" }, { "t": "7.24.8 The Marketplace may correct related Wallet, Settlement and Platform Records where required to reflect the final verified payment position.", "k": "body" }, { "t": "7.25 Currency and Payment Amounts", "k": "h2" }, { "t": "7.25.1 Unless otherwise specified in the applicable Transaction, all amounts payable through the Platform, including Product Pricing, Fees, commissions, refunds, adjustments and Settlement amounts, shall be denominated in Indian Rupees (INR).", "k": "body" }, { "t": "7.25.2 The Buyer shall ensure that the amount paid for an advance-paid Transaction corresponds to the amount specified or otherwise payable under the applicable Order, Transaction or payment instruction.", "k": "body" }, { "t": "7.25.3 Where taxes, charges, discounts, freight or other amounts form part of the Transaction amount, the applicable amount shall be determined in accordance with the Quotation, PO, SO, invoice, Platform Records or other agreed Transaction terms.", "k": "body" }, { "t": "7.25.4 The Marketplace may calculate and display the amount payable, refundable or available for Settlement based on the applicable Transaction records and agreed commercial terms.", "k": "body" }, { "t": "7.25.5 Any difference arising from rounding, calculation error, tax adjustment, refund, cancellation, chargeback, deduction or other valid adjustment may be corrected through the relevant Transaction, Wallet or Settlement records.", "k": "body" }, { "t": "7.25.6 Unless expressly stated otherwise, the Marketplace shall not be responsible for any foreign exchange conversion, foreign exchange loss or currency fluctuation arising from a payment made by a Participant.", "k": "body" }, { "t": "7.26 Payment and Settlement Cut-Offs", "k": "h2" }, { "t": "7.26.1 The Marketplace may specify cut-off times, processing windows or other operational timelines applicable to advance payments, refunds, adjustments and Settlements.", "k": "body" }, { "t": "7.26.2 Where a payment or other payment-related instruction is received after an applicable cut-off time, the Marketplace may process it on the next applicable processing cycle.", "k": "body" }, { "t": "7.26.3 Any processing timeline communicated by the Marketplace shall be an operational estimate unless expressly stated otherwise and may be affected by banks, payment processors, payment networks or other third-party service providers.", "k": "body" }, { "t": "7.26.4 The Marketplace shall endeavour to process eligible payments, refunds and Settlements at the earliest practicable time after the applicable conditions are satisfied.", "k": "body" }, { "t": "7.26.5 No Participant shall be entitled to treat an operational processing timeline as extending, reducing or otherwise modifying the contractual payment, delivery, dispute or other obligations of the Buyer or Seller unless expressly provided in the applicable Transaction terms.", "k": "body" }, { "t": "7.27 Payment-Related Communications and Notices", "k": "h2" }, { "t": "7.27.1 The Marketplace may communicate payment, refund, Settlement, Wallet, Transaction and other payment-related information to a Participant through the Platform, registered email address, registered mobile number or other communication channel made available by the Marketplace.", "k": "body" }, { "t": "7.27.2 Payment-related communications may include payment instructions, payment confirmations, payment failures, refund status, Settlement status, Wallet balances, deductions, adjustments, outstanding amounts, disputes, holds and other relevant information.", "k": "body" }, { "t": "7.27.3 The Participant shall regularly review payment-related information available through the Platform and its registered communication details and shall promptly notify the Marketplace of any material error, unauthorised activity or discrepancy.", "k": "body" }, { "t": "7.27.4 A communication relating to a payment, refund or Settlement shall not by itself modify the underlying Transaction terms unless the communication expressly records or confirms such modification in accordance with this Agreement.", "k": "body" }, { "t": "7.27.5 The Marketplace may rely on the Participant's registered and verified communication details for sending payment-related communications, and the Participant shall remain responsible for maintaining access to such details.", "k": "body" }, { "t": "7.27.6 Failure by a Participant to review or receive a payment-related communication due to inaccurate, outdated, inaccessible or incorrectly provided contact information shall not, to the extent permitted by Applicable Law, make the Marketplace responsible for the resulting consequences.", "k": "body" }, { "t": "7.28 Payment Records and Audit Trail", "k": "h2" }, { "t": "7.28.1 The Marketplace may maintain an electronic audit trail of payment-related activities, including payment initiation, payment confirmation, payment receipt, refunds, reversals, deductions, adjustments, Settlement, Wallet entries and other relevant payment events.", "k": "body" }, { "t": "7.28.2 Such records may include the date and time of the relevant activity, Transaction reference, payment reference, amount, payment status, applicable Participant, and other information reasonably required for accounting, administration, dispute resolution, fraud prevention or compliance purposes.", "k": "body" }, { "t": "7.28.3 The Marketplace may use Platform Records, bank records, payment processor records and other relevant electronic records to determine the status and accounting of a payment or Settlement.", "k": "body" }, { "t": "7.28.4 Subject to Applicable Law, such electronic records may be relied upon as evidence of the relevant payment-related activity, instruction, confirmation or adjustment.", "k": "body" }, { "t": "7.28.5 A Participant shall promptly notify the Marketplace if it reasonably believes that any material payment record is incorrect, duplicated, unauthorised or otherwise inconsistent with the applicable Transaction.", "k": "body" }, { "t": "7.28.6 The Marketplace may investigate and correct any payment-related record where it identifies an error or receives credible information indicating that an adjustment is required.", "k": "body" }, { "t": "7.28.7 The Marketplace may retain payment records for such period as it reasonably considers necessary for accounting, tax, audit, dispute resolution, fraud prevention, regulatory, legal or other legitimate business purposes.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.29 Payment-Related Confidentiality and Disclosure", "k": "h2" }, { "t": "7.29.1 The Marketplace may access, use, store and process payment, banking, Transaction and Settlement information of a Participant to the extent reasonably necessary for operating the Platform, processing payments, administering Wallet and Settlement, resolving disputes, preventing fraud, maintaining records, providing support and complying with Applicable Law.", "k": "body" }, { "t": "7.29.2 The Marketplace may disclose such information to its employees, authorised representatives, banks, payment processors, technology service providers, professional advisers, auditors, insurers, governmental or regulatory authorities and other persons where reasonably necessary for the purposes permitted under this Agreement or required by Applicable Law.", "k": "body" }, { "t": "7.29.3 The Marketplace may also disclose relevant payment or Settlement information to the Buyer or Seller involved in the applicable Transaction to the extent reasonably necessary for administering, confirming, resolving or completing that Transaction.", "k": "body" }, { "t": "7.29.4 The Marketplace shall not be required to disclose confidential payment, banking or financial information of one Participant to another Participant except where reasonably necessary for the applicable Transaction, dispute resolution, legal compliance or otherwise permitted by the Participant or Applicable Law.", "k": "body" }, { "t": "7.29.5 The obligations and rights under this Clause are subject to the Marketplace's applicable privacy and data protection obligations and shall not restrict any disclosure required or permitted under Applicable Law.", "k": "body" }, { "t": "7.30 Payment-Related Taxes and Statutory Compliance", "k": "h2" }, { "t": "7.30.1 Each Participant shall be responsible for all taxes, duties, levies, cess, withholding, collection, reporting and other statutory obligations applicable to payments or Transactions undertaken by such Participant, except to the extent such obligation is expressly imposed on the Marketplace under Applicable Law.", "k": "body" }, { "t": "7.30.2 The Buyer and Seller shall provide accurate GST, tax and other statutory information reasonably required for processing, recording, invoicing, Settlement, refund or other payment-related activities.", "k": "body" }, { "t": "7.30.3 The Marketplace may make or facilitate any deduction, withholding, collection or statutory payment from amounts otherwise payable to a Participant where required under Applicable Law.", "k": "body" }, { "t": "7.30.4 Any amount deducted, withheld or collected by the Marketplace pursuant to Applicable Law may be reflected in the relevant Transaction, Wallet or Settlement records and shall be treated as having been paid, withheld or collected on behalf of the relevant Participant to the extent permitted by Applicable Law.", "k": "body" }, { "t": "7.30.5 A Participant shall be solely responsible for the accuracy of tax information provided by it and for any tax liability, interest, penalty, loss or other consequence arising from inaccurate, incomplete or misleading information provided by such Participant.", "k": "body" }, { "t": "7.30.6 The Marketplace may request information or documents reasonably necessary to comply with tax, accounting, reporting or other statutory requirements relating to payments and Transactions.", "k": "body" }, { "t": "7.30.7 Nothing in this Clause shall be construed as making the Marketplace responsible for determining or advising a Participant on its tax liability, tax treatment, eligibility for exemption, input tax credit or other tax position.", "k": "body" }, { "t": "7.31 Payment-Related Indemnity", "k": "h2" }, { "t": "7.31.1 Each Participant shall indemnify and hold harmless the Marketplace, its directors, officers, employees, representatives and agents from and against claims, losses, liabilities, penalties, damages, costs and reasonable expenses arising out of or relating to:", "k": "body" }, { "t": "(a) inaccurate, incomplete, misleading or unauthorised payment, banking, tax or Settlement information provided by the Participant;", "k": "body" }, { "t": "(b) any unauthorised, fraudulent or unlawful payment activity attributable to the Participant;", "k": "body" }, { "t": "(c) the Participant's failure to fulfil its payment, refund, tax, statutory or other financial obligations under a Transaction or this Agreement;", "k": "body" }, { "t": "(d) any chargeback, reversal, refund, adjustment, penalty or other payment-related liability attributable to the Participant, except to the extent caused by the Marketplace's breach of this Agreement or Applicable Law; or", "k": "body" }, { "t": "(e) any violation by the Participant of Applicable Law in connection with its payment or financial activities through or relating to the Platform.", "k": "body" }, { "t": "7.31.2 The indemnity under this Clause shall not apply to the extent that the relevant claim, loss or liability is finally determined to have resulted directly from the Marketplace's fraud, wilful misconduct or liability that cannot lawfully be excluded.", "k": "body" }, { "t": "7.31.3 The Marketplace may, to the extent permitted by this Agreement and Applicable Law, recover amounts payable under this Clause by deduction, adjustment or set-off against amounts otherwise payable to the Participant, including Settlement amounts or Wallet balances.", "k": "body" }, { "t": "7.32 Payment Processing and Settlement Support", "k": "h2" }, { "t": "7.32.1 The Marketplace may provide reasonable administrative and technical support in relation to payment processing, refunds, Wallet entries and Settlement through the Platform.", "k": "body" }, { "t": "7.32.2 Such support may include providing payment status information, assisting with payment-related queries, reviewing relevant Platform Records, communicating with payment service providers where appropriate, and facilitating resolution of payment-related issues.", "k": "body" }, { "t": "7.32.3 The Marketplace's provision of such support shall not make it responsible for the underlying payment, credit, Product, delivery or other commercial obligations of the Buyer or Seller.", "k": "body" }, { "t": "7.32.4 Participants shall provide timely and accurate information and reasonably cooperate with the Marketplace in resolving payment-related issues.", "k": "body" }, { "t": "7.32.5 The Marketplace may determine the appropriate administrative action in relation to a payment or Settlement issue based on the available Platform Records, payment information, Transaction terms, evidence provided by the Participants and applicable Policies.", "k": "body" }, { "t": "7.32.6 Any administrative action taken by the Marketplace shall be without prejudice to the rights and remedies of the Buyer or Seller against each other under the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "7.32 Payment Processing and Settlement Support", "k": "h2" }, { "t": "7.32.1 The Marketplace may provide reasonable administrative and technical support in relation to payment processing, refunds, Wallet entries and Settlement through the Platform.", "k": "body" }, { "t": "7.32.2 Such support may include providing payment status information, assisting with payment-related queries, reviewing relevant Platform Records, communicating with payment service providers where appropriate, and facilitating resolution of payment-related issues.", "k": "body" }, { "t": "7.32.3 The Marketplace's provision of such support shall not make it responsible for the underlying payment, credit, Product, delivery or other commercial obligations of the Buyer or Seller.", "k": "body" }, { "t": "7.32.4 Participants shall provide timely and accurate information and reasonably cooperate with the Marketplace in resolving payment-related issues.", "k": "body" }, { "t": "7.32.5 The Marketplace may determine the appropriate administrative action in relation to a payment or Settlement issue based on the available Platform Records, payment information, Transaction terms, evidence provided by the Participants and applicable Policies.", "k": "body" }, { "t": "7.32.6 Any administrative action taken by the Marketplace shall be without prejudice to the rights and remedies of the Buyer or Seller against each other under the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "7.34 Suspension Does Not Affect Accrued Payment Obligations", "k": "h2" }, { "t": "7.34.1 Suspension, restriction or delay of any payment processing, Wallet operation or Settlement shall not relieve a Participant from any payment, refund, compensation, Fee, commission, tax, indemnity or other obligation that has already accrued under this Agreement or the applicable Transaction.", "k": "body" }, { "t": "7.34.2 Where a payment or Settlement is suspended due to an issue attributable to a Participant, that Participant shall continue to remain responsible for resolving the relevant issue and for any resulting amounts payable.", "k": "body" }, { "t": "7.34.3 Where a Transaction is cancelled or terminated while an amount remains held by the Marketplace, the Marketplace may process such amount by way of refund, Settlement, deduction, adjustment or other appropriate treatment in accordance with this Agreement, the applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.34.4 Suspension or restriction of a Participant's payment or Settlement facilities shall not prevent the Marketplace from recovering any amount due from that Participant under this Agreement.", "k": "body" }, { "t": "7.34.5 Any rights of the Marketplace to deduct, set off, adjust, recover or restrict amounts under this Agreement shall continue notwithstanding suspension, cancellation, termination or closure of the Participant's Account, subject to Applicable Law.", "k": "body" }, { "t": "7.34.6 Nothing in this Clause shall require the Marketplace to continue processing payments or Settlements where doing so would reasonably create a legal, regulatory, security or material financial risk.", "k": "body" }, { "t": "7.35 Closure of Payment and Settlement", "k": "h2" }, { "t": "7.35.1 A payment and Settlement shall be treated as completed when the applicable amount has been released to the Seller, refunded to the Buyer, adjusted against amounts due, or otherwise accounted for in accordance with the applicable Transaction terms and this Agreement.", "k": "body" }, { "t": "7.35.2 Upon completion of Settlement, the Marketplace may mark the corresponding payment and Settlement process as closed in its Platform Records.", "k": "body" }, { "t": "7.35.3 Closure of a payment or Settlement shall not prevent the Marketplace from making any subsequent adjustment, deduction, recovery or correction arising from a refund, return, chargeback, payment reversal, fraud, dispute, accounting error, statutory requirement, penalty or other valid basis under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.35.4 Where an amount becomes payable by a Participant after Settlement has been completed, the Participant shall remain liable for such amount and the Marketplace may recover it in accordance with this Agreement.", "k": "body" }, { "t": "7.35.5 Completion of Settlement shall not constitute confirmation or warranty by the Marketplace regarding the quality, quantity, authenticity, legality, condition or performance of the Products, or full discharge of the Buyer or Seller from their respective obligations under the Transaction.", "k": "body" }, { "t": "7.35.6 The Marketplace may retain relevant payment, Transaction, Wallet and Settlement records after closure for the period and purposes permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.35 Closure of Payment and Settlement", "k": "h2" }, { "t": "7.35.1 A payment and Settlement shall be treated as completed when the applicable amount has been released to the Seller, refunded to the Buyer, adjusted against amounts due, or otherwise accounted for in accordance with the applicable Transaction terms and this Agreement.", "k": "body" }, { "t": "7.35.2 Upon completion of Settlement, the Marketplace may mark the corresponding payment and Settlement process as closed in its Platform Records.", "k": "body" }, { "t": "7.35.3 Closure of a payment or Settlement shall not prevent the Marketplace from making any subsequent adjustment, deduction, recovery or correction arising from a refund, return, chargeback, payment reversal, fraud, dispute, accounting error, statutory requirement, penalty or other valid basis under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.35.4 Where an amount becomes payable by a Participant after Settlement has been completed, the Participant shall remain liable for such amount and the Marketplace may recover it in accordance with this Agreement.", "k": "body" }, { "t": "7.35.5 Completion of Settlement shall not constitute confirmation or warranty by the Marketplace regarding the quality, quantity, authenticity, legality, condition or performance of the Products, or full discharge of the Buyer or Seller from their respective obligations under the Transaction.", "k": "body" }, { "t": "7.35.6 The Marketplace may retain relevant payment, Transaction, Wallet and Settlement records after closure for the period and purposes permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.37 Payment and Settlement Upon Transaction Cancellation", "k": "h2" }, { "t": "7.37.1 Where an advance-paid Transaction is cancelled before Settlement, the Marketplace may determine whether the advance amount is to be refunded to the Buyer, adjusted against any amount properly payable, or otherwise dealt with in accordance with the applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.37.2 Where cancellation occurs due to the Seller's failure to fulfil the confirmed Transaction, including failure to dispatch or deliver within the applicable original or approved extended timeline, the Marketplace may refund the applicable advance amount to the Buyer and recover or adjust any amount payable by the Seller in accordance with this Agreement.", "k": "body" }, { "t": "7.37.3 Where cancellation occurs at the Buyer's request or due to circumstances attributable to the Buyer, any applicable cancellation charges, costs, deductions or other amounts may be adjusted from the advance payment in accordance with the applicable Transaction terms and Policies.", "k": "body" }, { "t": "7.37.4 Where the Buyer and Seller mutually agree to cancel a Transaction, the Marketplace may process the resulting refund, adjustment or Settlement in accordance with their agreed terms, this Agreement and Applicable Law.", "k": "body" }, { "t": "7.37.5 If the amount otherwise available for refund is insufficient to satisfy an amount recoverable from the Seller, the outstanding amount may be recorded as payable by the Seller and recovered through the Seller's Wallet, future Settlement amounts or other lawful recovery mechanisms.", "k": "body" }, { "t": "7.37.6 Cancellation of an advance-paid Transaction shall not affect any accrued rights, Fees, commissions, penalties, claims, indemnities, payment obligations or other liabilities arising before cancellation.", "k": "body" }, { "t": "7.37.7 The Marketplace may retain or adjust amounts reasonably required to resolve any pending dispute, refund, chargeback, reversal, claim or other payment-related matter arising from the cancelled Transaction.", "k": "body" }, { "t": "7.38 Payment and Settlement Upon Returns or Replacements", "k": "h2" }, { "t": "7.38.1 Where a Product is returned, replaced or otherwise rejected after an advance-paid Transaction, the Marketplace may hold, refund, adjust or otherwise process the corresponding amount in accordance with the applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.38.2 Where the return, replacement or rejection is attributable to the Seller, including defective, damaged, incorrect, counterfeit, short or non-conforming Products, the Marketplace may adjust the corresponding refund, compensation or other amount against the Seller's Settlement or Wallet.", "k": "body" }, { "t": "7.38.3 Where the Seller has already received Settlement and an amount subsequently becomes payable to the Buyer, the Marketplace may recover such amount from the Seller's future Settlement, Wallet balance or otherwise require payment from the Seller.", "k": "body" }, { "t": "7.38.4 Where a replacement is agreed instead of a refund, the Marketplace may continue to hold or adjust the relevant amount until the replacement is completed or the applicable Transaction terms otherwise provide.", "k": "body" }, { "t": "7.38.5 The Marketplace may request evidence relating to the return, replacement, rejection, Product condition, delivery or other relevant circumstances before processing a refund or adjustment.", "k": "body" }, { "t": "7.38.6 The Marketplace's processing of a return, replacement, refund or adjustment shall not constitute an admission that the Seller was at fault or that the Product was defective, except to the extent expressly determined by the Marketplace under its administrative dispute process or required by Applicable Law.", "k": "body" }, { "t": "7.38.7 The rights under this Clause are without prejudice to any independent rights or remedies of the Buyer or Seller under the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "7.39 Payment and Settlement Upon Disputes", "k": "h2" }, { "t": "7.39.1 Where a Buyer raises a dispute within the applicable period in relation to an advance-paid Transaction, the Marketplace may place the relevant amount on hold until the dispute is reviewed and resolved in accordance with this Agreement, the applicable Transaction terms and Policies.", "k": "body" }, { "t": "7.39.2 The Marketplace may review relevant Platform Records and information, including the Order, Quotation, PO, SO, delivery status, Seller's delivery confirmation, communications, payment records and evidence submitted by the Buyer or Seller.", "k": "body" }, { "t": "7.39.3 The Marketplace may request additional information, documents, photographs, delivery records, invoices or other evidence from the Buyer or Seller reasonably required for determining the appropriate Settlement or refund.", "k": "body" }, { "t": "7.39.4 Following its administrative review, the Marketplace may determine, to the extent permitted under this Agreement and Applicable Law, whether the relevant amount should be released to the Seller, refunded or compensated to the Buyer, adjusted between the Parties, or otherwise dealt with.", "k": "body" }, { "t": "7.39.5 Where the Marketplace determines that an amount is refundable or payable to the Buyer due to circumstances attributable to the Seller, the Marketplace may deduct such amount from the Seller's Settlement or Wallet in accordance with this Agreement.", "k": "body" }, { "t": "7.39.6 If the amount available from the Seller's Settlement or Wallet is insufficient, the remaining amount shall constitute an amount recoverable from the Seller and may be recovered in accordance with Clause 7.13.", "k": "body" }, { "t": "7.39.7 The Marketplace shall endeavour to complete its administrative review and implement the resulting payment or Settlement action at the earliest practicable time.", "k": "body" }, { "t": "7.39.8 Any administrative determination by the Marketplace under this Clause shall relate only to the administration of the Platform payment and Settlement and shall not make the Marketplace a party to the underlying sale or purchase contract between the Buyer and Seller.", "k": "body" }, { "t": "7.39.9 Nothing in this Clause prevents the Buyer or Seller from pursuing any independent right or remedy available against the other under the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "7.40 Payment and Settlement Upon Fraud or Unauthorised Activity", "k": "h2" }, { "t": "7.40.1 If the Marketplace has reasonable grounds to suspect fraud, unauthorised payment activity, misuse of an Account, manipulation of Transaction records or other unlawful activity affecting a payment or Settlement, it may temporarily hold, restrict, suspend or cancel the affected payment, Transaction or Settlement.", "k": "body" }, { "t": "7.40.2 The Marketplace may investigate the suspected activity using Platform Records, payment records, communications, information provided by Participants, payment service providers, banks or other relevant sources.", "k": "body" }, { "t": "7.40.3 The Marketplace may request information, documents, confirmations or other cooperation from the relevant Participant for the purpose of verifying the activity.", "k": "body" }, { "t": "7.40.4 Where the Marketplace determines that a payment or Settlement resulted from fraud, unauthorised activity, manipulation, misrepresentation or other unlawful conduct attributable to a Participant, it may reverse, cancel, refund, withhold or adjust the affected amount to the extent permitted by this Agreement and Applicable Law.", "k": "body" }, { "t": "7.40.5 Any amount recoverable from a Participant as a result of such activity may be deducted from its Wallet, Settlement or other amounts payable to it, or otherwise recovered in accordance with Clause 7.13.", "k": "body" }, { "t": "7.40.6 The Marketplace may also restrict or suspend the relevant Participant's Account, buying or selling privileges, Wallet or other Platform functionality where reasonably necessary to prevent further loss, misuse or risk.", "k": "body" }, { "t": "7.40.7 The Marketplace may disclose information concerning suspected or confirmed fraudulent or unauthorised activity to banks, payment service providers, law-enforcement authorities, regulators or other relevant persons where reasonably necessary or required by Applicable Law.", "k": "body" }, { "t": "7.40.8 Action taken under this Clause shall be without prejudice to any other rights or remedies available to the Marketplace under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.41 Payment Processing and Regulatory Cooperation", "k": "h2" }, { "t": "7.41.1 Each Participant shall reasonably cooperate with the Marketplace in relation to payment processing, Settlement, refunds, payment verification, fraud prevention, tax compliance and other payment-related requirements applicable to the Platform.", "k": "body" }, { "t": "7.41.2 The Marketplace may request information, confirmations, records or documents from a Participant where reasonably necessary to comply with Applicable Law, respond to a lawful request from a governmental, regulatory, judicial or statutory authority, or address a payment, fraud, security or compliance concern.", "k": "body" }, { "t": "7.41.3 A Participant shall provide the requested information or cooperation within the period reasonably specified by the Marketplace, subject to the Participant's rights under Applicable Law.", "k": "body" }, { "t": "7.41.4 Where a Participant fails to provide information or cooperation reasonably required for payment processing, refund or Settlement, the Marketplace may temporarily delay, restrict or suspend the relevant payment, Transaction or Settlement to the extent reasonably necessary.", "k": "body" }, { "t": "7.41.5 The Marketplace may take such actions as are reasonably necessary to comply with Applicable Law or a binding direction, order or requirement of a competent governmental, regulatory, judicial or statutory authority, including withholding, restricting, refunding, reversing or otherwise dealing with amounts connected with a Transaction.", "k": "body" }, { "t": "7.41.6 Where legally permitted and reasonably practicable, the Marketplace may inform the affected Participant of material payment-related action taken under this Clause.", "k": "body" }, { "t": "7.41.7 Compliance with this Clause shall not require the Marketplace or any Participant to disclose information beyond what is reasonably necessary or legally required.", "k": "body" }, { "t": "7.42 Payment Processing and Service Continuity", "k": "h2" }, { "t": "7.42.1 The Marketplace may temporarily suspend or restrict payment processing, refund, Wallet or Settlement functionality where reasonably necessary for maintenance, upgrades, security measures, system changes, technical issues or other operational requirements.", "k": "body" }, { "t": "7.42.2 The Marketplace shall endeavour to restore affected payment or Settlement functionality at the earliest practicable time, having regard to the nature and cause of the interruption.", "k": "body" }, { "t": "7.42.3 Temporary unavailability, interruption, delay or restriction of payment functionality shall not by itself constitute a waiver of any payment, refund, Settlement or other obligation of a Participant.", "k": "body" }, { "t": "7.42.4 Where payment functionality is temporarily unavailable, the Marketplace may provide alternative payment or processing instructions or procedures where reasonably practicable.", "k": "body" }, { "t": "7.42.5 The Marketplace shall not be responsible for delays or failures resulting from internet or telecommunications failures, banking systems, payment networks, payment processors, third-party technology providers, governmental actions, Force Majeure events or other circumstances beyond its reasonable control.", "k": "body" }, { "t": "7.42.6 Nothing in this Clause shall require the Marketplace to continue or restore a particular payment mechanism where doing so would reasonably conflict with Applicable Law, security requirements or legitimate operational requirements.", "k": "body" }, { "t": "7.43 Payment Processing Errors, Delays and Third-Party Failures", "k": "h2" }, { "t": "7.43.1 The Marketplace shall not be responsible for any delay, failure, interruption, rejection, reversal or error in payment processing, refund or Settlement arising from circumstances beyond its reasonable control, including failures or delays of banks, payment gateways, payment processors, payment networks, telecommunications networks or other third-party service providers.", "k": "body" }, { "t": "7.43.2 Where a payment, refund or Settlement is affected by such circumstances, the Marketplace may wait for confirmation, correction or resolution from the relevant bank, payment provider or other service provider before taking further action.", "k": "body" }, { "t": "7.43.3 The Marketplace may update, correct or adjust the relevant Platform, Transaction, Wallet or Settlement records once the actual payment status or amount has been verified.", "k": "body" }, { "t": "7.43.4 A Participant shall remain responsible for its underlying payment obligation notwithstanding any delay or failure in a third-party payment system, except to the extent such obligation has been legally discharged.", "k": "body" }, { "t": "7.43.5 Where a payment is successfully received by the Marketplace but the corresponding confirmation is delayed due to a third-party system, the Marketplace may defer recognition or processing of the payment until sufficient confirmation is available.", "k": "body" }, { "t": "7.43.6 Where a payment is incorrectly credited, duplicated, reversed or otherwise incorrectly processed due to a technical or third-party error, the Marketplace may correct the relevant records and recover or adjust any resulting excess amount in accordance with this Agreement.", "k": "body" }, { "t": "7.43.7 The Marketplace shall endeavour to address payment-processing errors or delays at the earliest practicable time after becoming aware of them, but shall not be liable for consequences arising solely from circumstances beyond its reasonable control.", "k": "body" }, { "t": "7.44 Payment Processing Responsibility of the Marketplace", "k": "h2" }, { "t": "7.44.1 The Marketplace's role in relation to advance payments is limited to receiving, holding, administering, releasing, refunding and adjusting funds in connection with the applicable Platform Transaction, in accordance with this Agreement, the applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.44.2 The Marketplace shall not be responsible for ensuring that a Buyer has sufficient funds, that a Seller has sufficient financial capacity to fulfil a Transaction, or that either Party performs its underlying commercial obligations.", "k": "body" }, { "t": "7.44.3 The Marketplace does not assume any obligation to fund, finance, advance, guarantee or otherwise make payment on behalf of a Buyer or Seller, except for amounts actually received and held by the Marketplace in connection with an advance-paid Transaction.", "k": "body" }, { "t": "7.44.4 The Marketplace's processing, holding or release of advance payment shall not constitute confirmation that the Seller has fulfilled all Product, delivery, warranty or other obligations, except to the extent expressly determined through the applicable Platform process.", "k": "body" }, { "t": "7.44.5 The Marketplace may rely on Platform Records and information reasonably available to it when administering payment and Settlement and may take administrative action in accordance with this Agreement where a payment or Transaction issue arises.", "k": "body" }, { "t": "7.44.6 Nothing in this Clause shall limit any liability or obligation of the Marketplace that cannot lawfully be excluded under Applicable Law.", "k": "body" }, { "t": "7.45 Payment Processing Discretion and Administrative Authority", "k": "h2" }, { "t": "7.45.1 The Marketplace may take such administrative actions in relation to payment processing, refunds, Wallet entries and Settlement as it reasonably considers necessary to administer the Platform and the relevant Transaction, subject to this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "7.45.2 Such actions may include confirming or declining payment status, placing or releasing a hold, processing a refund, making an adjustment, applying a deduction, correcting an accounting entry, recovering an amount due or restricting further payment-related activity.", "k": "body" }, { "t": "7.45.3 In exercising such administrative authority, the Marketplace may consider the applicable Transaction terms, Platform Records, payment records, delivery status, dispute information, evidence submitted by the Parties, applicable Policies and other information reasonably available to it.", "k": "body" }, { "t": "7.45.4 The Marketplace may take interim action where immediate action is reasonably necessary to protect funds, prevent fraud or unauthorised activity, comply with Applicable Law, or prevent material loss or risk.", "k": "body" }, { "t": "7.45.5 The Marketplace shall endeavour to act reasonably and consistently with the applicable Transaction terms and this Agreement when making administrative payment or Settlement decisions.", "k": "body" }, { "t": "7.45.6 An administrative decision concerning payment or Settlement shall not, unless expressly stated otherwise, constitute a determination of ownership, title, Product quality, contractual liability or any other substantive legal right between the Buyer and Seller.", "k": "body" }, { "t": "7.45.7 The Marketplace may revise or correct an administrative payment or Settlement decision where new information, evidence, an error, payment reversal, fraud, regulatory requirement or other material circumstance reasonably requires such revision, subject to Applicable Law.", "k": "body" }, { "t": "7.45.8 Nothing in this Clause limits the rights of a Buyer or Seller to pursue remedies available against the other under the applicable Transaction terms or Applicable Law.", "k": "body" }, { "t": "7.46 Finality and Correction of Payment Decisions", "k": "h2" }, { "t": "7.46.1 Subject to this Agreement and Applicable Law, the payment, refund, adjustment and Settlement actions recorded by the Marketplace shall be treated as the applicable administrative treatment of the relevant payment or Transaction.", "k": "body" }, { "t": "7.46.2 A Participant may raise a genuine objection to any payment, refund, deduction, adjustment or Settlement action through the applicable Platform mechanism or communication channel within a reasonable period after becoming aware of the relevant action.", "k": "body" }, { "t": "7.46.3 The Participant raising an objection shall provide sufficient details and supporting information reasonably required by the Marketplace to review the matter.", "k": "body" }, { "t": "7.46.4 The Marketplace may review the objection against the relevant Platform Records, payment records, Transaction terms, communications and other available evidence and may confirm, modify or correct the applicable payment or Settlement treatment.", "k": "body" }, { "t": "7.46.5 The Marketplace may correct a payment or Settlement action where it identifies an administrative, technical, accounting or other error, or where a subsequent refund, reversal, chargeback, fraud finding, dispute outcome or statutory requirement requires correction.", "k": "body" }, { "t": "7.46.6 A correction may be implemented through a refund, deduction, adjustment, Wallet entry, future Settlement adjustment or other appropriate mechanism permitted under this Agreement.", "k": "body" }, { "t": "7.46.7 The Marketplace shall endeavour to communicate material corrections or changes to the affected Participant where reasonably practicable.", "k": "body" }, { "t": "7.46.8 No payment or Settlement action shall prevent a Participant from exercising any right or remedy that cannot lawfully be excluded under Applicable Law.", "k": "body" }, { "t": "7.47 Participant's Duty to Review Payment and Settlement Records", "k": "h2" }, { "t": "7.47.1 Each Participant shall regularly review its payment, Transaction, Wallet, refund and Settlement records available through the Platform.", "k": "body" }, { "t": "7.47.2 A Participant shall promptly notify the Marketplace of any material discrepancy, unauthorised payment, incorrect deduction, unexpected refund, incorrect Settlement, duplicate entry or other payment-related error identified in its records.", "k": "body" }, { "t": "7.47.3 The Participant shall provide reasonable details and supporting information required by the Marketplace to investigate the reported discrepancy or error.", "k": "body" }, { "t": "7.47.4 Failure by a Participant to promptly report a material discrepancy shall not, by itself, prevent the Marketplace from correcting the relevant records or recovering an amount that was incorrectly credited, released or adjusted.", "k": "body" }, { "t": "7.47.5 The Marketplace may investigate reported discrepancies and, where appropriate, correct the relevant Transaction, Wallet or Settlement records in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.47.6 Each Participant remains responsible for maintaining its own accounting, tax and financial records relating to its Transactions and shall not rely solely on Platform Records for its statutory or accounting obligations.", "k": "body" }, { "t": "7.47.7 Platform payment and Settlement records may be made available to the relevant Participant through the Platform or other communication channel determined by the Marketplace.", "k": "body" }, { "t": "7.48 Payment and Settlement Information Sharing", "k": "h2" }, { "t": "7.48.1 The Marketplace may share payment, Transaction, refund, Wallet and Settlement information with the Buyer or Seller to the extent reasonably necessary for administering the relevant Transaction, resolving a dispute, processing a refund or Settlement, or communicating the status of amounts payable or receivable.", "k": "body" }, { "t": "7.48.2 The Marketplace may share relevant payment information with banks, payment gateways, payment processors, technology providers, auditors, professional advisers and other service providers engaged by the Marketplace where reasonably necessary for providing Platform Services, payment processing, accounting, fraud prevention, security or compliance.", "k": "body" }, { "t": "7.48.3 The Marketplace may disclose payment or Settlement information to governmental, regulatory, judicial or statutory authorities where required or permitted under Applicable Law.", "k": "body" }, { "t": "7.48.4 The Marketplace shall use reasonable measures to restrict disclosure of payment and financial information to information relevant to the applicable purpose and shall handle such information in accordance with its applicable privacy and data protection obligations.", "k": "body" }, { "t": "7.48.5 Nothing in this Clause shall require the Marketplace to disclose confidential banking, payment or financial information of a Participant where such disclosure is not reasonably necessary, authorised or required under Applicable Law.", "k": "body" }, { "t": "7.48.6 A Participant shall not misuse, disclose or use payment or Settlement information received through the Platform for any unlawful, fraudulent or unauthorised purpose.", "k": "body" }, { "t": "7.49 No Interest on Advance Payments", "k": "h2" }, { "t": "7.49.1 No interest, return, yield, profit or other financial benefit shall accrue or be payable to the Buyer or Seller in respect of any advance payment received and held by the Marketplace pending completion of the applicable Transaction or Settlement.", "k": "body" }, { "t": "7.49.2 The Marketplace shall not be required to separately account to the Buyer or Seller for any interest, income or other benefit that may arise from the temporary holding of advance payment, except to the extent otherwise required by Applicable Law.", "k": "body" }, { "t": "7.49.3 The amount eligible for release or refund shall be determined based on the applicable Transaction Value and the adjustments, deductions, refunds, commissions, Fees and other amounts applicable under this Agreement and the relevant Transaction terms.", "k": "body" }, { "t": "7.49.4 The holding of an advance payment by the Marketplace is solely for administering the applicable Platform Transaction and shall not be construed as an investment, deposit-taking, financing or other financial arrangement for the benefit of the Buyer or Seller.", "k": "body" }, { "t": "7.50 Payment and Settlement Survival", "k": "h2" }, { "t": "7.50.1 The rights and obligations relating to payment, refunds, adjustments, Settlement, Wallet balances, commissions, Fees, chargebacks, reversals, deductions and recovery of amounts due shall survive completion, cancellation, suspension, termination or closure of the relevant Transaction or Participant Account to the extent necessary to give effect to such rights and obligations.", "k": "body" }, { "t": "7.50.2 The Marketplace may continue to process, adjust, recover or otherwise administer any amount arising from a Transaction after its completion or closure where such action is permitted under this Agreement, the applicable Transaction terms, Policies or Applicable Law.", "k": "body" }, { "t": "7.50.3 A Participant shall remain liable for any amount that became payable before or as a result of completion, cancellation, suspension, termination or closure of a Transaction or Account.", "k": "body" }, { "t": "7.50.4 The expiration or termination of this Agreement shall not affect any payment or Settlement right or obligation that accrued before such expiration or termination.", "k": "body" }, { "t": "7.50.5 The provisions of this Section 7 relating to payment, fund holding, refunds, adjustments, recovery, records and Settlement shall continue to apply to the extent necessary to complete or resolve any outstanding payment or financial matter arising from Transactions undertaken before termination.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.51 No Liability for Participant's Banking Arrangements", "k": "h2" }, { "t": "7.51.1 Each Participant shall be solely responsible for maintaining its own bank accounts, payment instruments, banking relationships and financial arrangements necessary to fulfil its obligations under this Agreement and applicable Transactions.", "k": "body" }, { "t": "7.51.2 The Marketplace shall not be responsible for any action, omission, restriction, freeze, closure, delay, rejection or other issue affecting a Participant's bank account or payment instrument where such matter is attributable to the Participant, its bank, financial institution or other third party.", "k": "body" }, { "t": "7.51.3 A Participant shall be responsible for ensuring that its bank account and payment arrangements comply with Applicable Law and are capable of receiving or making payments required under applicable Transactions.", "k": "body" }, { "t": "7.51.4 The Marketplace may rely on banking and payment information provided or verified by the Participant and shall not be required to independently verify the Participant's ownership, authority or arrangements with its bank except where reasonably required for security, fraud prevention or compliance purposes.", "k": "body" }, { "t": "7.51.5 Any dispute between a Participant and its bank, financial institution or payment service provider shall be resolved by the Participant directly with the relevant institution and shall not relieve the Participant of its obligations under this Agreement or an applicable Transaction, except to the extent otherwise required by Applicable Law.", "k": "body" }, { "t": "7.52 Payment Processing Authority and Participant Instructions", "k": "h2" }, { "t": "7.52.1 The Marketplace is authorised to process, hold, release, refund, deduct, adjust and otherwise administer advance payments in accordance with this Agreement, the applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.52.2 The Marketplace may act upon payment, refund, Settlement and adjustment instructions generated through the Platform or otherwise authorised in accordance with the applicable Platform procedures.", "k": "body" }, { "t": "7.52.3 A Participant shall ensure that all payment-related instructions submitted through its Account are accurate, complete and duly authorised.", "k": "body" }, { "t": "7.52.4 Where an instruction appears incomplete, inconsistent, suspicious or unauthorised, the Marketplace may seek confirmation or additional information before acting upon it.", "k": "body" }, { "t": "7.52.5 The Marketplace may decline, delay or suspend implementation of a payment-related instruction where reasonably necessary to prevent fraud, protect funds, resolve a dispute, comply with Applicable Law or address a technical or operational issue.", "k": "body" }, { "t": "7.52.6 The Marketplace shall not be responsible for consequences arising from an instruction that was accurately processed in accordance with the information submitted or authorised by the Participant, except to the extent caused by the Marketplace's own breach, fraud, wilful misconduct or liability that cannot lawfully be excluded.", "k": "body" }, { "t": "7.52.7 The authority granted under this Clause is limited to administering payments and Settlement connected with the Platform and shall not be construed as authority to alter the underlying commercial terms between Buyer and Seller without the applicable consent or other authority provided under this Agreement.", "k": "body" }, { "t": "7.53 Payment Method and Processing Requirements", "k": "h2" }, { "t": "7.53.1 The Marketplace may determine and make available the payment methods through which advance payments may be made for Transactions on the Platform.", "k": "body" }, { "t": "7.53.2 A Buyer shall use an available and authorised payment method and shall comply with the applicable payment instructions, limits and procedures communicated through the Platform.", "k": "body" }, { "t": "7.53.3 The Marketplace may add, remove, restrict or modify available payment methods or processing procedures from time to time for operational, technical, security, commercial, regulatory or other legitimate reasons.", "k": "body" }, { "t": "7.53.4 The Marketplace may impose reasonable transaction limits, payment limits or other controls on a payment method or Transaction where necessary for security, fraud prevention, risk management, operational or compliance purposes.", "k": "body" }, { "t": "7.53.5 Where a particular payment method is unavailable, restricted or unsuccessful, the Marketplace may require the Buyer to use another payment method made available through the Platform.", "k": "body" }, { "t": "7.53.6 The availability of a payment method through the Platform does not constitute a representation or warranty by the Marketplace regarding the Buyer's eligibility, creditworthiness, financial capacity or ability to complete the relevant Transaction.", "k": "body" }, { "t": "7.53.7 The Marketplace shall not be responsible for any additional charges, restrictions, limits or requirements imposed directly by a Participant's bank, payment instrument provider or other third-party payment service provider, except to the extent required by Applicable Law.", "k": "body" }, { "t": "7.54 Payment-Related Complaints and Support", "k": "h2" }, { "t": "7.54.1 A Participant may raise a payment-related complaint or request for assistance through the support mechanism or communication channel made available by the Marketplace.", "k": "body" }, { "t": "7.54.2 Payment-related complaints may include issues concerning payment confirmation, payment status, refunds, deductions, Wallet entries, Settlement, payment reversals, chargebacks or other payment-related matters connected with the Platform.", "k": "body" }, { "t": "7.54.3 The Participant shall provide reasonable details and supporting information necessary for the Marketplace to identify and review the relevant Transaction or payment.", "k": "body" }, { "t": "7.54.4 The Marketplace may review relevant Platform Records, payment records, Transaction details, communications and information received from applicable banks, payment processors or other service providers while addressing the complaint.", "k": "body" }, { "t": "7.54.5 Where a complaint concerns an underlying commercial dispute between Buyer and Seller, the Marketplace may address the payment or Settlement consequences in accordance with this Agreement without assuming responsibility for resolving the underlying commercial relationship.", "k": "body" }, { "t": "7.54.6 The Marketplace shall endeavour to respond to and process genuine payment-related complaints at the earliest practicable time, having regard to the nature of the issue and information reasonably available.", "k": "body" }, { "t": "7.54.7 Raising a complaint shall not, by itself, suspend any payment, delivery, refund or other obligation of a Participant unless the Marketplace or the applicable Transaction terms provide otherwise.", "k": "body" }, { "t": "7.54.8 The Marketplace may communicate the outcome of its review and, where appropriate, implement a refund, deduction, adjustment, Settlement or other administrative action in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.55 Payment Processing and Settlement Records", "k": "h2" }, { "t": "7.55.1 The Marketplace may maintain records of all advance payments, payment confirmations, refunds, reversals, deductions, adjustments, Wallet entries and Settlements processed through or in connection with the Platform.", "k": "body" }, { "t": "7.55.2 Such records may be maintained electronically and may include Transaction references, payment references, dates, amounts, payment status, Settlement status and other information reasonably required for administration of the Platform.", "k": "body" }, { "t": "7.55.3 The Marketplace may use such records for accounting, reconciliation, Settlement, refunds, dispute resolution, fraud prevention, audit, tax, regulatory compliance and other legitimate purposes connected with the Platform.", "k": "body" }, { "t": "7.55.4 Subject to Applicable Law, the Marketplace may rely on its Platform Records and records received from banks, payment processors and other authorised service providers when determining the status and accounting of a payment or Settlement.", "k": "body" }, { "t": "7.55.5 Where records from different sources conflict, the Marketplace may investigate the discrepancy and determine the appropriate administrative treatment based on the information reasonably available to it.", "k": "body" }, { "t": "7.55.6 A Participant shall reasonably cooperate with any investigation of a material payment or Settlement discrepancy and provide information or evidence reasonably requested by the Marketplace.", "k": "body" }, { "t": "7.55.7 The Marketplace may correct any record where an error, duplication, omission, reversal or other discrepancy is identified, and may make corresponding adjustments to the relevant Transaction, Wallet or Settlement.", "k": "body" }, { "t": "7.55.8 Maintenance or correction of payment records shall not, by itself, modify the underlying commercial rights or obligations of the Buyer or Seller under the applicable Transaction.", "k": "body" }, { "t": ".56 Payment Processing — Limitation of Marketplace Responsibility", "k": "body" }, { "t": "7.56.1 The Marketplace shall use reasonable care in administering advance payments, refunds, adjustments and Settlement through the Platform in accordance with this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "7.56.2 Except to the extent expressly undertaken by the Marketplace under this Agreement or required under Applicable Law, the Marketplace shall not be responsible for:", "k": "body" }, { "t": "(a) the Buyer's or Seller's financial capacity, solvency or ability to fulfil its payment obligations;", "k": "body" }, { "t": "(b) payment obligations arising directly between Buyer and Seller under credit or deferred-payment Transactions;", "k": "body" }, { "t": "(c) Product quality, quantity, authenticity, conformity or delivery;", "k": "body" }, { "t": "(d) failures or delays attributable to banks, payment processors, payment gateways, payment networks or other third parties;", "k": "body" }, { "t": "(e) incorrect or unauthorised payment or banking information provided by a Participant; or", "k": "body" }, { "t": "(f) disputes arising from the underlying commercial relationship between Buyer and Seller.", "k": "body" }, { "t": "7.56.3 The Marketplace's receipt, holding, processing, refund or Settlement of an advance payment shall not constitute a guarantee of performance by either Buyer or Seller.", "k": "body" }, { "t": "7.56.4 Nothing in this Clause shall exclude or limit any liability of the Marketplace that cannot lawfully be excluded or limited under Applicable Law.", "k": "body" }, { "t": "7.57 Payment and Settlement — Participant Acknowledgement", "k": "h2" }, { "t": "7.57.1 By using the Platform and participating in a Transaction, each Participant acknowledges and agrees that the payment, fund-holding, refund and Settlement mechanisms applicable to the Transaction shall be governed by this Agreement, the applicable Transaction terms and Policies.", "k": "body" }, { "t": "7.57.2 The Buyer acknowledges that, in an advance-paid Transaction, the Marketplace may receive and hold the advance payment until the conditions for release, refund or other applicable treatment are satisfied.", "k": "body" }, { "t": "7.57.3 The Seller acknowledges that, in an advance-paid Transaction, the amount payable to it may remain subject to the applicable delivery, dispute, refund, adjustment and Settlement provisions before release.", "k": "body" }, { "t": "7.57.4 The Buyer and Seller acknowledge that, in a credit Transaction, payment is made directly between them and the Marketplace does not receive, hold or settle such credit payment.", "k": "body" }, { "t": "7.57.5 Each Participant acknowledges that the Marketplace may make administrative decisions relating to payment, refund, adjustment and Settlement in accordance with this Agreement and may rely on relevant Platform Records and available evidence.", "k": "body" }, { "t": "7.57.6 Each Participant further acknowledges that the Marketplace's payment and Settlement functions are provided to facilitate administration of Platform Transactions and do not transfer the underlying commercial obligations between Buyer and Seller to the Marketplace.", "k": "body" }, { "t": "7.57.7 The provisions of this Section 7 shall be read together with the other provisions of this Agreement, including provisions relating to Transactions, Product obligations, disputes, suspension, termination, indemnification and Applicable Law.", "k": "body" }, { "t": "7.58 Payment and Settlement — Order of Precedence", "k": "h2" }, { "t": "7.58.1 In the event of any inconsistency concerning payment, refund, Wallet, deduction or Settlement between the provisions of this Section 7 and the applicable Transaction records, the following order shall apply, unless otherwise expressly provided in this Agreement:", "k": "body" }, { "t": "(a) mandatory requirements of Applicable Law;", "k": "body" }, { "t": "(b) the express terms of this Agreement;", "k": "body" }, { "t": "(c) the applicable confirmed Order, PO, SO or other confirmed Transaction terms;", "k": "body" }, { "t": "(d) applicable Commercial Terms; and", "k": "body" }, { "t": "(e) applicable Policies and Platform procedures.", "k": "body" }, { "t": "7.58.2 A Quotation, payment instruction, Platform display or other communication shall not modify the terms of a confirmed Transaction unless the modification is expressly accepted or recorded in accordance with this Agreement.", "k": "body" }, { "t": "7.58.3 Where a matter is not specifically addressed in the applicable Transaction terms, the provisions of this Agreement and applicable Policies shall apply.", "k": "body" }, { "t": "7.58.4 Nothing in this Clause shall be interpreted as permitting any Transaction term, Platform procedure or Policy to override a mandatory requirement of Applicable Law.", "k": "body" }, { "t": "7.59 Payment and Settlement — No Waiver of Rights", "k": "h2" }, { "t": "7.59.1 Any delay, omission or failure by the Marketplace to exercise any right, remedy, authority or discretion available to it in relation to payment, refund, deduction, Wallet, Settlement or any Transaction shall not constitute or be deemed to constitute a waiver of such right, remedy, authority or discretion.", "k": "body" }, { "t": "7.59.2 Any waiver by the Marketplace shall be effective only if expressly communicated or recorded in writing or electronically through the Platform and shall apply only to the specific instance for which it is given.", "k": "body" }, { "t": "7.59.3 A waiver in respect of any particular payment, deduction, Settlement, Transaction or breach shall not prevent the Marketplace from exercising the same or any other right in respect of any subsequent or other matter.", "k": "body" }, { "t": "7.59.4 Nothing in this Clause shall restrict any right or remedy available to the Marketplace or Participant under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.60 Payment and Settlement — Severability", "k": "h2" }, { "t": "7.60.1 If any provision of this Section 7 relating to payment, refund, deduction, Wallet, Settlement or any other payment-related matter is determined by a competent authority to be invalid, unlawful or unenforceable, such provision shall, to the extent permitted by Applicable Law, be modified or limited to the minimum extent necessary to make it valid and enforceable.", "k": "body" }, { "t": "7.60.2 The invalidity or unenforceability of any such provision shall not affect the validity or enforceability of the remaining provisions of this Section 7 or the Agreement.", "k": "body" }, { "t": "7.60.3 The Parties shall, where reasonably practicable, cooperate in good faith to replace any invalid or unenforceable provision with a valid and enforceable provision that most closely reflects the original commercial intent of the affected provision.", "k": "body" }, { "t": "7.61 Payment and Settlement — Continuing Effect", "k": "h2" }, { "t": "7.61.1 The rights, obligations and responsibilities of the Parties relating to any payment, refund, deduction, Wallet balance, Settlement, outstanding amount or other financial obligation arising before expiry or termination of this Agreement shall continue until such matter has been fully resolved, paid, refunded, adjusted or otherwise discharged in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.61.2 Expiry, suspension or termination of the Participant’s Account or this Agreement shall not, by itself, extinguish any payment or Settlement obligation that has accrued before such expiry, suspension or termination.", "k": "body" }, { "t": "7.61.3 The Marketplace may continue to process refunds, deductions, recoveries, adjustments and other Settlement-related actions after suspension or termination to the extent necessary to give effect to Transactions and obligations arising before such suspension or termination.", "k": "body" }, { "t": "7.62 Payment and Settlement — No Obligation to Advance Funds", "k": "h2" }, { "t": "7.62.1 The Marketplace shall not be required to advance, lend, finance or otherwise provide its own funds to satisfy any payment, refund, Settlement, compensation, deduction or other financial obligation of a Participant, Buyer or Seller, except to the extent expressly agreed by the Marketplace in writing.", "k": "body" }, { "t": "7.62.2 Where funds required for a refund, Settlement, compensation, adjustment or other payment are required to be recovered from a Participant, the Marketplace may recover such amounts from the Participant’s Wallet, future Settlement amounts or other amounts payable to that Participant, subject to this Agreement and Applicable Law.", "k": "body" }, { "t": "7.62.3 Nothing in this Clause shall create any obligation on the Marketplace to provide credit, financing, overdraft, loan, guarantee or other financial accommodation to any Participant.", "k": "body" }, { "t": "7.63 Payment and Settlement — Recovery of Amounts Due", "k": "h2" }, { "t": "7.63.1 Where any amount becomes due and payable by a Participant to the Marketplace under this Agreement, a Transaction, applicable Commercial Terms or Policies, the Marketplace may recover such amount by deduction or adjustment against any amount otherwise payable or releasable to such Participant through the Platform.", "k": "body" }, { "t": "7.63.2 If the amount available for deduction or adjustment is insufficient to satisfy the amount due, the outstanding balance shall remain payable by the Participant to the Marketplace.", "k": "body" }, { "t": "7.63.3 The Marketplace may record such outstanding amount in the Participant’s Wallet or Platform Records and may restrict or suspend further Transactions, Settlement or other Platform functionality until the outstanding amount is paid or otherwise resolved.", "k": "body" }, { "t": "7.63.4 Recovery under this Clause shall be without prejudice to any other rights or remedies available to the Marketplace under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.64 Payment and Settlement — Participant’s Cooperation", "k": "h2" }, { "t": "7.64.1 The Participant shall reasonably cooperate with the Marketplace in connection with any payment, refund, Settlement, deduction, adjustment, reconciliation, dispute, chargeback, fraud investigation or other payment-related matter arising from or relating to a Transaction.", "k": "body" }, { "t": "7.64.2 The Participant shall promptly provide such information, confirmations, records, documents or clarifications as may reasonably be required by the Marketplace for processing, verifying or resolving any payment or Settlement matter.", "k": "body" }, { "t": "7.64.3 Failure by the Participant to provide required information or cooperation within a reasonable period may result in the Marketplace delaying, restricting or suspending the relevant payment, refund, Settlement or other Platform action until the matter is resolved.", "k": "body" }, { "t": "7.64.4 Nothing in this Clause shall require the Participant to provide information that it is prohibited from providing under Applicable Law.", "k": "body" }, { "t": "7.65 Payment and Settlement — Compliance with Applicable Law", "k": "h2" }, { "t": "7.65.1 All payments, refunds, deductions, adjustments, Wallet entries and Settlements under this Agreement shall be made, processed and administered in accordance with Applicable Law.", "k": "body" }, { "t": "7.65.2 The Marketplace may take such actions, impose such restrictions, delay or withhold processing, or require such information or verification as may reasonably be necessary to comply with Applicable Law, regulatory requirements, governmental directions, fraud-prevention requirements or lawful orders of a competent authority.", "k": "body" }, { "t": "7.65.3 Where any provision, payment arrangement or Settlement mechanism is required to be modified, restricted or discontinued to comply with Applicable Law, the Marketplace may implement such modification, restriction or discontinuation to the extent reasonably necessary.", "k": "body" }, { "t": "7.65.4 The Participant shall comply with all Applicable Law applicable to its own payment, tax, accounting, reporting and other statutory obligations arising from or relating to Transactions.", "k": "body" }, { "t": "7.66 Payment and Settlement — Electronic Instructions and Records", "k": "h2" }, { "t": "7.66.1 The Participant acknowledges and agrees that payment instructions, confirmations, Order records, Transaction records, Wallet entries, Settlement records and other payment-related actions or records generated, submitted, confirmed or maintained through the Platform may be maintained in electronic form.", "k": "body" }, { "t": "7.66.2 Subject to Applicable Law, the Participant agrees that electronic records maintained by the Marketplace in connection with payments and Settlements may be relied upon for administering Transactions, calculating amounts due, processing refunds and adjustments, and resolving payment-related disputes.", "k": "body" }, { "t": "7.66.3 The Participant shall promptly review payment and Settlement information made available through the Platform and notify the Marketplace of any apparent error, unauthorised transaction or discrepancy in accordance with the applicable procedures.", "k": "body" }, { "t": "7.66.4 Nothing in this Clause prevents a Party from challenging an electronic record or transaction where it has reasonable grounds to establish that the record is inaccurate, unauthorised, fraudulent or otherwise affected by an error.", "k": "body" }, { "t": "7.67 Payment and Settlement — Dispute Resolution", "k": "h2" }, { "t": "7.67.1 Any dispute, claim, discrepancy or objection relating to a payment, refund, deduction, Wallet entry or Settlement shall be addressed in accordance with the dispute resolution procedures set out in this Agreement and the applicable Policies.", "k": "body" }, { "t": "7.67.2 The Marketplace may review relevant Platform Records, Transaction details, payment records, communications, delivery records and other information available to it for the purpose of assessing and administering such payment-related dispute.", "k": "body" }, { "t": "7.67.3 Pending resolution of a payment-related dispute, the Marketplace may hold, restrict or defer the release of the disputed amount to the extent reasonably necessary to protect the interests of the Parties and administer the relevant Transaction.", "k": "body" }, { "t": "7.67.4 Any administrative decision or adjustment made by the Marketplace under this Section shall be subject to the rights and remedies of the Parties under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.68 Payment and Settlement — Effect of Transaction Completion", "k": "h2" }, { "t": "7.68.1 Completion of a Transaction shall not by itself release or extinguish any payment, refund, deduction, adjustment, recovery or other financial obligation that has accrued in connection with such Transaction.", "k": "body" }, { "t": "7.68.2 Where a Transaction has been completed and the applicable Settlement has been released, any subsequent payment-related adjustment, refund, recovery or deduction may be made where permitted under this Agreement, the applicable Policies or Applicable Law.", "k": "body" }, { "t": "7.68.3 The Marketplace may make such post-completion adjustment based on returns, disputes, fraud, payment reversals, incorrect credits or deductions, tax or statutory requirements, clerical or technical errors, or other circumstances affecting the accuracy or validity of the original Settlement.", "k": "body" }, { "t": "7.68.4 A Participant shall remain responsible for any amount properly determined to be payable by it following such post-completion adjustment.", "k": "body" }, { "t": "7.69 Payment and Settlement — Marketplace Administrative Role", "k": "h2" }, { "t": "7.69.1 The Participant acknowledges that the Marketplace may perform administrative and operational functions in relation to payments and Settlements, including recording payment status, calculating applicable Fees and adjustments, holding and releasing funds in accordance with this Agreement, processing refunds and making Settlement decisions in relation to disputed Transactions.", "k": "body" }, { "t": "7.69.2 The Marketplace's administrative role in relation to payment and Settlement shall not make the Marketplace a party to the underlying sale contract between the Buyer and Seller, except to the extent expressly provided under this Agreement.", "k": "body" }, { "t": "7.69.3 The Marketplace does not assume the payment, delivery, Product, credit, tax or other commercial obligations of a Buyer or Seller merely by facilitating, recording, holding or administering payment or Settlement.", "k": "body" }, { "t": "7.69.4 The Participant remains responsible for fulfilling all obligations arising from the relevant Transaction notwithstanding any payment or Settlement function performed by the Marketplace.", "k": "body" }, { "t": "7.70 Payment and Settlement — No Guarantee of Buyer or Seller Performance", "k": "h2" }, { "t": "7.70.1 The Marketplace's processing, holding, release or Settlement of any payment shall not constitute a representation, warranty or guarantee that the Buyer or Seller will perform its obligations under the relevant Transaction.", "k": "body" }, { "t": "7.70.2 The Marketplace does not guarantee the Buyer’s ability or willingness to make any payment due directly to a Seller under a Credit Transaction, nor does it guarantee the Seller’s ability or willingness to deliver Products or otherwise perform its obligations.", "k": "body" }, { "t": "7.70.3 The Participant acknowledges that payment processing and Settlement are administrative functions of the Marketplace and do not eliminate the commercial, contractual or legal risks associated with dealing with another Participant.", "k": "body" }, { "t": "7.70.4 Nothing in this Clause limits any right of a Participant to raise a claim or dispute in accordance with this Agreement.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.71 Payment and Settlement — Multiple Transactions", "k": "h2" }, { "t": "7.71.1 Each Transaction shall be treated separately for the purpose of determining the applicable payment terms, payment status, deductions, refunds and Settlement, unless otherwise expressly provided in the applicable Transaction terms or this Agreement.", "k": "body" }, { "t": "7.71.2 Amounts relating to one Transaction shall not be treated as relating to another Transaction merely because the same Participant acts as Buyer or Seller in both Transactions.", "k": "body" }, { "t": "7.71.3 Notwithstanding Clause 7.71.2, the Marketplace may, where permitted under this Agreement, adjust, deduct or recover amounts due from a Participant against amounts otherwise payable or releasable to that Participant in connection with other Transactions.", "k": "body" }, { "t": "7.71.4 The Marketplace may maintain separate Transaction-level records for payment and Settlement while maintaining an aggregate Wallet or account-level record of amounts payable, receivable, deducted or outstanding.", "k": "body" }, { "t": "7.72 Payment and Settlement — Transaction-Specific Terms", "k": "h2" }, { "t": "7.72.1 The payment method and Settlement mechanism applicable to a Transaction shall be determined by the payment terms displayed, recorded or otherwise confirmed through the Platform for that Transaction.", "k": "body" }, { "t": "7.72.2 Where a Transaction is designated as an advance or prepaid Transaction, the Buyer shall make payment in accordance with the applicable payment instructions, and the Marketplace shall administer the receipt, holding and release of such funds in accordance with this Agreement.", "k": "body" }, { "t": "7.72.3 Where a Transaction is designated as a Credit Transaction, payment shall be made directly by the Buyer to the Seller in accordance with the credit and payment terms agreed between them, and the Marketplace shall not be responsible for collecting or guaranteeing such payment.", "k": "body" }, { "t": "7.72.4 The payment terms applicable to a Transaction shall not be changed after confirmation except in accordance with the applicable procedures of the Platform and with the consent or action required from the relevant Parties.", "k": "body" }, { "t": "7.72.5 In case of any discrepancy between the payment status or payment method displayed on the Platform and the terms otherwise communicated between the Buyer and Seller, the Parties shall cooperate with the Marketplace to verify the applicable Transaction records and resolve the discrepancy in accordance with this Agreement.", "k": "body" }, { "t": "7.73 Payment and Settlement — Application of Fees and Adjustments", "k": "h2" }, { "t": "7.73.1 The Marketplace may calculate and apply applicable Fees, commissions, refunds, penalties, compensation, deductions, adjustments, taxes or other amounts arising in connection with a Transaction in accordance with this Agreement, the applicable Commercial Terms, Policies and Platform Records.", "k": "body" }, { "t": "7.73.2 Unless otherwise expressly specified, applicable amounts may be deducted from funds otherwise available for Settlement to the relevant Participant.", "k": "body" }, { "t": "7.73.3 Where an applicable deduction exceeds the amount available for Settlement, the resulting balance shall remain payable by the relevant Participant and may be recorded as an outstanding amount in accordance with this Agreement.", "k": "body" }, { "t": "7.73.4 The Participant authorises the Marketplace to make such deductions and adjustments to the extent permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.74 Payment and Settlement — Participant’s Continuing Liability", "k": "h2" }, { "t": "7.74.1 The Participant shall remain liable for all amounts properly payable by it in connection with its Account, Transactions, Fees, refunds, deductions, adjustments, Settlements, Wallet balance and other obligations under this Agreement.", "k": "body" }, { "t": "7.74.2 The Participant’s liability shall not be discharged merely because a Transaction has been completed, funds have been released, the Account has been suspended or closed, or the Agreement has expired or been terminated.", "k": "body" }, { "t": "7.74.3 Where any amount becomes payable or recoverable after completion, Settlement, suspension, closure, expiry or termination due to a refund, dispute, reversal, fraud, error, adjustment, statutory requirement or other matter permitted under this Agreement, the Participant shall remain responsible for such amount.", "k": "body" }, { "t": "7.74.4 The Marketplace may recover such amounts in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.75 Payment and Settlement — Participant Statements and Confirmations", "k": "h2" }, { "t": "7.75.1 The Participant shall review the payment, Wallet and Settlement information made available through the Platform and shall promptly notify the Marketplace of any material discrepancy, incorrect entry or unauthorised activity identified by the Participant.", "k": "body" }, { "t": "7.75.2 Where the Participant confirms or accepts any payment, Settlement, refund, adjustment, deduction or Wallet entry through the Platform, such confirmation shall constitute evidence of the Participant’s acknowledgement of the relevant record, subject to the Participant’s rights under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.75.3 Failure to raise an objection within a reasonable period after the relevant information is made available may be considered by the Marketplace when administering the relevant Transaction or resolving any subsequent dispute, but shall not by itself extinguish any right or remedy that cannot lawfully be waived.", "k": "body" }, { "t": "7.75.4 The Marketplace may request confirmation or acknowledgement from the Participant where reasonably necessary to verify or resolve any payment or Settlement matter.", "k": "body" }, { "t": "7.76 Payment and Settlement — No Fiduciary Relationship", "k": "h2" }, { "t": "7.76.1 Nothing in this Agreement shall be construed as creating a fiduciary, trustee, agency, partnership, joint venture or similar relationship between the Marketplace and any Participant in connection with the receipt, holding, processing, refund or Settlement of Transaction funds.", "k": "body" }, { "t": "7.76.2 The Marketplace shall administer payment and Settlement functions in accordance with this Agreement, the applicable Transaction terms, Policies and Applicable Law.", "k": "body" }, { "t": "7.76.3 The Participant acknowledges that the Marketplace's holding or administration of funds in connection with an advance or prepaid Transaction is undertaken solely for the purposes expressly described in this Agreement and does not create any relationship beyond those expressly agreed between the Parties.", "k": "body" }, { "t": "7.76.4 Nothing in this Clause limits any obligation or liability of the Marketplace expressly undertaken under this Agreement or imposed upon it by Applicable Law.", "k": "body" }, { "t": "7.77 Payment and Settlement — No Transfer of Commercial Risk", "k": "h2" }, { "t": "7.77.1 The Marketplace’s receipt, holding, processing or Settlement of funds in connection with an advance or prepaid Transaction shall not transfer to the Marketplace any commercial risk relating to the underlying Transaction.", "k": "body" }, { "t": "7.77.2 The Buyer and Seller shall remain responsible for their respective obligations relating to Product quality, quantity, specifications, delivery, acceptance, payment, taxes, warranties, returns and other commercial matters applicable to the Transaction.", "k": "body" }, { "t": "7.77.3 The Marketplace’s involvement in payment and Settlement shall not be construed as an assumption of responsibility for the performance, solvency, creditworthiness or commercial conduct of either the Buyer or the Seller, except to the extent expressly provided in this Agreement or required under Applicable Law.", "k": "body" }, { "t": "7.78 Payment and Settlement — No Guarantee of Transaction Completion", "k": "h2" }, { "t": "7.78.1 The receipt or holding of funds by the Marketplace in connection with an advance or prepaid Transaction shall not constitute confirmation or guarantee that the Seller will dispatch or deliver the Products, or that the Transaction will otherwise be completed.", "k": "body" }, { "t": "7.78.2 Where a Seller fails to fulfil its obligations within the applicable delivery timeline, including any approved extension, the Marketplace may take such action in relation to the held funds as is permitted under this Agreement, including refunding the Buyer or making appropriate deductions or adjustments.", "k": "body" }, { "t": "7.78.3 Where a Buyer fails to fulfil its obligations, the Marketplace may take such action in relation to the relevant funds as is permitted under this Agreement, the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "7.78.4 The Marketplace’s administration of Transaction funds does not constitute a guarantee of performance by either Party.", "k": "body" }, { "t": "7.79 Payment and Settlement — Marketplace Discretion in Exceptional Circumstances", "k": "h2" }, { "t": "7.79.1 Where circumstances arise that may materially affect the payment, refund or Settlement of a Transaction, the Marketplace may take reasonable administrative measures necessary to protect the integrity of the Platform and the interests of the Parties, subject to this Agreement and Applicable Law.", "k": "body" }, { "t": "7.79.2 Such measures may include temporarily holding or restricting funds, delaying Settlement, seeking additional information or confirmation, suspending a payment-related action, or making an appropriate adjustment or refund.", "k": "body" }, { "t": "7.79.3 The Marketplace shall, where reasonably practicable, consider the relevant Transaction records, information provided by the Parties and the circumstances known to it when exercising such discretion.", "k": "body" }, { "t": "7.79.4 Any action taken under this Clause shall be limited to what the Marketplace reasonably considers necessary in the circumstances and shall not prevent either Party from exercising its rights under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.80 Payment and Settlement — Notification of Material Issues", "k": "h2" }, { "t": "7.80.1 The Participant shall promptly notify the Marketplace upon becoming aware of any material issue that may affect the payment, refund, deduction or Settlement of a Transaction, including any suspected fraud, unauthorised payment, incorrect payment, duplicate payment, material discrepancy or other error.", "k": "body" }, { "t": "7.80.2 The Marketplace may, upon receiving such notification or otherwise becoming aware of such issue, take reasonable steps to verify the matter and may temporarily hold, restrict, adjust or otherwise administer the relevant funds or Settlement in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.80.3 The Participant shall reasonably cooperate with the Marketplace in investigating and resolving any such issue and shall provide relevant information or clarification reasonably requested for that purpose.", "k": "body" }, { "t": "7.80.4 Notification under this Clause shall not, by itself, constitute an admission of liability by the Participant or the Marketplace.", "k": "body" }, { "t": "7.81 Payment and Settlement — Resolution of Payment Errors", "k": "h2" }, { "t": "7.81.1 If the Marketplace identifies or is notified of an error in relation to any payment, refund, deduction, Wallet entry or Settlement, it may investigate and, where appropriate, correct the relevant Platform Records and make corresponding adjustments.", "k": "body" }, { "t": "7.81.2 Such correction may include reversing an incorrect credit or debit, recovering an amount incorrectly released, applying an additional deduction, restoring an amount incorrectly deducted, or processing an appropriate refund or Settlement adjustment.", "k": "body" }, { "t": "7.81.3 The Participant shall cooperate with the Marketplace in implementing any correction reasonably required to rectify an identified error.", "k": "body" }, { "t": "7.81.4 Any correction under this Clause shall be made subject to the applicable Transaction records, this Agreement and Applicable Law.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.82 Payment and Settlement — Reversal of Incorrect Credits", "k": "h2" }, { "t": "7.82.1 Where any amount is incorrectly credited, released or otherwise made available to a Participant due to an error, technical issue, incorrect instruction, duplicate processing or other mistake, the Marketplace may reverse or recover such amount, subject to Applicable Law.", "k": "body" }, { "t": "7.82.2 The Marketplace may recover the incorrectly credited amount by adjustment against the Participant’s Wallet, future Settlement amounts or other amounts payable or releasable to the Participant through the Platform.", "k": "body" }, { "t": "7.82.3 If the amount cannot be fully recovered through such adjustment, the unrecovered balance shall remain payable by the Participant and may be recorded as an outstanding amount.", "k": "body" }, { "t": "7.82.4 The Participant shall not be entitled to retain or claim any amount that was incorrectly credited or released to it solely due to an error or mistake.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.83 Payment and Settlement — Recovery Following Refund or Adjustment", "k": "h2" }, { "t": "7.83.1 Where the Marketplace has processed a refund, compensation, reversal or other adjustment in favour of a Buyer in relation to a Transaction and the amount is attributable to the Seller, the Marketplace may recover such amount from the Seller in accordance with this Agreement.", "k": "body" }, { "t": "7.83.2 Such recovery may be made by deduction from any amount otherwise payable or releasable to the Seller, adjustment through the Seller’s Wallet, or by recording the amount as an outstanding amount payable by the Seller.", "k": "body" }, { "t": "7.83.3 Where the amount available for recovery is insufficient, the Seller shall remain liable for the unrecovered balance, and the Marketplace may restrict further Transactions, Settlement or other Platform functionality until such amount is paid or otherwise resolved.", "k": "body" }, { "t": "7.83.4 Recovery under this Clause shall be without prejudice to any other rights or remedies available to the Marketplace or the Buyer under this Agreement or Applicable Law.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.84 Payment and Settlement — Recovery from Buyer", "k": "h2" }, { "t": "7.84.1 Where any amount becomes recoverable from a Buyer in connection with a Transaction, including due to an incorrect refund, reversal, compensation, adjustment, payment error or other amount payable under this Agreement, the Marketplace may seek recovery of such amount from the Buyer.", "k": "body" }, { "t": "7.84.2 Where permitted under this Agreement and Applicable Law, the Marketplace may adjust such amount against any amount otherwise payable or releasable to the Buyer through the Platform.", "k": "body" }, { "t": "7.84.3 If the amount cannot be recovered through such adjustment, the outstanding balance shall remain payable by the Buyer to the Marketplace or, where applicable, to the relevant Seller.", "k": "body" }, { "t": "7.84.4 The Marketplace may restrict or suspend the Buyer’s further use of payment-related or other Platform functionality until such outstanding amount is paid or otherwise resolved, subject to this Agreement and Applicable Law.", "k": "body" }, { "t": "7.85 Payment and Settlement — No Set-Off by Participant", "k": "h2" }, { "t": "7.85.1 The Participant shall not withhold, deduct, set off or otherwise adjust any amount payable to the Marketplace under this Agreement against any amount that the Participant claims to be entitled to receive from the Marketplace, unless expressly agreed by the Marketplace in writing or otherwise permitted under Applicable Law.", "k": "body" }, { "t": "7.85.2 Any dispute, claim or amount alleged to be recoverable from the Marketplace shall be raised separately in accordance with the applicable dispute resolution procedure and shall not, by itself, suspend or reduce the Participant’s undisputed payment obligations.", "k": "body" }, { "t": "7.85.3 Nothing in this Clause shall restrict any right of set-off or adjustment that cannot lawfully be excluded under Applicable Law.", "k": "body" }, { "t": "7.86 Payment and Settlement — No Obligation to Maintain Funds", "k": "h2" }, { "t": "7.86.1 The Marketplace shall not be required to maintain any minimum balance, reserve or other amount in relation to a Participant’s Account, Wallet or any Transaction, except to the extent expressly required under Applicable Law or expressly agreed by the Marketplace.", "k": "body" }, { "t": "7.86.2 The Marketplace may determine the timing and manner of payment processing, fund release, refund, deduction and Settlement in accordance with this Agreement, the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "7.86.3 Nothing in this Clause shall be construed as requiring the Marketplace to provide financial accommodation, funding or credit to any Participant.", "k": "body" }, { "t": "7.87 Payment and Settlement — No Interest or Return on Held Funds", "k": "h2" }, { "t": "7.87.1 Unless expressly required under Applicable Law, the Participant shall not be entitled to any interest, return, yield, appreciation or other financial benefit in respect of funds received and held by the Marketplace in connection with an advance or prepaid Transaction pending completion and Settlement.", "k": "body" }, { "t": "7.87.2 The holding of such funds shall be solely for administering the relevant Transaction in accordance with this Agreement and shall not create any obligation on the Marketplace to invest, deploy or otherwise utilise such funds for the benefit of the Participant.", "k": "body" }, { "t": "7.87.3 The Marketplace shall not be liable to the Participant for any loss of interest, investment return or other financial benefit that the Participant might otherwise have earned had such funds remained available to it.", "k": "body" }, { "t": "7.88 Payment and Settlement — No Commingling Obligation", "k": "h2" }, { "t": "7.88.1 The Marketplace shall administer funds received in connection with advance or prepaid Transactions in accordance with its applicable internal processes, banking arrangements and Applicable Law.", "k": "body" }, { "t": "7.88.2 The Participant shall not have any right to require the Marketplace to maintain such funds in any particular bank account, segregated account or separate arrangement, except to the extent expressly required by Applicable Law.", "k": "body" }, { "t": "7.88.3 Nothing in this Agreement shall be interpreted as creating an escrow, trust, deposit, payment account or other regulated financial arrangement unless expressly established or required under Applicable Law.", "k": "body" }, { "t": "7.88.4 The Marketplace shall remain responsible for administering and releasing eligible Transaction funds in accordance with the applicable Transaction terms and this Agreement.", "k": "body" }, { "t": "7.89 Payment and Settlement — Banking and Payment Channels", "k": "h2" }, { "t": "7.89.1 The Marketplace may determine the bank account, payment gateway, payment channel or other payment infrastructure through which advance or prepaid Transaction funds are received, processed, held or released.", "k": "body" }, { "t": "7.89.2 The Participant shall make payments only through the payment methods and instructions made available or authorised by the Marketplace for the relevant Transaction.", "k": "body" }, { "t": "7.89.3 The Participant shall not make or request any payment through an unauthorised account, intermediary or payment channel for the purpose of circumventing applicable Fees, Settlement procedures, Transaction records or other Platform requirements.", "k": "body" }, { "t": "7.89.4 Where a Participant makes a payment through an unauthorised channel or contrary to the applicable Platform instructions, the Marketplace may be unable to recognise, process, reconcile or apply such payment to the relevant Transaction, and the Participant shall remain responsible for the underlying payment obligation until appropriately verified and recorded.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.90 Payment and Settlement — Prohibition on Circumvention", "k": "h2" }, { "t": "7.90.1 A Participant shall not circumvent or attempt to circumvent the payment, Fee, Wallet, Settlement or other financial procedures established by the Marketplace in relation to Transactions conducted through the Platform.", "k": "body" }, { "t": "7.90.2 Without limitation, a Participant shall not knowingly structure, redirect or record a Transaction in a manner intended to avoid applicable Fees, commissions, payment procedures, Settlement requirements, deductions or other obligations under this Agreement.", "k": "body" }, { "t": "7.90.3 A Participant shall not request, encourage or facilitate another Participant to make payment outside the prescribed Platform process where such payment is intended to circumvent applicable Platform requirements.", "k": "body" }, { "t": "7.90.4 Where the Marketplace reasonably determines that a Participant has engaged in such circumvention, it may take appropriate action under this Agreement, including restricting the Account, cancelling or suspending Transactions, withholding or adjusting Settlement amounts, recovering amounts due, or applying applicable penalties, subject to Applicable Law.", "k": "body" }, { "t": "7.91 Payment and Settlement — Transactions Conducted Outside the Platform", "k": "h2" }, { "t": "7.91.1 Where a Transaction is initiated, negotiated, confirmed, recorded or otherwise facilitated through the Platform, the Participant shall not intentionally move or complete such Transaction outside the Platform for the purpose of avoiding applicable Fees, commissions, payment procedures, Settlement requirements or other obligations under this Agreement.", "k": "body" }, { "t": "7.91.2 Nothing in this Clause prevents Participants from entering into separate or subsequent commercial transactions outside the Platform that are genuinely independent of a Transaction conducted through the Platform.", "k": "body" }, { "t": "7.91.3 Where the Marketplace reasonably determines that a Participant has intentionally diverted a Platform Transaction outside the Platform to circumvent applicable obligations, the Marketplace may take appropriate action under this Agreement, including restricting the Account, cancelling or suspending Platform privileges, recovering applicable Fees or other amounts, and applying permitted penalties.", "k": "body" }, { "t": "7.91.4 The Participant shall not use contact information, Transaction information or other information obtained through the Platform for the primary purpose of circumventing the Platform’s applicable commercial or payment arrangements.", "k": "body" }, { "t": "7.92 Payment and Settlement — Platform Transaction Records", "k": "h2" }, { "t": "7.92.1 The Participant acknowledges that Transactions conducted through the Platform may be recorded through Orders, POs, SOs, Quotations, payment confirmations, invoices, Wallet entries, Settlement records, communications and other electronic records maintained by the Marketplace.", "k": "body" }, { "t": "7.92.2 The Participant shall ensure that the information and instructions submitted by it through the Platform accurately reflect the commercial and payment terms agreed for the relevant Transaction.", "k": "body" }, { "t": "7.92.3 The Marketplace may rely upon the Platform Records for administering payment and Settlement, calculating applicable amounts, processing refunds and adjustments, and resolving payment-related disputes, subject to this Agreement and Applicable Law.", "k": "body" }, { "t": "7.92.4 If a Participant identifies any material discrepancy in the Platform Records relating to a Transaction, it shall promptly notify the Marketplace and provide reasonable supporting information for verification and correction.", "k": "body" }, { "t": "7.93 Payment and Settlement — Payment Status", "k": "h2" }, { "t": "7.93.1 The payment status of a Transaction shall be determined based on the payment information and confirmation recorded by the Marketplace through the Platform and its applicable payment or administrative systems.", "k": "body" }, { "t": "7.93.2 In an advance or prepaid Transaction, payment shall be treated as received by the Marketplace only when the Buyer has submitted the required payment details and the Marketplace has confirmed the payment through its applicable administrative records or Platform systems.", "k": "body" }, { "t": "7.93.3 A payment instruction, screenshot, bank reference, transaction reference, debit entry or other evidence submitted by a Participant shall not, by itself, constitute confirmation that funds have been received by the Marketplace.", "k": "body" }, { "t": "7.93.4 In a Credit Transaction, payment made directly by the Buyer to the Seller shall be governed by the payment and credit terms agreed between the Buyer and Seller, and the Marketplace may record the payment status based on information provided by the relevant Parties or available through the Platform.", "k": "body" }, { "t": "7.93.5 The Marketplace may require reasonable evidence or confirmation of payment where the payment status of a Transaction is disputed, unclear or cannot otherwise be verified from its records.", "k": "body" }, { "t": "7.94 Payment and Settlement — Payment Confirmation", "k": "h2" }, { "t": "7.94.1 The Marketplace may issue or make available a payment confirmation, receipt, status update or other electronic acknowledgement in respect of an advance or prepaid Transaction after the applicable payment has been verified and recorded.", "k": "body" }, { "t": "7.94.2 Such confirmation shall relate only to the receipt or processing status of the relevant payment and shall not constitute confirmation that the Seller has fulfilled its delivery obligations or that the Transaction has otherwise been completed.", "k": "body" }, { "t": "7.94.3 A payment confirmation may be subject to subsequent correction, reversal, refund or adjustment where required due to an error, payment reversal, fraud, dispute, statutory requirement or other circumstance permitted under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.94.4 The Participant shall retain any payment confirmation and related records reasonably necessary for its accounting, tax, audit and other statutory or business requirements.", "k": "body" }, { "t": "7.95 Payment and Settlement — Payment Reversal", "k": "h2" }, { "t": "7.95.1 Where any payment received in connection with a Transaction is subsequently reversed, returned, rejected, charged back or otherwise becomes unavailable to the Marketplace for any reason, the Marketplace may take appropriate action in relation to the affected Transaction and Settlement.", "k": "body" }, { "t": "7.95.2 Such action may include withholding or reversing a Settlement, recovering amounts already released, adjusting the relevant Wallet, suspending further Transactions or requiring the responsible Participant to pay the affected amount.", "k": "body" }, { "t": "7.95.3 Where a payment reversal affects a Transaction that has already been completed or settled, the Marketplace may make a corresponding post-completion adjustment or recovery in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.95.4 The Participant shall remain responsible for any amount properly payable by it as a result of such payment reversal, notwithstanding that the original payment may previously have been reflected as received or settled.", "k": "body" }, { "t": "7.96 Payment and Settlement — Payment Reconciliation", "k": "h2" }, { "t": "7.96.1 The Marketplace may reconcile payment information received or recorded in connection with a Transaction against the corresponding Platform Records, payment confirmations, Transaction Value, applicable Fees, refunds, deductions and Settlement amounts.", "k": "body" }, { "t": "7.96.2 Where a discrepancy is identified during such reconciliation, the Marketplace may investigate the discrepancy and make appropriate corrections, adjustments or recovery actions in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.96.3 The Participant shall reasonably cooperate in resolving any payment reconciliation discrepancy and shall provide relevant information or evidence reasonably requested by the Marketplace.", "k": "body" }, { "t": "7.96.4 Completion of any reconciliation shall not prevent the Marketplace from correcting a subsequently identified error, reversal, fraud or other payment-related discrepancy in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.97 Payment and Settlement — Settlement Statement", "k": "h2" }, { "t": "7.97.1 The Marketplace may make available to a Participant a Settlement statement, summary or other electronic record setting out amounts received, released, deducted, refunded, adjusted, charged or otherwise accounted for in connection with one or more Transactions.", "k": "body" }, { "t": "7.97.2 The Settlement statement may include, as applicable, Transaction Value, applicable Fees or commissions, refunds, deductions, adjustments, taxes or statutory deductions, Wallet adjustments and the net amount released or payable.", "k": "body" }, { "t": "7.97.3 The Participant shall review the Settlement statement and promptly notify the Marketplace of any material discrepancy identified by the Participant.", "k": "body" }, { "t": "7.97.4 A Settlement statement shall be an administrative record of the relevant payment and Settlement activity and shall remain subject to correction or adjustment in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.98 Payment and Settlement — Settlement Completion", "k": "h2" }, { "t": "7.98.1 Subject to this Agreement, the applicable Transaction terms and any applicable dispute, refund, deduction or adjustment, the Marketplace shall release the eligible amount of Settlement to the Seller upon completion of the conditions applicable to the relevant advance or prepaid Transaction.", "k": "body" }, { "t": "7.98.2 For an advance or prepaid Transaction, where the Seller has delivered the confirmed quantity of Products and marked the Transaction as delivered through the Platform, the Buyer shall have one (1) Business Day from such marking to raise a dispute in accordance with this Agreement.", "k": "body" }, { "t": "7.98.3 If no dispute is raised by the Buyer within such period, the Transaction shall become eligible for automatic release of the applicable funds to the Seller, subject to any applicable Fees, deductions, refunds, adjustments or other amounts authorised under this Agreement.", "k": "body" }, { "t": "7.98.4 No separate reconciliation period shall apply after the conditions for Settlement release have been satisfied, unless a hold, dispute, reversal, fraud-related issue, technical issue or other circumstance expressly permitted under this Agreement or Applicable Law requires otherwise.", "k": "body" }, { "t": "7.99 Payment and Settlement — Release of Funds", "k": "h2" }, { "t": "7.99.1 Upon satisfaction of the applicable conditions for Settlement under this Agreement, the Marketplace shall initiate the release of the eligible funds to the Seller through the applicable banking or payment channel.", "k": "body" }, { "t": "7.99.2 The amount released shall be the amount available for Settlement after accounting for applicable Fees, commissions, refunds, deductions, adjustments, penalties, taxes or other amounts properly payable or recoverable under this Agreement.", "k": "body" }, { "t": "7.99.3 The Marketplace shall not be responsible for delays occurring after initiation of a Settlement that are caused by the receiving bank, payment service provider, banking network, technical infrastructure or other third party not under the Marketplace’s reasonable control.", "k": "body" }, { "t": "7.99.4 A Settlement shall be treated as initiated when the Marketplace records the release instruction through its applicable administrative or payment system. The Participant acknowledges that the actual credit of funds may occur thereafter depending upon the applicable banking or payment channel.", "k": "body" }, { "t": ".100 Payment and Settlement — Final Settlement Amount", "k": "body" }, { "t": "7.100.1 The final Settlement amount payable or releasable to a Participant in respect of a Transaction shall be determined by the Marketplace based on the applicable Transaction Value and after giving effect to all applicable Fees, commissions, refunds, deductions, adjustments, penalties, taxes, statutory deductions and other amounts properly accounted for under this Agreement.", "k": "body" }, { "t": "7.100.2 The final Settlement amount may be reflected in the Participant’s Platform records, Settlement statement or other applicable electronic record.", "k": "body" }, { "t": "7.100.3 Where the final Settlement amount is zero or negative, no amount shall be released to the Participant, and any resulting outstanding amount shall remain payable and recoverable in accordance with this Agreement.", "k": "body" }, { "t": "7.100.4 The determination of the final Settlement amount shall be subject to correction where an error, reversal, fraud, dispute, refund, statutory requirement or other circumstance requiring adjustment is subsequently identified.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.101 Payment and Settlement — Settlement to Seller", "k": "h2" }, { "t": "7.101.1 Subject to the terms of this Agreement, the applicable Transaction terms and completion of the conditions for release, the Marketplace shall settle the eligible amount payable in respect of an advance or prepaid Transaction to the Seller through the applicable payment or banking channel.", "k": "body" }, { "t": "7.101.2 The Seller shall ensure that its bank account and other payment details recorded with the Marketplace are accurate, valid and capable of receiving Settlement amounts.", "k": "body" }, { "t": "7.101.3 The Marketplace may rely on the payment details last provided and verified by the Seller and shall not be responsible for a Settlement failure resulting from incorrect, incomplete, outdated or invalid payment details provided by the Seller.", "k": "body" }, { "t": "7.101.4 Settlement to the Seller shall be subject to any deductions, adjustments, refunds, penalties, Fees, commissions or other amounts properly recoverable under this Agreement.", "k": "body" }, { "t": "7.102 Payment and Settlement — Settlement to Participant", "k": "h2" }, { "t": "7.102.1 Where a Participant is entitled to receive an amount from the Marketplace in connection with a Transaction, refund, adjustment or other Settlement, the Marketplace shall process such amount in accordance with the applicable Transaction terms, this Agreement and Applicable Law.", "k": "body" }, { "t": "7.102.2 The amount payable to the Participant shall be determined after giving effect to all applicable deductions, Fees, commissions, refunds, adjustments, penalties, taxes, statutory deductions and other amounts properly recoverable or payable under this Agreement.", "k": "body" }, { "t": "7.102.3 The Marketplace may process such payment through the bank account or payment channel recorded and verified for the Participant and may rely on the payment details last provided by the Participant.", "k": "body" }, { "t": "7.102.4 Any amount that cannot be released due to incorrect, incomplete, invalid or outdated payment details may remain pending until the Participant provides valid details and any required verification is completed.", "k": "body" }, { "t": "7.103 Payment and Settlement — Settlement Timing", "k": "h2" }, { "t": "7.103.1 The Marketplace shall endeavour to process eligible Settlements at the earliest reasonably practicable time after the applicable conditions for release have been satisfied.", "k": "body" }, { "t": "7.103.2 Unless otherwise expressly specified for a particular Transaction or required by Applicable Law, no additional reconciliation period shall apply after the Settlement conditions have been satisfied.", "k": "body" }, { "t": "7.103.3 The actual time for credit of Settlement amounts may depend upon the applicable banking channel, payment service provider, banking network, holidays, technical processing or other circumstances outside the Marketplace’s reasonable control.", "k": "body" }, { "t": "7.103.4 A delay in actual credit after the Marketplace has initiated the Settlement shall not, by itself, constitute a failure by the Marketplace to process the Settlement.", "k": "body" }, { "t": "7.104 Payment and Settlement — Settlement Delays", "k": "h2" }, { "t": "7.104.1 Where Settlement of an eligible amount is delayed due to a payment processing issue, banking or payment network delay, incorrect payment details, system error, regulatory requirement, dispute, fraud review or other circumstance affecting the release of funds, the Marketplace may temporarily defer the Settlement until the relevant issue is resolved.", "k": "body" }, { "t": "7.104.2 The Marketplace shall, where reasonably practicable, take reasonable steps to resolve or facilitate resolution of a Settlement delay.", "k": "body" }, { "t": "7.104.3 A delay permitted under this Clause shall not constitute a waiver of the Participant’s underlying entitlement to the applicable Settlement amount, subject to any deductions, adjustments, refunds, reversals or other rights under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.104.4 The Marketplace shall not be liable for delays attributable to banks, payment service providers, payment networks, governmental or regulatory authorities, or other third parties beyond the Marketplace’s reasonable control.", "k": "body" }, { "t": "7.105 Payment and Settlement — Suspension of Settlement", "k": "h2" }, { "t": "7.105.1 The Marketplace may temporarily suspend, hold or restrict Settlement of any amount where reasonably necessary due to a pending dispute, suspected fraud or unauthorised activity, payment reversal, material Transaction discrepancy, regulatory requirement, incorrect or incomplete payment information, or other circumstance affecting the validity or proper administration of the Settlement.", "k": "body" }, { "t": "7.105.2 During such suspension or hold, the Marketplace may review the relevant Platform Records and request information, confirmation or supporting evidence from the concerned Participant.", "k": "body" }, { "t": "7.105.3 Upon resolution of the matter, the Marketplace shall process the applicable Settlement, refund, adjustment or other payment action in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.105.4 A suspension or hold under this Clause shall not, by itself, constitute a forfeiture of any amount otherwise properly payable to a Participant.", "k": "body" }, { "t": "7.106 Payment and Settlement — Release After Suspension", "k": "h2" }, { "t": "7.106.1 Once the circumstances giving rise to a suspension, hold or restriction of Settlement have been resolved, the Marketplace may release, refund, adjust or otherwise process the relevant amount in accordance with this Agreement, the applicable Transaction terms and Applicable Law.", "k": "body" }, { "t": "7.106.2 Where the review establishes that the Seller is entitled to the held amount, the Marketplace shall proceed with the applicable Settlement, subject to any Fees, deductions, refunds or adjustments properly applicable to the Transaction.", "k": "body" }, { "t": "7.106.3 Where the review establishes that the Buyer is entitled to a refund or other adjustment, the Marketplace may process such refund or adjustment in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.106.4 Where the review identifies an amount recoverable from a Participant, the Marketplace may apply the recovery mechanisms available under this Agreement.", "k": "body" }, { "t": "7.107 Payment and Settlement — Completion of Settlement", "k": "h2" }, { "t": "7.107.1 A Settlement shall be considered completed when the applicable Settlement amount has been released by the Marketplace through the designated payment or banking channel and the release has been recorded in the Platform Records.", "k": "body" }, { "t": "7.107.2 Completion of Settlement shall not prevent any subsequent correction, reversal, refund, deduction or recovery expressly permitted under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.107.3 Where a Settlement cannot be completed due to circumstances attributable to the receiving Participant, including incorrect or invalid payment details or failure to complete required verification, the Settlement shall remain pending until the relevant issue is resolved.", "k": "body" }, { "t": "7.107.4 The Marketplace may record the status and completion of each Settlement in the Platform Records, and such records may be relied upon for administration of the relevant Transaction.", "k": "body" }, { "t": "7.108 Payment and Settlement — Settlement Records", "k": "h2" }, { "t": "7.108.1 The Marketplace may maintain electronic records of all amounts received, held, released, refunded, deducted, adjusted or otherwise processed in connection with a Transaction.", "k": "body" }, { "t": "7.108.2 Such records may include the payment status, Transaction Value, applicable Fees and commissions, deductions, refunds, adjustments, Settlement amount, Settlement date and other information relevant to the administration of the Transaction.", "k": "body" }, { "t": "7.108.3 The Participant may access or receive such records through the Platform or other means made available by the Marketplace, subject to applicable access controls and retention practices.", "k": "body" }, { "t": "7.108.4 The Marketplace may use such records for accounting, audit, tax, compliance, dispute resolution, fraud prevention, Transaction administration and other legitimate business purposes in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.109 Payment and Settlement — Participant Review of Settlement Records", "k": "h2" }, { "t": "7.109.1 The Participant shall review the payment and Settlement records made available through the Platform and shall promptly notify the Marketplace of any material discrepancy, omission, unauthorised activity or other apparent error relating to such records.", "k": "body" }, { "t": "7.109.2 Where a discrepancy or error is reported, the Marketplace may review the relevant Platform Records and other information reasonably available to it and may make such correction, adjustment or other administrative action as may be appropriate under this Agreement and Applicable Law.", "k": "body" }, { "t": "7.109.3 The Participant shall reasonably cooperate with the Marketplace in verifying any disputed or disputed Settlement record and shall provide information or evidence reasonably required for such verification.", "k": "body" }, { "t": "7.109.4 Nothing in this Clause limits any right or remedy available to a Participant under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.110 Payment and Settlement — Effect of Disputes on Settlement", "k": "h2" }, { "t": "7.110.1 Where a dispute relating to a Transaction may affect the amount payable or releasable to a Participant, the Marketplace may hold or restrict the relevant funds until the dispute is resolved in accordance with this Agreement.", "k": "body" }, { "t": "7.110.2 The Marketplace may review the information and evidence available through the Platform and may communicate with the Buyer and Seller for the purpose of determining the appropriate payment, refund, deduction or Settlement action.", "k": "body" }, { "t": "7.110.3 Where the Marketplace determines that an amount is refundable, payable, deductible or otherwise adjustable following such dispute, the Marketplace may give effect to that determination through the applicable Settlement, refund, Wallet adjustment or recovery mechanism.", "k": "body" }, { "t": "7.110.4 Any decision or action taken by the Marketplace under this Clause shall be subject to the rights and remedies of the Parties under this Agreement and Applicable Law.", "k": "body" }, { "t": "Top of Form", "k": "body" }, { "t": "Bottom of Form", "k": "body" }, { "t": "7.111 Payment and Settlement — Participant Authority and Responsibility", "k": "h2" }, { "t": "7.111.1 The Participant represents and warrants that it has full legal capacity, authority and all necessary approvals to make, receive, authorise and perform all payments and other financial obligations arising from its Transactions and its use of the Platform.", "k": "body" }, { "t": "7.111.2 Where a Participant operates through employees, representatives, agents, authorised persons or other users having access to its Account, all payment instructions, confirmations, approvals and other actions undertaken through such Account shall be deemed to have been authorised by the Participant, unless the Participant establishes that the relevant activity resulted from unauthorised access that was promptly reported to the Marketplace and was not attributable to any act or omission of the Participant or its authorised users.", "k": "body" }, { "t": "7.111.3 The Participant shall ensure that all payment instructions, bank details, Transaction amounts, payment references and other financial information submitted through the Platform are accurate and authorised.", "k": "body" }, { "t": "7.111.4 The Participant shall not use another person's or entity's bank account, payment instrument, financial credentials or payment details except where legally authorised and expressly permitted through the applicable Platform process.", "k": "body" }, { "t": "7.112 Payment and Settlement — Fraud, Suspicious Activity and Unauthorised Transactions", "k": "h2" }, { "t": "7.112.1 The Marketplace may take reasonable measures to prevent, detect, investigate or respond to suspected fraud, money laundering, unauthorised activity, payment abuse, manipulation of Transactions, misuse of Accounts or other suspicious activity affecting the Platform or a Transaction.", "k": "body" }, { "t": "7.112.2 Such measures may include delaying, holding, restricting, cancelling or reversing a payment or Settlement, restricting Account functionality, requesting additional information or verification, reviewing Platform Records, or taking other action reasonably necessary to protect Participants, the Platform or the integrity of Transactions.", "k": "body" }, { "t": "7.112.3 The Marketplace may disclose relevant information to payment service providers, banks, financial institutions, governmental or regulatory authorities, law-enforcement agencies, professional advisers or other persons where reasonably necessary for fraud prevention, investigation, compliance, protection of rights or as required by Applicable Law.", "k": "body" }, { "t": "7.112.4 The Marketplace shall not be required to disclose information concerning fraud detection methods, security controls, risk models or investigative processes where such disclosure could reasonably compromise the security or integrity of the Platform or an investigation.", "k": "body" }, { "t": "7.112.5 Any action taken under this Clause shall be undertaken subject to Applicable Law and shall not constitute a determination that a Participant has committed fraud unless such determination is expressly made following an applicable investigation or otherwise established by competent authority.", "k": "body" }, { "t": "7.113 Payment and Settlement — Third-Party Banking and Payment Infrastructure", "k": "h2" }, { "t": "7.113.1 The Marketplace may use banks, payment gateways, payment service providers, technology providers, communication networks and other third-party service providers in connection with payment processing, fund transfers, Settlement or related administrative functions.", "k": "body" }, { "t": "7.113.2 The Marketplace may rely upon information, confirmations and processing status received from such third parties for administering Transactions and Settlements, subject to reasonable verification where appropriate.", "k": "body" }, { "t": "7.113.3 The Marketplace shall not be responsible for any failure, delay, rejection, interruption, error or unavailability caused by a bank, payment service provider, payment network or other third party beyond the Marketplace's reasonable control, except to the extent directly caused by the Marketplace's breach of an express obligation under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.113.4 Where a third-party failure affects a payment or Settlement, the Marketplace may take reasonable administrative steps to retry, hold, reverse, correct or otherwise process the affected amount in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.114 Payment and Settlement — Taxes, Invoices and Statutory Obligations", "k": "h2" }, { "t": "7.114.1 Each Participant shall be solely responsible for determining and complying with all tax, invoicing, accounting, reporting, withholding, registration and other statutory obligations applicable to its Transactions and amounts received or paid by it.", "k": "body" }, { "t": "7.114.2 The Marketplace may collect, deduct, withhold, report or otherwise account for any tax or statutory amount where required or permitted under Applicable Law.", "k": "body" }, { "t": "7.114.3 The Marketplace may rely upon the GSTIN, PAN, tax status, declarations and other information provided or verified by the Participant for administering applicable Transactions and Settlements.", "k": "body" }, { "t": "7.114.4 The Participant shall promptly notify the Marketplace of any change affecting its GSTIN, PAN, tax registration, tax status or other information relevant to payment or Settlement.", "k": "body" }, { "t": "7.114.5 The Marketplace shall not be responsible for any additional tax, interest, penalty, assessment, loss of credit or other consequence arising from incorrect, incomplete, outdated or misleading tax or registration information provided by the Participant or from the Participant's failure to comply with its own statutory obligations.", "k": "body" }, { "t": "7.115 Payment and Settlement — Indemnification for Payment-Related Matters", "k": "h2" }, { "t": "7.115.1 The Participant shall indemnify, defend and hold harmless the Marketplace, its directors, officers, employees, representatives and service providers from and against losses, liabilities, claims, demands, penalties, costs, expenses and reasonable legal fees arising out of or relating to:", "k": "body" }, { "t": "(a) any unauthorised, fraudulent or unlawful payment activity attributable to the Participant or its Account;", "k": "body" }, { "t": "(b) incorrect or unauthorised payment instructions or bank details provided by the Participant;", "k": "body" }, { "t": "(c) any breach by the Participant of its payment, tax, invoicing, credit or other financial obligations;", "k": "body" }, { "t": "(d) any claim by a third party arising from the Participant's use of a payment instrument, bank account or financial credential without proper authority;", "k": "body" }, { "t": "(e) any attempt by the Participant to circumvent Platform payment, Fee or Settlement procedures; or", "k": "body" }, { "t": "(f) any inaccurate, misleading or fraudulent information supplied by the Participant in connection with a payment or Settlement.", "k": "body" }, { "t": "7.115.2 The indemnity under this Clause shall not apply to the extent that a competent authority finally determines that the relevant loss was directly caused by the Marketplace's fraud, wilful misconduct or liability that cannot lawfully be excluded or indemnified.", "k": "body" }, { "t": "7.116 Payment and Settlement — Marketplace's Right to Correct Records", "k": "h2" }, { "t": "7.116.1 The Marketplace may correct, modify or update Platform Records relating to payment, Wallet, Fees, refunds, deductions or Settlement where it identifies an administrative, clerical, technical, calculation, reconciliation or other error.", "k": "body" }, { "t": "7.116.2 Where a correction results in an amount becoming payable to or recoverable from a Participant, the Marketplace may make the corresponding adjustment through the applicable Settlement, Wallet or other recovery mechanism provided under this Agreement.", "k": "body" }, { "t": "7.116.3 The Marketplace shall, where reasonably practicable, provide or make available sufficient information regarding a material correction to enable the affected Participant to understand the nature of the adjustment.", "k": "body" }, { "t": "7.116.4 A correction of a Platform Record shall not, by itself, constitute an amendment of the underlying commercial terms of a Transaction unless the correction is necessary to accurately reflect those terms or is otherwise permitted under this Agreement. 7.117 Payment and Settlement — Limitation of Marketplace Liability", "k": "body" }, { "t": "7.117.1 Subject to Applicable Law and the express obligations undertaken by the Marketplace under this Agreement, the Marketplace shall not be liable for losses arising solely from:", "k": "body" }, { "t": "(a) a Buyer's failure to pay a Seller in a Credit Transaction;", "k": "body" }, { "t": "(b) a Seller's failure to perform its delivery or other commercial obligations;", "k": "body" }, { "t": "(c) incorrect, incomplete or outdated bank or payment details provided by a Participant;", "k": "body" }, { "t": "(d) delays, failures or errors of banks, payment service providers, payment networks or other third parties;", "k": "body" }, { "t": "(e) a Participant's failure to maintain access to its registered mobile number, email address, Account or authentication credentials;", "k": "body" }, { "t": "(f) taxes, duties, penalties or statutory liabilities arising from the Participant's own business or Transactions; or", "k": "body" }, { "t": "(g) circumstances beyond the Marketplace's reasonable control.", "k": "body" }, { "t": "7.117.2 Nothing in this Clause shall exclude or limit liability to the extent such exclusion or limitation is prohibited under Applicable Law.", "k": "body" }, { "t": "7.117.3 The Marketplace does not guarantee that every payment, refund or Settlement will be completed within a particular period where completion depends upon circumstances outside its reasonable control.", "k": "body" }, { "t": "7.118 Payment and Settlement — No Guarantee of Solvency or Creditworthiness", "k": "h2" }, { "t": "7.118.1 The Marketplace does not represent, warrant or guarantee the solvency, liquidity, creditworthiness, financial capacity, payment ability or commercial reliability of any Participant.", "k": "body" }, { "t": "7.118.2 Any GST verification, Account approval, Transaction history, Platform status, payment processing or Settlement administered by the Marketplace shall not be construed as a credit assessment, financial guarantee, endorsement, certification or assurance regarding a Participant.", "k": "body" }, { "t": "7.118.3 In particular, where a Buyer and Seller undertake a Credit Transaction, the Marketplace does not guarantee payment by the Buyer and does not assume responsibility for collection, enforcement or recovery of the credit extended by the Seller, except for administrative assistance expressly provided under this Agreement.", "k": "body" }, { "t": "7.118.4 Each Participant shall independently assess the commercial and credit risks associated with entering into a Transaction with another Participant.", "k": "body" }, { "t": "7.119 Payment and Settlement — Post-Termination and Survival", "k": "h2" }, { "t": "7.119.1 Expiry, suspension or termination of this Agreement or a Participant's Account shall not affect any payment, refund, deduction, recovery, Settlement, Wallet balance or other financial obligation accrued before such expiry, suspension or termination.", "k": "body" }, { "t": "7.119.2 The Marketplace may continue to process, hold, release, refund, deduct, adjust or recover amounts relating to Transactions initiated before suspension, expiry or termination to the extent reasonably necessary to complete or resolve such Transactions.", "k": "body" }, { "t": "7.119.3 Any outstanding amount payable by a Participant to the Marketplace shall remain immediately due and recoverable in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "7.119.4 The provisions of this Section relating to payment obligations, recovery, deductions, adjustments, indemnification, records, disputes and other matters which by their nature are intended to continue shall survive expiry or termination of this Agreement.", "k": "body" }, { "t": "7.120 Payment and Settlement — General Protection and Reservation of Rights", "k": "h2" }, { "t": "7.120.1 The rights, powers, remedies, deductions, holds, adjustments and recovery mechanisms available to the Marketplace under this Section are cumulative and are in addition to any other rights or remedies available to the Marketplace under this Agreement or Applicable Law.", "k": "body" }, { "t": "7.120.2 The Marketplace may exercise any applicable right or remedy independently or in combination with any other right or remedy, subject to Applicable Law.", "k": "body" }, { "t": "7.120.3 No delay, failure, omission or temporary inability of the Marketplace to exercise any payment or Settlement-related right shall constitute a waiver of that right.", "k": "body" }, { "t": "7.120.4 Nothing in this Section shall be interpreted as requiring the Marketplace to assume the underlying commercial, credit, Product, delivery, tax or other obligations of a Buyer or Seller.", "k": "body" }, { "t": "7.120.5 Nothing in this Section shall be interpreted as excluding, restricting or overriding any mandatory requirement of Applicable Law, including any requirement applicable to payment processing, fund handling, taxation, consumer protection, data protection, fraud prevention or financial regulation.", "k": "body" }, { "t": "7.120.6 If any provision of this Section is determined to be invalid, unlawful or unenforceable, it shall be modified or limited to the minimum extent necessary to make it valid and enforceable, and the remaining provisions shall continue in full force and effect.", "k": "body" }, { "t": "7.120.7 This Section shall be read together with the remainder of the Agreement, applicable Transaction terms, Commercial Terms and Policies. In the event of inconsistency, the applicable order of precedence set out in Clause 7.58 shall apply, subject always to mandatory Applicable Law.", "k": "body" }, { "t": "7.120.8 The Participant acknowledges that the payment and Settlement mechanisms described in this Section are material terms of its use of the Platform and agrees to comply with all applicable requirements relating to payments, Transactions, Wallet, Fees and Settlement.", "k": "body" }, { "t": "8. PARTICIPANT OBLIGATIONS AND PROHIBITED CONDUCT", "k": "h1" }, { "t": "8.1 General Participant Obligations", "k": "h2" }, { "t": "8.1.1 The Participant shall use the Platform and Marketplace Services only for lawful, legitimate and bona fide business purposes and in accordance with this Agreement, applicable Policies and Applicable Law.", "k": "body" }, { "t": "8.1.2 The Participant shall conduct all activities through the Platform in a professional, honest, fair and commercially responsible manner and shall not engage in any conduct that may adversely affect another Participant, the Marketplace, the Platform or the integrity of any Transaction.", "k": "body" }, { "t": "8.1.3 The Participant shall be solely responsible for ensuring that all information, representations, commitments, Products, Orders, Quotations, POs, SOs, invoices, payment instructions and other content or actions submitted or undertaken by it through the Platform are accurate, lawful and authorised.", "k": "body" }, { "t": "8.1.4 The Participant shall comply with all applicable requirements relating to its business, Products, taxation, invoicing, licensing, registration, transportation, payment obligations and other activities undertaken through the Platform.", "k": "body" }, { "t": "8.1.5 The Participant shall not use the Platform in any manner that is fraudulent, deceptive, misleading, abusive, unlawful, unauthorised or reasonably likely to compromise the security, reliability or reputation of the Platform or any Marketplace participant.", "k": "body" }, { "t": "8.1.6 The Participant shall promptly cooperate with the Marketplace in relation to reasonable requests concerning Transactions, complaints, disputes, fraud prevention, verification, security incidents, regulatory requirements and other matters necessary for the proper operation of the Platform.", "k": "body" }, { "t": "8.1.7 The Participant acknowledges that compliance with this Clause is a continuing obligation throughout the period during which the Participant has access to or uses the Platform.", "k": "body" }, { "t": "8.2 Prohibited Conduct", "k": "h2" }, { "t": "8.2.1 The Participant shall not use the Platform or Marketplace Services for any unlawful, fraudulent, deceptive, abusive, or unauthorised purpose, or in any manner that may adversely affect the Platform, Marketplace, other Participants, Transactions, or the integrity of the marketplace.", "k": "body" }, { "t": "8.2.2 The Participant shall not provide, submit, publish, or communicate any false, misleading, incomplete, fabricated, or materially inaccurate information in connection with its Account, business, Products, Orders, Quotations, POs, SOs, invoices, payments, delivery status, disputes, claims, or any other Platform activity.", "k": "body" }, { "t": "8.2.3 The Participant shall not create, place, accept, manipulate, or cancel Orders or Transactions for the purpose of artificially inflating activity, creating false demand or supply, misleading another Participant, avoiding payment, obtaining an undue benefit, or otherwise manipulating the Platform or Transaction records.", "k": "body" }, { "t": "8.2.4 The Participant shall not impersonate, represent itself as, or falsely claim to be another person, business, Participant, employee, representative, or agent, or falsely represent any affiliation, authority, approval, certification, or relationship.", "k": "body" }, { "t": "8.2.5 The Participant shall not use another Participant’s Account, credentials, payment information, business information, or other access credentials without proper authorisation.", "k": "body" }, { "t": "8.2.6 The Participant shall not attempt to gain unauthorised access to any Account, Platform system, database, network, administrative interface, or information belonging to the Marketplace or another Participant.", "k": "body" }, { "t": "8.2.7 The Participant shall not introduce, transmit, upload, or distribute any virus, malware, malicious code, harmful software, corrupted file, or other material intended or reasonably likely to interfere with or damage the Platform, its systems, or another Participant’s systems.", "k": "body" }, { "t": "8.2.8 The Participant shall not interfere with, disrupt, overload, disable, circumvent, or attempt to compromise the operation, security, availability, functionality, or technical infrastructure of the Platform.", "k": "body" }, { "t": "8.2.9 The Participant shall not use automated means, scraping tools, bots, crawlers, scripts, or similar mechanisms to access, extract, copy, monitor, reproduce, or collect Platform data or content except where expressly permitted by the Marketplace.", "k": "body" }, { "t": "8.2.10 The Participant shall not circumvent or attempt to circumvent any Platform restriction, Transaction control, payment mechanism, Fee, commission, Settlement process, security measure, Account limitation, or other control implemented by the Marketplace.", "k": "body" }, { "t": "8.2.11 The Participant shall not use the Platform to facilitate the sale, purchase, supply, distribution, or transportation of Products that are prohibited, unlawful, counterfeit, stolen, restricted without required authorisation, unsafe, or otherwise not permitted under the Agreement, Policies, or Applicable Law.", "k": "body" }, { "t": "8.2.12 The Participant shall not knowingly submit fraudulent payment instructions, falsify payment confirmations, manipulate Transaction or delivery status, or otherwise attempt to obtain release of funds, refund, Settlement, credit, or other financial benefit to which it is not entitled.", "k": "body" }, { "t": "8.2.13 The Participant shall not use the Platform to harass, threaten, abuse, intimidate, discriminate against, or engage in unlawful or seriously inappropriate conduct toward the Marketplace, its personnel, or another Participant.", "k": "body" }, { "t": "8.2.14 The Participant shall not use Platform communications, contact information, or Transaction information to send spam, unsolicited commercial communications, malicious content, or communications unrelated to legitimate Platform or Transaction purposes.", "k": "body" }, { "t": "8.2.15 The Participant shall not misuse, copy, disclose, sell, distribute, reverse engineer, or commercially exploit Platform information, software, systems, interfaces, or confidential information except as expressly permitted under the Agreement or Applicable Law.", "k": "body" }, { "t": "8.2.16 The Participant shall not engage in any conduct intended to manipulate marketplace visibility, rankings, pricing, demand, supply, reviews, ratings, Transaction volumes, or other Platform-generated information in a misleading or unfair manner.", "k": "body" }, { "t": "8.2.17 The Participant shall not use the Platform or information obtained through the Platform to facilitate any activity that is intended to defeat, evade, or circumvent Applicable Law, taxation requirements, regulatory requirements, or legitimate compliance controls.", "k": "body" }, { "t": "8.2.18 The Participant shall not knowingly assist, facilitate, encourage, or permit any other person to engage in conduct prohibited under this Clause 8.2.", "k": "body" }, { "t": "8.2.19 Nothing in this Clause shall restrict any activity that is expressly permitted by the Marketplace or required or protected under Applicable Law.", "k": "body" }, { "t": "8.2.20 The Marketplace may, subject to Applicable Law, investigate suspected prohibited conduct and may take appropriate action, including restricting access, suspending or terminating an Account, cancelling or restricting Transactions, withholding or adjusting Settlement, requiring additional information, or taking other measures permitted under the Agreement and Policies.", "k": "body" }, { "t": "8.3 Compliance with Applicable Laws and Regulations", "k": "h2" }, { "t": "8.3.1 The Participant shall, at all times, comply with all Applicable Laws in connection with its registration, Account, use of the Platform, Products, Orders, Transactions, payments, transportation, communications, and other activities carried out through or in connection with the Platform.", "k": "body" }, { "t": "8.3.2 The Participant shall obtain and maintain, at its own cost, all registrations, licences, approvals, permissions, certificates, authorisations, consents, and other governmental or regulatory requirements applicable to its business, Products, and activities.", "k": "body" }, { "t": "8.3.3 The Participant shall be solely responsible for compliance with all applicable requirements relating to taxation, GST, invoicing, accounting, product standards, packaging, labelling, transportation, storage, environmental requirements, employment, consumer or commercial protections, import/export, and other regulatory matters applicable to the Participant or the relevant Transaction.", "k": "body" }, { "t": "8.3.4 Where a Participant acts as a Seller in a Transaction, it shall ensure that the sale, supply, Product, pricing, invoicing, packaging, labelling, dispatch, transportation, and delivery comply with all Applicable Laws applicable to such activity.", "k": "body" }, { "t": "8.3.5 Where a Participant acts as a Buyer in a Transaction, it shall ensure that its purchase, intended use, receipt, storage, transportation, payment, and handling of the Products comply with all Applicable Laws applicable to such activity.", "k": "body" }, { "t": "8.3.6 The Participant shall not use the Platform to conduct any activity that would cause the Marketplace to violate Applicable Law or knowingly expose the Marketplace, its service providers, or another Participant to regulatory or legal liability.", "k": "body" }, { "t": "8.3.7 The Participant shall promptly inform the Marketplace if it becomes aware of any actual or suspected violation of Applicable Law that may materially affect the Platform, a Transaction, a Product, or another Participant.", "k": "body" }, { "t": "8.3.8 The Participant shall provide such information, confirmations, declarations, or records as may reasonably be required by the Marketplace for compliance with Applicable Law, governmental requirements, regulatory directions, or legitimate compliance processes.", "k": "body" }, { "t": "8.3.9 The Marketplace may restrict, suspend, cancel, or refuse any Account, Product, Order, Transaction, payment, Settlement, or Platform activity where it reasonably considers such action necessary to comply with Applicable Law, a governmental or regulatory direction, or applicable legal or compliance requirements.", "k": "body" }, { "t": "8.3.10 Nothing in this Agreement shall require either Party to act in violation of Applicable Law, and where any provision of this Agreement conflicts with a mandatory requirement of Applicable Law, such mandatory requirement shall prevail to the extent of the conflict.", "k": "body" }, { "t": "8.4 Accuracy and Authenticity of Information", "k": "h2" }, { "t": "8.4.1 The Participant shall ensure that all information and documents submitted to or generated through the Platform by or on behalf of the Participant are genuine, accurate, complete, current, and not misleading.", "k": "body" }, { "t": "8.4.2 The Participant shall promptly update any information that becomes inaccurate, incomplete, invalid, or outdated where such information is relevant to its Account, Products, Transactions, payments, tax status, or compliance obligations.", "k": "body" }, { "t": "8.4.3 The Participant shall not knowingly conceal, alter, falsify, manipulate, or misrepresent any material fact relating to its business, Products, Transactions, payment obligations, delivery status, disputes, or compliance status.", "k": "body" }, { "t": "8.4.4 Where any information supplied by the Participant is found or reasonably suspected to be materially inaccurate, misleading, fraudulent, or unauthorised, the Marketplace may take appropriate action under this Agreement and the Policies.", "k": "body" }, { "t": "8.5 Communications and Conduct with Other Participants", "k": "h2" }, { "t": "8.5.1 The Participant shall communicate with other Participants in a professional, lawful, and commercially reasonable manner.", "k": "body" }, { "t": "8.5.2 The Participant shall not make false, threatening, abusive, defamatory, fraudulent, or misleading statements concerning another Participant, the Marketplace, Products, Orders, Transactions, or payment matters.", "k": "body" }, { "t": "8.5.3 The Participant shall not misuse contact information or other information obtained through the Platform for purposes unrelated to legitimate business activities or the relevant Transaction.", "k": "body" }, { "t": "8.5.4 The Participant shall remain responsible for all communications, commitments, representations, and instructions made through its Account by its authorised representatives, employees, agents, or other persons granted access by the Participant.", "k": "body" }, { "t": "8.6 Anti-Circumvention", "k": "h2" }, { "t": "8.6.1 The Participant shall not knowingly use information, contacts, commercial opportunities, or Transaction information obtained through the Platform for the purpose of circumventing the Marketplace in order to avoid applicable Fees, commissions, payment mechanisms, Platform processes, or other contractual obligations.", "k": "body" }, { "t": "8.6.2 The Participant shall not structure, split, redirect, or otherwise manipulate a Transaction for the purpose of avoiding any Fee, commission, Settlement requirement, restriction, or control applicable under this Agreement or the Policies.", "k": "body" }, { "t": "8.6.3 Nothing in this Clause shall prohibit legitimate commercial dealings that are independently established and are not undertaken for the purpose of circumventing the Marketplace or avoiding contractual obligations.", "k": "body" }, { "t": "8.7 Cooperation, Verification and Investigation", "k": "h2" }, { "t": "8.7.1 The Participant shall reasonably cooperate with the Marketplace in any investigation concerning suspected fraud, misuse, prohibited conduct, security incidents, Transaction disputes, payment issues, regulatory requirements, or breaches of this Agreement.", "k": "body" }, { "t": "8.7.2 The Marketplace may request explanations, confirmations, records, Transaction details, payment information, delivery information, or other information reasonably necessary to investigate or resolve such matters, subject to Applicable Law.", "k": "body" }, { "t": "8.7.3 The Participant shall not knowingly obstruct, mislead, delay, or interfere with any legitimate investigation or verification process conducted by the Marketplace.", "k": "body" }, { "t": "8.7.4 Where reasonably necessary, the Marketplace may temporarily restrict relevant Platform activities while an investigation or verification is ongoing.", "k": "body" }, { "t": "8.8 Intellectual Property and Platform Materials", "k": "h2" }, { "t": "8.8.1 The Participant shall not copy, reproduce, modify, distribute, sell, license, publish, reverse engineer, decompile, disassemble, or otherwise exploit the Platform or any software, interface, technology, content, design, database, trademark, logo, or other intellectual property belonging to or lawfully used by the Marketplace, except as expressly permitted under this Agreement or Applicable Law.", "k": "body" }, { "t": "8.8.2 The Participant shall not remove, alter, conceal, or interfere with any proprietary notice, copyright notice, trademark, branding, security mechanism, or other rights notice displayed on or incorporated into the Platform.", "k": "body" }, { "t": "8.8.3 The Participant shall use Platform materials solely for purposes reasonably connected with its authorised use of the Platform.", "k": "body" }, { "t": "8.9 Consequences of Breach", "k": "h2" }, { "t": "8.9.1 Without prejudice to any other rights or remedies available under this Agreement or Applicable Law, the Marketplace may take appropriate action where the Participant breaches this Section 8 or where the Marketplace reasonably believes that such breach has occurred or may occur.", "k": "body" }, { "t": "8.9.2 Such action may include issuing a warning, requiring corrective action, restricting Products or Platform functionality, cancelling or restricting Orders or Transactions, suspending Account access, withholding or adjusting Settlement, restricting payment or other Platform services, or terminating the Participant's Account and/or this Agreement.", "k": "body" }, { "t": "8.9.3 The Marketplace may take immediate action where reasonably necessary to protect the Platform, another Participant, Transaction funds, Products, data, security, or compliance with Applicable Law.", "k": "body" }, { "t": "8.9.4 Any action taken by the Marketplace under this Section shall be subject to Applicable Law and shall not prevent the Marketplace from exercising any other contractual or legal right or remedy available to it.", "k": "body" }, { "t": "8.9.5 Suspension, restriction, cancellation, or termination of the Participant's Account shall not release the Participant from any payment, indemnity, confidentiality, Transaction, dispute, recovery, or other obligation that accrued before such action or which by its nature survives such action.", "k": "body" }, { "t": "9. MARKETPLACE RIGHTS, RESPONSIBILITIES AND LIMITATIONS", "k": "h1" }, { "t": "9.1 Marketplace Role", "k": "h2" }, { "t": "9.1.1 The Marketplace operates and provides the Platform as a technology-enabled B2B marketplace intended to facilitate interactions and Transactions between Participants.\n9.1.2 The Marketplace may provide technology, communication, payment facilitation, Settlement, logistics facilitation, verification, support, dispute assistance, and other services as may be made available from time to time.\n9.1.3 Except where expressly stated otherwise in this Agreement, the Marketplace does not itself act as the Buyer or Seller in a Transaction and does not acquire ownership, title, possession, or commercial interest in Products merely by facilitating a Transaction.\n9.1.4 The Marketplace is not responsible for the commercial performance, solvency, creditworthiness, conduct, representations, Products, quality, quantity, specifications, pricing, delivery, transportation, warranties, or other obligations of a Participant, except to the extent expressly assumed by the Marketplace under this Agreement or required by Applicable Law.", "k": "body" }, { "t": "9.2 Marketplace Services", "k": "h2" }, { "t": "9.2.1 The Marketplace may determine the nature, scope, availability, functionality, and manner of providing Marketplace Services.\n9.2.2 The Marketplace may introduce, modify, suspend, discontinue, replace, or add Platform features, processes, services, integrations, or functionalities from time to time.\n9.2.3 The Marketplace may engage employees, contractors, technology providers, payment service providers, logistics providers, verification service providers, professional advisers, and other third parties to provide or support Marketplace Services.\n9.2.4 Availability of any particular Marketplace Service shall not create an obligation on the Marketplace to provide such service continuously or indefinitely.", "k": "body" }, { "t": "9.3 Marketplace Administration", "k": "h2" }, { "t": "9.3.1 The Marketplace may administer and operate the Platform in accordance with this Agreement, the Policies, and Applicable Law.\n9.3.2 The Marketplace may establish reasonable operational, technical, security, commercial, compliance, and risk-control procedures for the Platform.\n9.3.3 The Marketplace may review Platform activity, Transaction records, communications, Products, Orders, payment information, complaints, and other relevant information for legitimate operational, security, compliance, fraud-prevention, dispute-resolution, and enforcement purposes, subject to Applicable Law.\n9.3.4 The Marketplace may take reasonable administrative action where necessary to protect the Platform, Participants, Transaction integrity, payment processes, data, or compliance with Applicable Law.", "k": "body" }, { "t": "9.4 Marketplace Discretion", "k": "h2" }, { "t": "9.4.1 Subject to this Agreement and Applicable Law, the Marketplace may determine whether to accept, reject, restrict, suspend, cancel, or otherwise act upon an Account, Product, Order, Transaction, payment, Settlement, or Platform activity.\n9.4.2 The Marketplace may impose reasonable conditions, limitations, transaction limits, verification requirements, security measures, or other controls based on operational, commercial, technical, legal, compliance, or risk considerations.\n9.4.3 The exercise of any right or discretion by the Marketplace in one circumstance shall not require the Marketplace to exercise the same right or discretion in another circumstance.\n9.4.4 Any administrative action taken by the Marketplace shall not, by itself, constitute an admission of liability, wrongdoing, or fault by the Marketplace or any Participant.", "k": "body" }, { "t": "9.5 Platform Information and Records", "k": "h2" }, { "t": "9.5.1 The Marketplace may maintain Platform Records relating to Accounts, Products, Orders, Transactions, communications, payments, Settlements, deliveries, complaints, disputes, and other Platform activities.\n9.5.2 Subject to Applicable Law, Platform Records maintained by or on behalf of the Marketplace may be used as evidence of Platform activity and Transaction events.\n9.5.3 The Marketplace may rely on information submitted through the Platform by Participants and shall not be required to independently verify every representation, document, Product detail, Transaction instruction, or communication submitted by a Participant.\n9.5.4 The Marketplace may correct administrative, technical, calculation, reconciliation, or recording errors in Platform Records and make corresponding adjustments where reasonably necessary.", "k": "body" }, { "t": "9.6 No Guarantee of Participant Performance", "k": "h2" }, { "t": "9.6.1 The Marketplace does not guarantee that any Participant will enter into a Transaction, perform its obligations, make payment, accept an Order, supply or receive Products, complete delivery, honour a warranty, or otherwise perform as represented.\n9.6.2 The Marketplace does not guarantee the financial capacity, solvency, creditworthiness, business reputation, authenticity, capability, licensing status, or legal compliance of any Participant.\n9.6.3 Registration, GST verification, Account approval, Transaction history, Platform activity, or availability of payment or Settlement functionality shall not constitute an endorsement, certification, recommendation, or guarantee of any Participant.", "k": "body" }, { "t": "9.7 No Guarantee of Product Quality or Suitability", "k": "h2" }, { "t": "9.7.1 Except to the extent expressly agreed by the Marketplace in writing or required by Applicable Law, the Marketplace does not manufacture, inspect, test, own, control, possess, or independently certify Products offered or supplied by Participants.\n9.7.2 The Marketplace does not guarantee that Products are genuine, merchantable, fit for a particular purpose, safe, compliant, available, suitable, or consistent with any description, specification, sample, image, quotation, or representation provided by a Participant.\n9.7.3 Responsibility for Products and all representations relating to Products shall remain with the Participant responsible for such Products under the relevant Transaction and this Agreement.", "k": "body" }, { "t": "9.8 Marketplace Communication and Support", "k": "h2" }, { "t": "9.8.1 The Marketplace may provide communication channels, customer or Participant support, notifications, alerts, administrative assistance, and dispute-related assistance as part of Marketplace Services.\n9.8.2 Support provided by the Marketplace shall not transfer the commercial, contractual, Product, payment, delivery, or other obligations of one Participant to the Marketplace.\n9.8.3 The Marketplace may communicate with Participants through verified email addresses, mobile numbers, Platform notifications, dashboards, or other communication channels made available by the Marketplace.\n9.8.4 Participants shall reasonably cooperate with support and administrative processes and provide accurate information necessary for resolution of matters raised through the Platform.", "k": "body" }, { "t": "9.9 Marketplace Intervention in Transactions", "k": "h2" }, { "t": "9.9.1 The Marketplace may intervene administratively in a Transaction where reasonably necessary to address a dispute, payment issue, delivery issue, fraud concern, compliance matter, security issue, suspected breach, or other material issue affecting the Platform or Transaction.\n9.9.2 Such intervention may include requesting information, communicating with the relevant Participants, restricting Transaction activity, holding or adjusting Settlement, facilitating resolution, cancelling or modifying Platform status, or taking other measures permitted under this Agreement and Applicable Law.\n9.9.3 Administrative intervention by the Marketplace shall not make the Marketplace a party to the underlying commercial contract between Buyer and Seller unless expressly agreed otherwise.", "k": "body" }, { "t": "9.10 Platform Availability and Technical Limitations", "k": "h2" }, { "t": "9.10.1 The Marketplace shall use commercially reasonable efforts to maintain the availability and functionality of the Platform, subject to maintenance, upgrades, technical limitations, security requirements, third-party dependencies, and circumstances beyond the Marketplace's reasonable control.\n9.10.2 The Participant acknowledges that the Platform may from time to time experience interruptions, delays, errors, downtime, maintenance periods, connectivity issues, or temporary unavailability.\n9.10.3 The Marketplace does not warrant that the Platform will always be uninterrupted, timely, secure, error-free, or free from defects.\n9.10.4 Temporary unavailability of the Platform shall not relieve a Participant of obligations that have already accrued or that can reasonably be performed without Platform access.", "k": "body" }, { "t": "9.11 Third-Party Services and Integrations", "k": "h2" }, { "t": "9.11.1 The Platform may contain or depend upon integrations, links, systems, services, or infrastructure provided by third parties.\n9.11.2 The Marketplace may rely upon information, status updates, confirmations, or processing results received from such third parties where reasonably necessary for providing Marketplace Services.\n9.11.3 The Marketplace shall not be responsible for failures, delays, interruptions, inaccuracies, or unavailability caused solely by third-party systems or services, except to the extent such responsibility cannot lawfully be excluded or arises from the Marketplace's own breach of this Agreement.", "k": "body" }, { "t": "9.12 Suspension or Restriction by Marketplace", "k": "h2" }, { "t": "9.12.1 The Marketplace may suspend, restrict, limit, or disable all or part of a Participant's access to the Platform or Marketplace Services where reasonably necessary due to breach of this Agreement, suspected fraud, security concerns, regulatory requirements, payment issues, prohibited conduct, inaccurate information, risk concerns, operational requirements, or other circumstances permitted under this Agreement.\n9.12.2 Where reasonably practicable and legally permissible, the Marketplace may communicate the reason for such action to the Participant.\n9.12.3 Suspension or restriction shall not affect any rights, obligations, liabilities, payment amounts, or claims that accrued before the suspension or restriction.", "k": "body" }, { "t": "9.13 Marketplace Liability Limitations", "k": "h2" }, { "t": "9.13.1 Except to the extent expressly provided in this Agreement or required by Applicable Law, the Marketplace shall not be responsible for losses arising solely from the acts, omissions, defaults, insolvency, negligence, misconduct, or non-performance of another Participant.\n9.13.2 The Marketplace shall not be responsible for losses resulting solely from incorrect information, instructions, bank details, payment details, Product information, delivery information, or other information submitted by a Participant.\n9.13.3 The Marketplace shall not be responsible for indirect or consequential commercial losses arising from a Participant's independent commercial relationship with another Participant, except to the extent such exclusion is prohibited by Applicable Law.\n9.13.4 Nothing in this Clause shall exclude or limit liability that cannot lawfully be excluded or limited under Applicable Law.", "k": "body" }, { "t": "9.14 No Agency, Partnership or Fiduciary Relationship", "k": "h2" }, { "t": "9.14.1 The Marketplace's operation of the Platform and provision of Marketplace Services shall not create any agency, partnership, joint venture, employment, franchise, fiduciary, or other representative relationship between the Marketplace and any Participant, except where expressly agreed in writing.\n9.14.2 No Participant shall have authority to bind, represent, or incur any obligation on behalf of the Marketplace unless expressly authorised in writing.\n9.14.3 A Participant shall not represent to any third party that it is an employee, agent, partner, representative, or authorised signatory of the Marketplace unless expressly authorised.", "k": "body" }, { "t": "9.15 Reservation of Rights", "k": "h2" }, { "t": "9.15.1 The Marketplace reserves all rights not expressly granted to the Participant under this Agreement.\n9.15.2 Nothing in this Agreement shall prevent the Marketplace from exercising any right or remedy available under Applicable Law.\n9.15.3 The Marketplace's failure or delay in exercising any right shall not constitute a waiver of that right.\n9.15.4 The rights and protections provided to the Marketplace under this Section are cumulative and shall be in addition to any other rights and remedies available under this Agreement, the Policies, or Applicable Law.", "k": "body" }, { "t": "10. DISPUTES, CLAIMS AND RESOLUTION PROCESS", "k": "h1" }, { "t": "10.1 Transaction-Level Disputes", "k": "h2" }, { "t": "10.1.1 Any dispute, complaint, claim, objection, or disagreement arising between Buyer and Seller in connection with a Transaction, including relating to Product quality, quantity, specification, pricing, delivery, Transportation, damage, shortage, invoicing, payment, return, replacement, refund, or other Transaction-related matter, may be raised through the Platform in accordance with the applicable Policies and procedures.\n10.1.2 The Participant raising a dispute shall provide accurate and sufficient information and supporting evidence reasonably available to it, including relevant Orders, Purchase Orders, Sales Orders, invoices, delivery records, photographs, communications, payment records, or other Transaction documents.\n10.1.3 A dispute shall be raised within the time period specified under this Agreement, the applicable Transaction terms, or the Policies, as applicable. Where no specific period is prescribed, the Participant shall raise the dispute within a reasonable period after becoming aware of the relevant issue.\n10.1.4 Raising a dispute shall not automatically establish that the claim is valid, nor shall it by itself constitute an admission of liability by the other Participant or the Marketplace.", "k": "body" }, { "t": "10.2 Participant's First Responsibility to Resolve", "k": "h2" }, { "t": "10.2.1 Buyer and Seller shall first make reasonable efforts to resolve any Transaction-related dispute directly and in good faith through the communication facilities available on the Platform.\n10.2.2 Each Participant shall provide reasonable cooperation, explanations, documents, and information necessary to enable the other Participant to understand and evaluate the dispute.\n10.2.3 A Participant shall not intentionally delay, obstruct, or frustrate a legitimate dispute-resolution process.", "k": "body" }, { "t": "10.3 Marketplace Assistance", "k": "h2" }, { "t": "10.3.1 Where a dispute is not resolved between the relevant Participants, the Marketplace may, at its discretion, provide administrative assistance in facilitating resolution.\n10.3.2 Such assistance may include reviewing Platform Records, communicating with the Participants, requesting additional information, seeking clarification, reviewing delivery or payment status, and facilitating a mutually acceptable resolution.\n10.3.3 The Marketplace may establish procedures, timelines, evidence requirements, and other operational requirements for handling disputes through the Platform.\n10.3.4 The Marketplace's assistance is intended to facilitate administration and resolution of Platform Transactions and does not make the Marketplace a party to the underlying commercial contract between Buyer and Seller.", "k": "body" }, { "t": "10.4 Marketplace Administrative Decision", "k": "h2" }, { "t": "10.4.1 Where a dispute affects payment, Settlement, refund, Transaction status, or other Platform-administered matters, the Marketplace may make an administrative determination based on the Platform Records, information provided by the Participants, applicable Transaction terms, this Agreement, the Policies, and other evidence reasonably available to it.\n10.4.2 The Marketplace may determine, subject to this Agreement and Applicable Law, whether funds should be released, held, refunded, adjusted, deducted, credited, or otherwise dealt with through the Platform.\n10.4.3 The Marketplace may also determine appropriate administrative action concerning cancellation, return, replacement, Transaction closure, Settlement adjustment, or restriction of Platform functionality.\n10.4.4 The Marketplace is not required to conduct a judicial or forensic investigation or determine legal liability between Participants before taking an administrative decision for purposes of Platform administration.\n10.4.5 An administrative decision made by the Marketplace for Platform purposes shall not constitute a judicial determination of legal rights or liability between the Participants.", "k": "body" }, { "t": "10.5 Evidence and Platform Records", "k": "h2" }, { "t": "10.5.1 Participants shall preserve relevant records and evidence relating to any Transaction or dispute for such period as may be required under Applicable Law or reasonably necessary for resolution of the matter.\n10.5.2 The Marketplace may consider Platform Records, including Orders, Quotations, Purchase Orders, Sales Orders, invoices, payment confirmations, communications, delivery information, timestamps, Account records, and other electronically recorded information, while reviewing a dispute.\n10.5.3 Where appropriate, the Marketplace may request additional documentary or other evidence from either Participant.\n10.5.4 Failure by a Participant to provide requested information within the specified or reasonable period may be considered by the Marketplace when making an administrative determination, subject to Applicable Law.", "k": "body" }, { "t": "10.6 Payment and Settlement During Disputes", "k": "h2" }, { "t": "10.6.1 Where a dispute relates to an Advance Transaction for which funds are held by the Marketplace, the Marketplace may continue to hold such funds until the dispute is resolved or an administrative determination is made.\n10.6.2 Where appropriate, the Marketplace may release, refund, deduct, adjust, or otherwise apply held funds based on the outcome of the dispute and the applicable Transaction terms.\n10.6.3 In a Credit Transaction, the Marketplace shall not be responsible for collecting amounts owed directly between Buyer and Seller and may only administer matters within the scope of Marketplace Services.\n10.6.4 A dispute shall not automatically suspend payment obligations that are independent of the disputed matter unless otherwise determined under this Agreement, the applicable Transaction terms, or the Policies.", "k": "body" }, { "t": "10.7 Product-Related Claims", "k": "h2" }, { "t": "10.7.1 Claims relating to Product quality, quantity, specification, authenticity, damage, shortage, defect, warranty, or conformity shall primarily remain the responsibility of the Participant responsible for the relevant Product or Transaction obligation.\n10.7.2 The Marketplace may facilitate communication, evidence collection, return or replacement coordination, or Settlement adjustment where such functionality is available.\n10.7.3 The Marketplace does not, merely by facilitating a Product dispute, assume responsibility for manufacturing defects, Product warranties, Product quality, or the underlying commercial obligations of the Seller.", "k": "body" }, { "t": "10.8 Delivery and Transportation Claims", "k": "h2" }, { "t": "10.8.1 Claims concerning delay, non-delivery, shortage, damage, loss, incorrect delivery, or other Transportation-related matters shall be handled in accordance with the applicable Transaction terms, Transportation arrangements, and Policies.\n10.8.2 The Marketplace may review available dispatch, delivery, tracking, acknowledgement, and other Transportation records when considering such claims.\n10.8.3 Responsibility for Transportation-related loss or damage shall be determined in accordance with the applicable allocation of risk and responsibility under this Agreement and the relevant Transaction terms.", "k": "body" }, { "t": "10.9 Payment Disputes and Reversals", "k": "h2" }, { "t": "10.9.1 Where a dispute concerns payment status, payment confirmation, reversal, chargeback, refund, incorrect credit, or other payment-related matter, the Marketplace may review relevant Platform Records and information received from applicable banking or payment service providers.\n10.9.2 The Marketplace may temporarily restrict Settlement or other Platform functionality while a payment-related dispute or investigation is pending.\n10.9.3 Where a payment is subsequently determined to have been incorrectly credited, reversed, duplicated, refunded, or otherwise improperly processed, the Marketplace may make the corresponding correction, adjustment, recovery, or deduction in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "10.10 Fraud, Misconduct and Security-Related Disputes", "k": "h2" }, { "t": "10.10.1 Where a dispute involves suspected fraud, impersonation, unauthorised Account access, payment misuse, manipulation of Platform Records, prohibited conduct, or other security concerns, the Marketplace may investigate the matter and take protective measures.\n10.10.2 Such measures may include suspension or restriction of Accounts, Transactions, Products, payments, Settlement, communications, or other Platform functionality.\n10.10.3 The Marketplace may require additional verification or information and may disclose relevant information to banks, payment service providers, insurers, professional advisers, governmental authorities, regulators, or law enforcement agencies where permitted or required by Applicable Law.\n10.10.4 Protective action taken during an investigation shall not by itself constitute a final finding that a Participant has committed fraud or misconduct.", "k": "body" }, { "t": "10.11 Time Limits and Failure to Respond", "k": "h2" }, { "t": "10.11.1 The Marketplace may prescribe reasonable response periods for Participants involved in a dispute.\n10.11.2 Where a Participant fails to respond within the applicable period, the Marketplace may proceed based on the information and evidence available to it.\n10.11.3 Failure to respond shall not automatically constitute an admission of liability unless expressly provided under the applicable Transaction terms, Policies, or Applicable Law.", "k": "body" }, { "t": "10.12 Finality of Marketplace Administrative Decisions", "k": "h2" }, { "t": "10.12.1 Subject to Applicable Law and any express review mechanism provided by the Marketplace, an administrative decision made by the Marketplace concerning release, refund, Settlement, adjustment, Transaction status, or other Platform administration shall be treated as final for purposes of administration of the relevant Platform Transaction.\n10.12.2 The Marketplace may correct an administrative decision where it identifies a material error, receives materially new information, or is required to do so under Applicable Law.\n10.12.3 Nothing in this Clause prevents a Participant from exercising any statutory or other legal right that cannot lawfully be excluded or restricted.", "k": "body" }, { "t": "10.13 Independent Legal Rights of Participants", "k": "h2" }, { "t": "10.13.1 The underlying commercial relationship between Buyer and Seller remains governed by their applicable commercial terms, Orders, Purchase Orders, Sales Orders, invoices, communications, and Applicable Law.\n10.13.2 A Participant may pursue any legal remedy available to it against another Participant, subject to the terms of the relevant commercial relationship and Applicable Law.\n10.13.3 The Marketplace's administrative role shall not prevent a Participant from asserting rights or claims that cannot lawfully be waived.", "k": "body" }, { "t": "10.14 Disputes with the Marketplace", "k": "h2" }, { "t": "10.14.1 Any dispute, claim, or disagreement between a Participant and the Marketplace arising out of or relating to this Agreement, the Platform, Marketplace Services, Fees, Settlement, Account restrictions, suspension, termination, or other matters shall first be notified to the Marketplace in writing through the designated communication channel.\n10.14.2 The Parties shall make reasonable efforts to resolve such dispute through good-faith discussions before commencing formal proceedings, except where immediate legal or injunctive relief is reasonably necessary or such prior process is not required under Applicable Law.\n10.14.3 The procedure for formal resolution of disputes between the Participant and Marketplace, including governing law, jurisdiction, arbitration, or other applicable mechanism, shall be governed by the dispute-resolution provisions set out elsewhere in this Agreement.", "k": "body" }, { "t": "10.15 No Waiver by Dispute Process", "k": "h2" }, { "t": "10.15.1 Participation in any dispute-resolution process shall not constitute a waiver of any right, claim, defence, remedy, or obligation under this Agreement or Applicable Law.\n10.15.2 The Marketplace's decision to assist in resolving a dispute shall not create an obligation to intervene in future disputes or establish a precedent for the treatment of any other Transaction.", "k": "body" }, { "t": "10.16 Continuing Obligations", "k": "h2" }, { "t": "10.16.1 A dispute shall not, unless expressly determined otherwise, relieve either Participant of obligations that are unrelated to the disputed matter.\n10.16.2 Participants shall continue to comply with their obligations relating to payment, confidentiality, data protection, preservation of records, cooperation, and other obligations that by their nature continue during or after a dispute.\n10.16.3 Rights and obligations arising from a dispute, including payment, recovery, indemnification, record preservation, and enforcement obligations, shall survive completion, cancellation, suspension, or termination of the relevant Transaction or Account to the extent necessary to give effect to such rights and obligations.", "k": "body" }, { "t": "11. CONFIDENTIALITY AND DATA PROTECTION", "k": "h1" }, { "t": "11.1 Confidential Information", "k": "h2" }, { "t": "11.1.1 For the purposes of this Agreement, “Confidential Information” means any non-public information disclosed or made available by one Party to the other Party, whether orally, electronically, visually, in writing, through the Platform, or by any other means, which is confidential by its nature or which a reasonable person would understand to be confidential.\n11.1.2 Confidential Information may include business information, commercial terms, pricing, customer or supplier information, Transaction information, financial information, technical information, software, systems, security information, business strategies, Platform information, trade secrets, and other proprietary information.\n11.1.3 Information shall not be treated as Confidential Information to the extent that it is lawfully available to the public other than through a breach of this Agreement, was already lawfully known to the receiving Party without a confidentiality obligation, is independently developed without use of the disclosing Party's Confidential Information, or is lawfully received from a third party without a confidentiality obligation.", "k": "body" }, { "t": "11.2 Confidentiality Obligations", "k": "h2" }, { "t": "11.2.1 Each Party shall keep the other Party's Confidential Information confidential and shall use it only for purposes connected with performing, administering, or exercising rights under this Agreement or a relevant Transaction.\n11.2.2 Neither Party shall disclose Confidential Information to any third party except as permitted under this Agreement, with the prior consent of the disclosing Party, or where disclosure is required or permitted by Applicable Law.\n11.2.3 Each Party shall take reasonable measures to protect Confidential Information against unauthorised access, use, disclosure, alteration, loss, or destruction.\n11.2.4 A Party may disclose Confidential Information to its employees, officers, professional advisers, contractors, service providers, or representatives who have a legitimate need to know such information, provided that the disclosing Party remains responsible for ensuring appropriate confidentiality obligations apply to such persons.", "k": "body" }, { "t": "11.3 Participant Transaction Information", "k": "h2" }, { "t": "11.3.1 A Participant shall treat information relating to another Participant's business, Products, Orders, pricing, Transactions, payment arrangements, customers, suppliers, and other commercial information obtained through the Platform as confidential.\n11.3.2 A Participant shall not use another Participant's information obtained through the Platform for purposes unrelated to legitimate business activities or the relevant Transaction.\n11.3.3 The obligations under this Clause shall not prevent a Participant from using information that it independently possesses or lawfully obtains from another source.", "k": "body" }, { "t": "11.4 Marketplace Information", "k": "h2" }, { "t": "11.4.1 The Participant shall keep confidential all non-public information relating to the Marketplace, Platform, Marketplace Services, systems, security arrangements, internal processes, commercial arrangements, Fees, technology, and other proprietary information made available to it.\n11.4.2 The Participant shall not disclose or commercially exploit such information except as expressly permitted under this Agreement or Applicable Law.\n11.4.3 Nothing in this Clause restricts disclosure of information that is lawfully required to be disclosed under Applicable Law.", "k": "body" }, { "t": "11.5 Permitted Disclosures", "k": "h2" }, { "t": "11.5.1 A Party may disclose Confidential Information where required by Applicable Law, court order, governmental authority, regulatory authority, or lawful governmental request.\n11.5.2 Where legally permitted, the receiving Party shall, where reasonably practicable, provide prior notice to the disclosing Party before making such disclosure.\n11.5.3 The receiving Party shall disclose only such portion of Confidential Information as is reasonably necessary to comply with the relevant requirement.", "k": "body" }, { "t": "11.6 Data Collection and Processing", "k": "h2" }, { "t": "11.6.1 The Participant acknowledges that the Marketplace may collect, store, use, process, analyse, transmit, and otherwise handle information relating to the Participant, its Account, authorised representatives, Products, Orders, Transactions, payments, communications, and Platform activities for purposes of providing and administering Marketplace Services.\n11.6.2 Such processing may include Account administration, Participant verification, Transaction processing, payment and Settlement administration, customer support, dispute resolution, fraud prevention, security, risk management, compliance, record keeping, analytics, system improvement, and enforcement of this Agreement.\n11.6.3 The Marketplace shall process Personal Data in accordance with Applicable Law and its applicable privacy or data-protection policies, as amended from time to time.\n11.6.4 The Participant shall ensure that it has the necessary authority, notices, consents, or other lawful basis required under Applicable Law for Personal Data that it provides to the Marketplace relating to its employees, representatives, customers, suppliers, or other individuals.", "k": "body" }, { "t": "11.7 Personal Data", "k": "h2" }, { "t": "11.7.1 Each Party shall comply with Applicable Law relating to the collection, use, storage, disclosure, transfer, security, and processing of Personal Data in connection with this Agreement.\n11.7.2 The Participant shall not provide Personal Data to the Marketplace that it is not legally authorised to provide.\n11.7.3 The Participant shall use Personal Data obtained through the Platform only for lawful and legitimate purposes connected with the relevant business activity or Transaction and shall not misuse, sell, unlawfully disclose, or otherwise exploit such information.", "k": "body" }, { "t": "11.8 Data Security", "k": "h2" }, { "t": "11.8.1 The Participant shall maintain reasonable administrative, technical, and organisational safeguards to protect Account credentials, Transaction information, Personal Data, payment information, and other confidential information under its control.\n11.8.2 The Participant shall promptly notify the Marketplace upon becoming aware of any unauthorised access, disclosure, loss, misuse, compromise, or security incident affecting Platform-related information or credentials under its control.\n11.8.3 The Participant shall reasonably cooperate with the Marketplace in investigating, containing, and addressing any security incident affecting the Platform or Transactions.", "k": "body" }, { "t": "11.9 Use of Platform Records and Data", "k": "h2" }, { "t": "11.9.1 Subject to Applicable Law, the Marketplace may retain and use Platform Records for operating the Platform, administering Transactions, resolving disputes, preventing fraud, maintaining security, analysing Platform performance, complying with legal requirements, enforcing this Agreement, and protecting its legitimate business interests.\n11.9.2 The Marketplace may generate aggregated, statistical, analytical, or otherwise non-identifying information from Platform activity and may use such information for legitimate business, operational, analytical, security, and service-improvement purposes, provided that such use complies with Applicable Law.\n11.9.3 Nothing in this Clause grants the Marketplace unrestricted rights over Personal Data beyond those permitted under Applicable Law.", "k": "body" }, { "t": "11.10 Disclosure to Service Providers and Authorities", "k": "h2" }, { "t": "11.10.1 The Marketplace may disclose relevant information to its banks, payment service providers, logistics providers, technology providers, verification providers, professional advisers, insurers, contractors, and other service providers where reasonably necessary to provide Marketplace Services or administer the Platform.\n11.10.2 The Marketplace may disclose information to governmental authorities, regulators, courts, law enforcement agencies, or other competent authorities where required or permitted by Applicable Law.\n11.10.3 The Marketplace may also disclose information where reasonably necessary to investigate fraud, security incidents, unlawful activity, suspected breaches, payment issues, or threats to the Platform or its Participants, subject to Applicable Law.", "k": "body" }, { "t": "11.11 Data Retention", "k": "h2" }, { "t": "11.11.1 The Marketplace may retain Account information, Platform Records, Transaction records, payment records, communications, dispute records, and other information for such period as reasonably necessary for legitimate business purposes, contractual obligations, dispute resolution, security, fraud prevention, regulatory compliance, legal obligations, or enforcement of rights.\n11.11.2 Where Applicable Law requires a specific retention period or deletion requirement, the Marketplace shall handle the relevant information in accordance with such requirement.", "k": "body" }, { "t": "11.12 Participant Responsibility for Data", "k": "h2" }, { "t": "11.12.1 The Participant shall be responsible for ensuring that information and Personal Data submitted by it to the Platform is accurate and lawfully obtained and provided.\n11.12.2 The Participant shall not upload, transmit, or otherwise provide information to the Platform that it is prohibited from disclosing or processing under Applicable Law or a contractual obligation.\n11.12.3 The Participant shall take reasonable steps to prevent unauthorised persons from accessing information obtained through its Account.", "k": "body" }, { "t": "11.13 Return, Deletion and Continuing Protection", "k": "h2" }, { "t": "11.13.1 Upon termination or closure of an Account, each Party shall, subject to Applicable Law and legitimate retention requirements, cease using the other Party's Confidential Information except where continued use is necessary to exercise or perform rights or obligations arising under this Agreement or a Transaction.\n11.13.2 Confidentiality obligations shall continue after termination or expiry of this Agreement for so long as the relevant information remains confidential, subject to Applicable Law.\n11.13.3 Obligations relating to Personal Data, security, confidentiality, and information protection shall survive termination to the extent required by their nature or Applicable Law.", "k": "body" }, { "t": "11.14 No Unauthorised Publicity", "k": "h2" }, { "t": "11.14.1 Neither Party shall use the name, logo, trademark, or other identifying information of the other Party in public announcements, advertising, promotional materials, or other publicity without prior written consent, except where required by Applicable Law or expressly permitted under this Agreement.\n11.14.2 The Marketplace may identify a Participant as a registered or participating business on the Platform where reasonably necessary for Platform operation, Transaction administration, or other legitimate purposes, subject to Applicable Law and applicable privacy requirements.", "k": "body" }, { "t": "11.15 Remedies", "k": "h2" }, { "t": "11.15.1 Each Party acknowledges that unauthorised disclosure, misuse, or compromise of Confidential Information or Personal Data may cause harm for which monetary compensation may not always be an adequate remedy.\n11.15.2 Accordingly, subject to Applicable Law, the affected Party may seek appropriate contractual, equitable, injunctive, or other legal remedies for a breach of this Section, in addition to any other remedies available under this Agreement or Applicable Law.", "k": "body" }, { "t": "12. INTELLECTUAL PROPERTY AND PLATFORM RIGHTS", "k": "h1" }, { "t": "12.1 Ownership of Marketplace Intellectual Property", "k": "h2" }, { "t": "12.1.1 All rights, title, and interest in and to the Platform, Marketplace Services, software, technology, interfaces, designs, databases, processes, systems, features, content, trademarks, logos, trade names, service marks, documentation, and other intellectual property owned, developed, licensed, or lawfully used by the Marketplace shall remain vested in the Marketplace or the respective rights holder.\n12.1.2 Nothing in this Agreement shall transfer or assign any ownership interest in such intellectual property to the Participant.\n12.1.3 Except for the limited rights expressly granted under this Agreement, the Participant shall have no licence, ownership, or other proprietary right in or to the Marketplace's intellectual property.", "k": "body" }, { "t": "12.2 Limited Right to Use the Platform", "k": "h2" }, { "t": "12.2.1 Subject to the Participant's continuing compliance with this Agreement, the Marketplace grants the Participant a limited, non-exclusive, non-transferable, non-sublicensable right to access and use the Platform solely for legitimate business purposes permitted under this Agreement.\n12.2.2 This right shall automatically cease upon suspension, termination, or expiry of the Participant's Account or this Agreement, except to the extent continued access is expressly permitted by the Marketplace or required by Applicable Law.", "k": "body" }, { "t": "12.3 Marketplace Trademarks and Branding", "k": "h2" }, { "t": "12.3.1 The Participant shall not use the Marketplace's name, trademarks, logos, trade names, domain names, service marks, branding, or other identifying material without prior written authorisation.\n12.3.2 The Participant shall not register or attempt to register any trademark, trade name, domain name, social media identifier, or other designation that is identical or confusingly similar to any trademark, name, or branding belonging to or lawfully used by the Marketplace.\n12.3.3 Any permitted use of Marketplace branding shall be strictly in accordance with the instructions and brand guidelines provided by the Marketplace.", "k": "body" }, { "t": "12.4 Participant Content and Information", "k": "h2" }, { "t": "12.4.1 The Participant retains ownership of its own trademarks, business information, Product information, photographs, descriptions, documents, and other materials submitted to the Platform, subject to the rights granted under this Agreement.\n12.4.2 The Participant represents that it has all rights, permissions, licences, and authorisations necessary to submit, publish, display, communicate, or otherwise use such materials through the Platform.\n12.4.3 The Participant shall not submit any material that infringes, misappropriates, or otherwise violates the intellectual property or other rights of any third party.", "k": "body" }, { "t": "12.5 Licence to Marketplace", "k": "h2" }, { "t": "12.5.1 By submitting or making materials available through the Platform, the Participant grants the Marketplace a non-exclusive, worldwide, royalty-free licence to host, store, reproduce, process, display, transmit, format, modify where technically necessary, and otherwise use such materials solely to the extent reasonably necessary to provide, operate, administer, improve, secure, and promote the Platform and Marketplace Services.\n12.5.2 The licence under this Clause shall continue for so long as reasonably necessary for the Marketplace to perform its obligations, maintain Platform Records, resolve disputes, comply with Applicable Law, protect its legitimate interests, or otherwise exercise rights arising from Transactions conducted through the Platform.\n12.5.3 The Marketplace shall not acquire ownership of Participant Content merely by receiving or using it in accordance with this Agreement.", "k": "body" }, { "t": "12.6 Product Images and Descriptions", "k": "h2" }, { "t": "12.6.1 Where a Participant uploads or provides Product photographs, specifications, descriptions, catalogues, logos, or other Product-related materials, the Participant authorises the Marketplace to display and use such materials for listing, search, discovery, Transaction, communication, support, and other legitimate Platform purposes.\n12.6.2 The Participant shall ensure that such materials are accurate and that their use by the Marketplace does not infringe any third-party rights.\n12.6.3 The Marketplace may remove, modify, restrict, or decline to display any Product material that it reasonably considers inaccurate, inappropriate, unlawful, infringing, misleading, or inconsistent with the Platform or Policies.", "k": "body" }, { "t": "12.7 Platform Software and Technology", "k": "h2" }, { "t": "12.7.1 The Participant shall not copy, reproduce, modify, adapt, translate, reverse engineer, decompile, disassemble, derive source code from, or otherwise attempt to discover the underlying structure, algorithms, source code, or technical architecture of the Platform, except to the extent such restriction is prohibited by Applicable Law.\n12.7.2 The Participant shall not circumvent or interfere with any technical protection, authentication mechanism, access control, security feature, or other technological measure implemented by the Marketplace.\n12.7.3 The Participant shall not create derivative products, services, interfaces, databases, or systems substantially based on the Platform without the Marketplace's prior written consent.", "k": "body" }, { "t": "12.8 Platform Data and Databases", "k": "h2" }, { "t": "12.8.1 All rights in databases, compilations, datasets, analytics, Platform Records, system-generated information, and other data created, collected, organised, or maintained by the Marketplace in connection with the Platform shall belong to the Marketplace or the applicable rights holder, subject to Participant rights under Applicable Law.\n12.8.2 The Participant shall not systematically extract, copy, reproduce, distribute, sell, license, publish, or commercially exploit Platform data or information except as expressly permitted under this Agreement.\n12.8.3 The Participant shall not use Platform data to create or operate a competing marketplace, database, directory, commercial information service, or similar service without the Marketplace's prior written consent.", "k": "body" }, { "t": "12.9 Feedback and Suggestions", "k": "h2" }, { "t": "12.9.1 The Participant may voluntarily provide suggestions, ideas, recommendations, feedback, or proposed improvements concerning the Platform or Marketplace Services.\n12.9.2 Unless otherwise agreed in writing, the Participant grants the Marketplace a perpetual, worldwide, royalty-free right to use, reproduce, modify, develop, incorporate, and otherwise utilise such feedback without payment or attribution.\n12.9.3 The Marketplace shall have no obligation to implement or use any feedback provided by the Participant.", "k": "body" }, { "t": "12.10 Intellectual Property Complaints", "k": "h2" }, { "t": "12.10.1 A Participant that reasonably believes that any material made available through the Platform infringes its intellectual property rights may notify the Marketplace through the designated communication channel, providing sufficient information to identify the allegedly infringing material and the basis of the claim.\n12.10.2 The Marketplace may, where appropriate and subject to Applicable Law, review the complaint and take reasonable administrative action, including requesting clarification, restricting access to the relevant material, removing content, or communicating with the relevant Participant.\n12.10.3 The Marketplace does not assume responsibility for determining the ultimate validity of any third-party intellectual property claim and may require the concerned parties to resolve the underlying legal dispute directly.", "k": "body" }, { "t": "12.11 Participant Indemnity for Intellectual Property Claims", "k": "h2" }, { "t": "12.11.1 The Participant shall be responsible for any claim that materials, Product information, trademarks, photographs, documents, content, or other intellectual property supplied or made available by the Participant through the Platform infringes or misappropriates the rights of a third party.\n12.11.2 The Participant shall indemnify the Marketplace in accordance with the indemnification provisions of this Agreement against losses, claims, liabilities, damages, costs, and reasonable legal expenses arising from such infringement or unauthorised use to the extent attributable to the Participant.", "k": "body" }, { "t": "12.12 No Unauthorised Use After Termination", "k": "h2" }, { "t": "12.12.1 Upon termination or suspension of the Participant's Account or this Agreement, the Participant shall immediately cease any use of Marketplace intellectual property that is no longer authorised.\n12.12.2 Termination shall not affect ownership of intellectual property or rights that accrued before termination.\n12.12.3 Any rights or licences expressly intended to survive termination shall continue only to the extent specified in this Agreement or required by Applicable Law.", "k": "body" }, { "t": "12.13 Reservation of Intellectual Property Rights", "k": "h2" }, { "t": "12.13.1 All intellectual property rights not expressly granted to the Participant under this Agreement are reserved by the Marketplace and the applicable rights holders.\n12.13.2 Nothing in this Agreement shall be interpreted as an implied transfer, assignment, licence, or waiver of intellectual property rights except where expressly provided or required by Applicable Law.", "k": "body" }, { "t": "13. INDEMNIFICATION AND LIMITATION OF LIABILITY", "k": "h1" }, { "t": "13.1 Participant Indemnification", "k": "h2" }, { "t": "13.1.1 The Participant shall indemnify, defend, and hold harmless the Marketplace, its directors, officers, employees, representatives, affiliates, contractors, service providers, and permitted assigns from and against any claims, demands, actions, proceedings, losses, liabilities, damages, penalties, costs, expenses, and reasonable legal fees arising out of or relating to:\n(a) the Participant's breach of this Agreement or any applicable Policy;\n(b) any breach of Applicable Law by the Participant;\n(c) any Product, listing, description, representation, warranty, or other information provided by the Participant;\n(d) any Transaction entered into, performed, or failed to be performed by the Participant;\n(e) any infringement, misappropriation, or violation of a third party's intellectual property, privacy, confidentiality, or other rights arising from materials or information supplied by the Participant;\n(f) any fraudulent, negligent, unlawful, misleading, abusive, or unauthorised act or omission of the Participant or its employees, representatives, agents, contractors, or authorised Account users;\n(g) any unauthorised payment instruction, payment activity, Account activity, or misuse of credentials attributable to the Participant;\n(h) any tax, GST, invoicing, statutory, regulatory, licensing, or reporting obligation of the Participant;\n(i) any claim relating to the Participant's Products, manufacturing, supply, packaging, labelling, storage, Transportation, delivery, warranty, recall, or other Product-related obligation;\n(j) any claim arising from the Participant's dealings with another Participant; or\n(k) any misuse of the Platform or Marketplace Services by the Participant.", "k": "body" }, { "t": "13.2 Indemnification Procedure", "k": "h2" }, { "t": "13.2.1 Where the Marketplace becomes aware of a claim that may give rise to an indemnification obligation under this Section, it may notify the Participant within a reasonable period, where reasonably practicable.\n13.2.2 The Participant shall reasonably cooperate with the Marketplace in responding to such claim and shall provide relevant information and assistance reasonably requested.\n13.2.3 The Marketplace may participate in the defence or resolution of any claim for which it seeks indemnification.\n13.2.4 The Participant shall not settle any claim in a manner that admits liability on behalf of, imposes an obligation upon, or materially prejudices the rights of the Marketplace without the Marketplace's prior written consent.\n13.2.5 Nothing in this Clause shall prevent the Marketplace from taking immediate action reasonably necessary to protect its rights, property, Platform, Participants, or compliance position.", "k": "body" }, { "t": "13.3 Participant Responsibility for Its Own Acts", "k": "h2" }, { "t": "13.3.1 The Participant remains solely responsible for its business, Products, commercial arrangements, employees, representatives, agents, contractors, Account users, and Transactions.\n13.3.2 The Marketplace's facilitation, review, communication, administrative assistance, payment processing, Settlement, or other Marketplace Services shall not transfer such responsibility to the Marketplace except to the extent expressly assumed under this Agreement or required by Applicable Law.", "k": "body" }, { "t": "13.4 Marketplace Liability", "k": "h2" }, { "t": "13.4.1 Subject to Applicable Law, the Marketplace shall be responsible only for obligations expressly undertaken by it under this Agreement.\n13.4.2 The Marketplace shall not be liable merely because it provides a Platform through which Participants interact or conduct Transactions.\n13.4.3 The Marketplace shall not be responsible for any act, omission, default, negligence, fraud, insolvency, non-payment, non-delivery, Product defect, misrepresentation, breach, or other conduct of another Participant except to the extent expressly provided under this Agreement or required by Applicable Law.", "k": "body" }, { "t": "13.5 Excluded Circumstances", "k": "h2" }, { "t": "13.5.1 Subject to Applicable Law, the Marketplace shall not be liable for losses arising solely from:\n(a) failure of a Buyer or Seller to perform its obligations;\n(b) failure to make or receive payment in a Credit Transaction;\n(c) Product defects, shortages, damage, quality issues, or non-conformity attributable to a Participant;\n(d) delays or failures in Transportation or delivery attributable to a Participant or third-party service provider;\n(e) incorrect information, bank details, payment instructions, Product information, or other information submitted by a Participant;\n(f) unauthorised access to a Participant's Account caused by the Participant's failure to protect its credentials;\n(g) acts or failures of banks, payment service providers, logistics providers, telecommunications providers, hosting providers, or other third parties beyond the Marketplace's reasonable control;\n(h) suspension or restriction undertaken in accordance with this Agreement, the Policies, or Applicable Law;\n(i) force majeure events; or\n(j) the Participant's own breach of this Agreement or Applicable Law.", "k": "body" }, { "t": "13.6 Indirect and Consequential Loss", "k": "h2" }, { "t": "13.6.1 To the maximum extent permitted by Applicable Law, the Marketplace shall not be liable for any indirect, incidental, special, exemplary, punitive, or consequential loss or damage, including loss of profits, revenue, business opportunities, anticipated savings, goodwill, reputation, or business interruption arising out of or relating to the Platform, Marketplace Services, or this Agreement.\n13.6.2 Nothing in this Clause shall exclude or restrict any liability that cannot lawfully be excluded or restricted.", "k": "body" }, { "t": "13.7 Liability Cap", "k": "h2" }, { "t": "13.7.1 Subject to Applicable Law, the aggregate liability of the Marketplace arising out of or relating to this Agreement, the Platform, or Marketplace Services shall not exceed the total Fees actually paid by the relevant Participant to the Marketplace during the twelve (12) months immediately preceding the event giving rise to the claim.\n13.7.2 Where the Participant has paid no Fees to the Marketplace during such period, the Marketplace's aggregate liability shall, subject to Applicable Law, be limited to the amount actually paid by the Participant to the Marketplace in connection with the specific Transaction giving rise to the claim.\n13.7.3 The limitation under this Clause shall not apply to liability that cannot legally be limited under Applicable Law.", "k": "body" }, { "t": "13.8 Participant's Duty to Mitigate", "k": "h2" }, { "t": "13.8.1 Each Participant shall take reasonable steps to mitigate any loss, damage, cost, or liability for which it seeks recovery from the other Party.\n13.8.2 A failure to take reasonable mitigation measures may be considered when determining the amount recoverable, to the extent permitted by Applicable Law.", "k": "body" }, { "t": "13.9 No Warranty of Continuous Availability", "k": "h2" }, { "t": "13.9.1 Except as expressly stated in this Agreement, the Marketplace does not warrant that the Platform or Marketplace Services will be continuously available, uninterrupted, error-free, secure, or free from defects.\n13.9.2 Temporary interruption, maintenance, technical failure, or unavailability of the Platform shall not by itself constitute a breach of this Agreement where the Marketplace has acted in accordance with its obligations and Applicable Law.", "k": "body" }, { "t": "13.10 Third-Party Services", "k": "h2" }, { "t": "13.10.1 The Marketplace may rely upon third-party service providers for payment processing, banking, Transportation, communications, hosting, technology, verification, security, and other functions.\n13.10.2 Subject to Applicable Law, the Marketplace shall not be liable for losses arising solely from the acts or omissions of such third parties where the relevant matter is outside the Marketplace's reasonable control.\n13.10.3 Nothing in this Clause shall relieve the Marketplace of responsibility for obligations expressly undertaken by it in relation to such services.", "k": "body" }, { "t": "13.11 No Guarantee of Commercial Outcome", "k": "h2" }, { "t": "13.11.1 The Marketplace does not guarantee any minimum number or value of Transactions, sales, purchases, revenue, profits, customers, suppliers, leads, or business opportunities for any Participant.\n13.11.2 A Participant's decision to enter into a Transaction or rely upon information available through the Platform shall remain its own commercial decision and responsibility.", "k": "body" }, { "t": "13.12 Basis of Allocation of Risk", "k": "h2" }, { "t": "13.12.1 The Parties acknowledge that the limitations, exclusions, indemnities, and allocation of responsibilities contained in this Agreement form an essential part of the commercial arrangement between them.\n13.12.2 The Fees and other commercial terms applicable to the Platform have been agreed taking into account the allocation of risks and responsibilities set out in this Agreement.", "k": "body" }, { "t": "13.13 No Limitation of Participant's Payment Obligations", "k": "h2" }, { "t": "13.13.1 Nothing in this Section shall limit or release the Participant from amounts properly due to the Marketplace, including Fees, commissions, charges, reimbursement obligations, indemnification amounts, recovery amounts, or other payment obligations under this Agreement.\n13.13.2 The Participant's obligation to pay amounts due shall continue notwithstanding any claim, dispute, suspension, or other proceeding, except to the extent such payment is specifically disputed or suspended under this Agreement.", "k": "body" }, { "t": "13.14 Exceptions Required by Law", "k": "h2" }, { "t": "13.14.1 Nothing in this Section shall exclude, restrict, or limit any liability, right, remedy, or obligation to the extent that doing so would be prohibited by Applicable Law.\n13.14.2 Where any limitation or exclusion contained in this Section is found to be unenforceable, it shall apply to the maximum extent permitted by Applicable Law, and the remaining provisions shall continue in full force and effect.", "k": "body" }, { "t": "13.15 Survival", "k": "h2" }, { "t": "13.15.1 The indemnification obligations, liability limitations, exclusions, payment obligations, and other provisions of this Section that by their nature are intended to survive shall continue after expiry, termination, suspension, or closure of the Account or this Agreement.", "k": "body" }, { "t": "14. TERM, SUSPENSION AND TERMINATION", "k": "h1" }, { "t": "14.1 Term", "k": "h2" }, { "t": "14.1.1 This Agreement shall commence on the Effective Date and shall continue unless terminated in accordance with this Section.\n14.1.2 The Participant's registration and right to access and use the Platform shall remain subject to continued compliance with this Agreement, the Policies, and Applicable Law.", "k": "body" }, { "t": "14.2 Suspension by Marketplace", "k": "h2" }, { "t": "14.2.1 The Marketplace may, subject to Applicable Law, immediately or temporarily suspend, restrict, limit, or disable the Participant's Account or access to all or any part of the Platform or Marketplace Services where reasonably necessary due to:\n(a) breach or suspected breach of this Agreement or any Policy;\n(b) suspected fraud, misconduct, unauthorised activity, or security risk;\n(c) inaccurate, incomplete, misleading, or unverifiable information;\n(d) payment, Settlement, or financial irregularities;\n(e) violation or suspected violation of Applicable Law;\n(f) prohibited Products or activities;\n(g) complaints, disputes, or conduct presenting material risk to another Participant or the Marketplace;\n(h) operational, technical, security, or risk-management requirements; or\n(i) any other circumstance expressly permitted under this Agreement.\n14.2.2 Suspension may apply to the entire Account or only to specific Products, Transactions, functions, payment facilities, Buyer/Seller capacity, or other Platform features.\n14.2.3 Where reasonably practicable and legally permissible, the Marketplace may notify the Participant of the reason for suspension and any corrective action required for restoration of access.", "k": "body" }, { "t": "14.3 Immediate Protective Action", "k": "h2" }, { "t": "14.3.1 The Marketplace may take immediate action without prior notice where it reasonably considers such action necessary to prevent fraud, unauthorised access, financial loss, security compromise, unlawful activity, misuse of the Platform, or harm to Participants or the Marketplace.\n14.3.2 Such action may include restricting Account access, blocking Transactions, holding Settlement, disabling payment functionality, removing Product listings, or restricting communication or other Platform functionality.\n14.3.3 Where legally permissible, the Marketplace may subsequently provide information concerning the action taken and the steps required for restoration.", "k": "body" }, { "t": "14.4 Participant's Right to Terminate", "k": "h2" }, { "t": "14.4.1 The Participant may request closure of its Account and termination of this Agreement by providing notice to the Marketplace through the designated communication channel.\n14.4.2 Account closure shall not automatically cancel or extinguish any Transaction, payment obligation, Fee, Settlement adjustment, refund, return, dispute, indemnity, or other obligation that arose before closure.\n14.4.3 The Marketplace may require completion, cancellation, settlement, or other appropriate resolution of outstanding Transactions before completing Account closure.", "k": "body" }, { "t": "14.5 Termination by Marketplace", "k": "h2" }, { "t": "14.5.1 The Marketplace may terminate this Agreement and/or the Participant's Account where:\n(a) the Participant materially breaches this Agreement or any Policy;\n(b) the Participant repeatedly breaches this Agreement or the Policies;\n(c) the Participant engages in fraud, prohibited conduct, or unlawful activity;\n(d) information provided by the Participant is materially false, misleading, fraudulent, or unverifiable;\n(e) continued access creates material legal, regulatory, security, financial, or operational risk;\n(f) the Participant becomes subject to insolvency, liquidation, dissolution, or similar proceedings, to the extent permitted by Applicable Law;\n(g) continued provision of Marketplace Services becomes unlawful or commercially impracticable; or\n(h) termination is otherwise permitted under this Agreement or Applicable Law.\n14.5.2 Where the circumstances reasonably permit, the Marketplace may provide notice and an opportunity to rectify a breach before termination.\n14.5.3 No prior notice or opportunity to cure shall be required where immediate termination is reasonably necessary to protect the Marketplace, Participants, Transaction funds, Platform security, or comply with Applicable Law.", "k": "body" }, { "t": "14.6 Effect of Suspension or Termination", "k": "h2" }, { "t": "14.6.1 Upon suspension or termination, the Participant shall immediately cease using any Platform functionality that has been suspended or terminated.\n14.6.2 Termination shall not affect rights, liabilities, claims, obligations, or remedies that accrued before the effective date of termination.\n14.6.3 The Marketplace may complete, cancel, suspend, refund, adjust, or otherwise administer outstanding Transactions in accordance with this Agreement, the Policies, and Applicable Law.\n14.6.4 The Participant shall remain responsible for all amounts due to the Marketplace and for all obligations arising from Transactions entered into before suspension or termination.", "k": "body" }, { "t": "14.7 Outstanding Payments and Settlement", "k": "h2" }, { "t": "14.7.1 Suspension or termination shall not prevent the Marketplace from holding, releasing, refunding, deducting, adjusting, or recovering Transaction funds where required to administer outstanding Transactions, disputes, refunds, reversals, Fees, or other financial obligations.\n14.7.2 Any negative Wallet balance or other amount due from the Participant shall remain payable notwithstanding suspension, termination, or Account closure.\n14.7.3 Where funds remain held in respect of an Advance Transaction, the Marketplace may process such funds in accordance with the applicable Transaction status, dispute status, refund requirements, and this Agreement.", "k": "body" }, { "t": "14.8 Outstanding Transactions", "k": "h2" }, { "t": "14.8.1 Termination shall not automatically cancel Transactions already accepted or otherwise concluded before termination.\n14.8.2 The Marketplace may determine whether outstanding Transactions should continue, be completed, cancelled, refunded, or otherwise administered based on the circumstances and applicable Transaction terms.\n14.8.3 Participants shall reasonably cooperate in completing or closing outstanding Transactions following termination.", "k": "body" }, { "t": "14.9 Re-Registration", "k": "h2" }, { "t": "14.9.1 A Participant whose Account has been suspended or terminated shall not create or use another Account for the purpose of circumventing such suspension or termination.\n14.9.2 The Marketplace may refuse or restrict any subsequent registration where it reasonably considers that the new registration is intended to circumvent a previous restriction, termination, or compliance measure.", "k": "body" }, { "t": "14.10 Data and Records After Termination", "k": "h2" }, { "t": "14.10.1 Following termination or Account closure, the Marketplace may retain Platform Records, Transaction information, payment records, communications, dispute records, and other information for the periods and purposes permitted or required under Applicable Law and this Agreement.\n14.10.2 The Participant shall not have a right to require deletion of information that the Marketplace is legally required or otherwise legitimately entitled to retain.\n14.10.3 Subject to Applicable Law, the Marketplace may restrict the Participant's access to historical Account or Transaction information following termination.", "k": "body" }, { "t": "14.11 No Liability for Permitted Suspension or Termination", "k": "h2" }, { "t": "14.11.1 Subject to Applicable Law, the Marketplace shall not be liable for losses arising solely from suspension, restriction, or termination carried out in accordance with this Agreement, the Policies, or Applicable Law.\n14.11.2 The Marketplace shall nevertheless remain responsible for obligations that cannot lawfully be excluded or for liabilities arising from its own breach to the extent required by Applicable Law.", "k": "body" }, { "t": "14.12 Reinstatement", "k": "h2" }, { "t": "14.12.1 Where an Account has been suspended, the Marketplace may, at its discretion, reinstate access after the Participant has satisfied applicable corrective, verification, payment, security, or compliance requirements.\n14.12.2 Reinstatement shall not be automatic and may be subject to additional conditions, restrictions, monitoring, or verification.\n14.12.3 The Marketplace shall not be required to reinstate an Account where termination has become final or continued access is prohibited or reasonably considered inappropriate under Applicable Law or the Marketplace's legitimate risk and compliance requirements.", "k": "body" }, { "t": "14.13 Survival", "k": "h2" }, { "t": "14.13.1 Provisions which by their nature are intended to survive termination shall continue in effect, including provisions relating to payment obligations, Settlement, recovery, confidentiality, data protection, intellectual property, indemnification, limitation of liability, dispute resolution, records, and Applicable Law.\n14.13.2 Termination shall not affect any right or remedy that accrued to either Party before termination.", "k": "body" }, { "t": "15. FORCE MAJEURE", "k": "h1" }, { "t": "15.1 Force Majeure Event", "k": "h2" }, { "t": "15.1.1 Neither Party shall be liable for any failure or delay in performing an obligation under this Agreement to the extent such failure or delay is directly caused by an event or circumstance beyond the reasonable control of the affected Party (“Force Majeure Event”).", "k": "body" }, { "t": "15.1.2 Force Majeure Events may include, without limitation:\n(a) natural disasters, including earthquake, flood, cyclone, fire, epidemic, pandemic, or other natural calamity;\n(b) war, armed conflict, terrorism, civil disturbance, riot, insurrection, or public disorder;\n(c) governmental action, orders, restrictions, embargoes, sanctions, lockdowns, or changes in Applicable Law;\n(d) strikes, labour disputes, or widespread industrial disturbances not limited to the affected Party's internal workforce;\n(e) failure or disruption of telecommunications, internet, electricity, cloud infrastructure, hosting infrastructure, banking systems, payment infrastructure, logistics networks, or other essential third-party infrastructure;\n(f) cyberattacks, widespread security incidents, or other technological disruptions not caused by the affected Party's wilful misconduct or gross negligence; or\n(g) any other event beyond the reasonable control of the affected Party that could not reasonably have been prevented or overcome.", "k": "body" }, { "t": "15.2 Effect of Force Majeure", "k": "h2" }, { "t": "15.2.1 The affected Party shall not be considered in breach of this Agreement to the extent and for the period that its performance is prevented or materially delayed by a Force Majeure Event.", "k": "body" }, { "t": "15.2.2 The affected Party shall use reasonable efforts to mitigate the effects of the Force Majeure Event and resume performance as soon as reasonably practicable.", "k": "body" }, { "t": "15.2.3 A Force Majeure Event shall not excuse obligations that arose before the occurrence of the Force Majeure Event and are capable of being performed despite the event.", "k": "body" }, { "t": "15.3 Notice", "k": "h2" }, { "t": "15.3.1 Where reasonably practicable, the affected Party shall notify the other Party of a material Force Majeure Event and its expected impact on performance.", "k": "body" }, { "t": "15.3.2 Failure to provide notice shall not itself prevent reliance on a Force Majeure Event where immediate notice was not reasonably practicable, but the affected Party shall provide notice as soon as reasonably practicable thereafter.", "k": "body" }, { "t": "15.4 Transaction-Level Impact", "k": "h2" }, { "t": "15.4.1 Where a Force Majeure Event affects an individual Transaction, the Marketplace may, having regard to the circumstances, Applicable Law, and the interests of the affected Participants, extend timelines, suspend processing, modify operational arrangements, cancel the Transaction, or otherwise administer the Transaction in accordance with this Agreement and the Policies.", "k": "body" }, { "t": "15.4.2 Neither Party shall be required to continue performance where doing so has become unlawful or objectively impossible due to a Force Majeure Event.", "k": "body" }, { "t": "15.5 Payment and Settlement During Force Majeure", "k": "h2" }, { "t": "15.5.1 A Force Majeure Event affecting banking, payment processing, Settlement, or related infrastructure may result in temporary delay in processing or Settlement.", "k": "body" }, { "t": "15.5.2 Such delay shall not extinguish or waive any underlying payment, refund, Fee, Settlement, or other financial obligation.", "k": "body" }, { "t": "15.5.3 Where Transaction funds are being held by the Marketplace in accordance with this Agreement, the Marketplace may continue to hold, release, refund, or otherwise administer such funds once the relevant conditions can reasonably be determined and processed.", "k": "body" }, { "t": "15.6 Marketplace Infrastructure and Third-Party Failures", "k": "h2" }, { "t": "15.6.1 The Marketplace shall not be responsible for interruption or delay caused by a Force Majeure Event affecting third-party infrastructure, including banks, payment systems, telecommunications providers, cloud service providers, logistics providers, or other external service providers.", "k": "body" }, { "t": "15.6.2 The Marketplace may temporarily suspend affected Platform functionality where reasonably necessary to protect Participants, Transaction funds, Platform security, or operational integrity.", "k": "body" }, { "t": "15.7 No Automatic Waiver", "k": "h2" }, { "t": "15.7.1 A Force Majeure Event shall not constitute a waiver of any right, remedy, or obligation that is not directly affected by the Force Majeure Event.", "k": "body" }, { "t": "15.7.2 The affected Party shall remain responsible for obligations that can reasonably be performed notwithstanding the Force Majeure Event.", "k": "body" }, { "t": "15.8 Prolonged Force Majeure", "k": "h2" }, { "t": "15.8.1 If a Force Majeure Event materially prevents or substantially interferes with performance of a Transaction or Marketplace Service for an extended period, the Marketplace may, subject to Applicable Law, suspend or cancel the affected Transaction or Service.", "k": "body" }, { "t": "15.8.2 Where cancellation occurs, the Marketplace may determine the appropriate treatment of Advance Payments, refunds, Settlement, Fees, and other amounts in accordance with this Agreement, the applicable Transaction terms, and Applicable Law.", "k": "body" }, { "t": "15.9 Continuing Obligations", "k": "h2" }, { "t": "15.9.1 Termination, cancellation, suspension, or delay resulting from a Force Majeure Event shall not affect rights, liabilities, or obligations accrued before the relevant event.", "k": "body" }, { "t": "15.9.2 Provisions intended by their nature to survive shall continue notwithstanding the Force Majeure Event or any resulting suspension or termination.", "k": "body" }, { "t": "16. TAXES, INVOICING AND STATUTORY COMPLIANCE", "k": "h1" }, { "t": "16.1 Taxes and Statutory Obligations", "k": "h2" }, { "t": "16.1.1 Each Participant shall be solely responsible for determining, charging, collecting, reporting, withholding, depositing, and paying all taxes, duties, levies, cess, and other statutory amounts applicable to its activities, Products, Transactions, income, or obligations under Applicable Law.", "k": "body" }, { "t": "16.1.2 Without limiting the foregoing, each Participant shall be responsible for its applicable GST, income tax, customs duties, withholding taxes, cess, and other applicable governmental or statutory obligations.", "k": "body" }, { "t": "16.2 GST Compliance", "k": "h2" }, { "t": "16.2.1 Where applicable, the Participant shall maintain valid GST registration and comply with all GST requirements relevant to its activities on the Platform.", "k": "body" }, { "t": "16.2.2 The Participant shall ensure that its GSTIN and other GST-related information provided to the Marketplace are accurate, valid, current, and belong to the Participant.", "k": "body" }, { "t": "16.2.3 The Participant shall be responsible for determining the correct GST treatment of each Transaction, including applicable tax rate, place of supply, taxability, exemptions, reverse charge, and other GST requirements.", "k": "body" }, { "t": "16.2.4 The Marketplace's display, calculation, collection, processing, or transmission of any tax-related information shall not constitute tax advice or confirmation of the Participant's tax position.", "k": "body" }, { "t": "16.3 Invoices and Tax Documents", "k": "h2" }, { "t": "16.3.1 The Seller shall issue valid and legally compliant invoices, credit notes, debit notes, delivery documents, e-invoices, e-way bills, and other statutory or commercial documents required for its Transactions.", "k": "body" }, { "t": "16.3.2 The Buyer shall provide such information as may reasonably be required for the Seller to issue legally compliant invoices or other Transaction documents.", "k": "body" }, { "t": "16.3.3 Each Participant shall verify the accuracy of invoices and other documents received from another Participant and promptly raise any material discrepancy.", "k": "body" }, { "t": "16.3.4 The Marketplace may facilitate the generation, transmission, storage, or display of invoices or other documents but shall not be responsible for the legal or tax correctness of documents issued by a Participant.", "k": "body" }, { "t": "16.4 Tax Deduction and Withholding", "k": "h2" }, { "t": "16.4.1 Where a Participant is required under Applicable Law to deduct or withhold any tax or statutory amount from a payment, such Participant shall make the deduction or withholding correctly and within the prescribed period.", "k": "body" }, { "t": "16.4.2 The Participant making any deduction or withholding shall provide the relevant certificate, statement, challan, or other evidence to the affected Participant where required by Applicable Law.", "k": "body" }, { "t": "16.4.3 The Marketplace may make or facilitate deductions, withholding, reporting, or other statutory adjustments where required by Applicable Law.", "k": "body" }, { "t": "16.5 Transaction Information", "k": "h2" }, { "t": "16.5.1 Each Participant shall provide accurate tax, billing, registration, and statutory information required for processing or recording a Transaction.", "k": "body" }, { "t": "16.5.2 The Participant shall promptly update the Marketplace regarding any material change in its GST registration, tax status, legal entity information, billing details, or other statutory information relevant to the Platform.", "k": "body" }, { "t": "16.6 Tax Invoices and Transaction Records", "k": "h2" }, { "t": "16.6.1 Participants shall maintain complete and accurate records relating to their Transactions, invoices, payments, taxes, returns, adjustments, and other statutory matters for the period required under Applicable Law.", "k": "body" }, { "t": "16.6.2 The Marketplace may maintain Platform Records relating to Transactions, payments, invoices, and other activities for operational, accounting, dispute, compliance, audit, and legal purposes.", "k": "body" }, { "t": "16.7 Tax Disputes", "k": "h2" }, { "t": "16.7.1 Any dispute between Participants concerning tax treatment, invoice validity, tax recovery, input tax credit, tax liability, or statutory compliance shall primarily be resolved between the relevant Participants.", "k": "body" }, { "t": "16.7.2 The Marketplace may provide relevant Platform Records or administrative assistance where reasonably required but shall not be responsible for determining the tax liability of either Participant except where expressly required by Applicable Law.", "k": "body" }, { "t": "16.8 Marketplace Fees and Taxes", "k": "h2" }, { "t": "16.8.1 Fees, commissions, and other amounts payable to the Marketplace may be subject to applicable taxes.", "k": "body" }, { "t": "16.8.2 The Marketplace may charge or collect applicable taxes on its Fees and Services and issue appropriate tax documentation in accordance with Applicable Law.", "k": "body" }, { "t": "16.8.3 Any taxes applicable to the Marketplace's supply of Services shall be borne and/or collected in accordance with Applicable Law.", "k": "body" }, { "t": "16.9 Tax Indemnity", "k": "h2" }, { "t": "16.9.1 The Participant shall indemnify and hold harmless the Marketplace against any tax, interest, penalty, demand, liability, cost, or expense arising from the Participant's failure to comply with its tax or statutory obligations, except to the extent directly caused by the Marketplace's own violation of Applicable Law.", "k": "body" }, { "t": "16.10 Regulatory and Statutory Cooperation", "k": "h2" }, { "t": "16.10.1 Each Participant shall reasonably cooperate with the Marketplace in relation to statutory, regulatory, tax, audit, investigation, reporting, or compliance requirements relating to the Participant's Account or Transactions.", "k": "body" }, { "t": "16.10.2 The Marketplace may provide information or records to governmental, tax, regulatory, judicial, or law-enforcement authorities where required or permitted under Applicable Law.", "k": "body" }, { "t": "16.11 No Tax Advice", "k": "h2" }, { "t": "16.11.1 Nothing in this Agreement, the Platform, Marketplace Services, invoices, Transaction records, tax displays, or communications from the Marketplace shall constitute legal, accounting, or tax advice.", "k": "body" }, { "t": "16.11.2 Each Participant remains solely responsible for obtaining independent professional advice regarding its tax and statutory obligations where required.", "k": "body" }, { "t": "16.12 Changes in Tax or Statutory Requirements", "k": "h2" }, { "t": "16.12.1 Where changes in Applicable Law affect Transactions, invoicing, taxation, payment processing, Settlement, or Marketplace Services, the Marketplace may modify relevant Platform processes, Policies, documentation requirements, or Transaction procedures to facilitate compliance.", "k": "body" }, { "t": "16.12.2 Participants shall comply with such legally required changes from the date on which they become applicable.", "k": "body" }, { "t": "17. COMPLIANCE, KYC/KYB, ANTI-FRAUD AND REGULATORY REQUIREMENTS", "k": "h1" }, { "t": "17.1 Participant Compliance", "k": "h2" }, { "t": "17.1.1 Each Participant shall comply with all Applicable Laws, regulations, governmental directions, statutory requirements, licences, registrations, approvals, permits, and industry requirements applicable to its business, Products, Transactions, and activities on the Platform.", "k": "body" }, { "t": "17.1.2 The Participant shall not use the Platform for any unlawful, fraudulent, deceptive, prohibited, or unauthorised purpose.", "k": "body" }, { "t": "17.2 Verification and Due Diligence", "k": "h2" }, { "t": "17.2.1 The Marketplace may carry out such verification, validation, screening, or due diligence of a Participant as it considers reasonably necessary for Platform operation, risk management, fraud prevention, security, or legal and regulatory compliance.", "k": "body" }, { "t": "17.2.2 Such verification may include verification of GSTIN, business information, Account information, Transaction activity, payment information, or other information available to or lawfully obtainable by the Marketplace.", "k": "body" }, { "t": "17.2.3 The Marketplace may require a Participant to provide additional information or clarification where reasonably necessary for verification, risk assessment, dispute handling, fraud prevention, or compliance with Applicable Law.", "k": "body" }, { "t": "17.3 Accuracy of Compliance Information", "k": "h2" }, { "t": "17.3.1 The Participant shall ensure that all information provided for registration, verification, Transactions, invoicing, payments, or compliance purposes is true, accurate, complete, and current.", "k": "body" }, { "t": "17.3.2 The Participant shall promptly notify the Marketplace of any material change affecting information previously provided by the Participant.", "k": "body" }, { "t": "17.4 Anti-Fraud Measures", "k": "h2" }, { "t": "17.4.1 The Marketplace may implement reasonable systems, controls, rules, and procedures to detect, prevent, investigate, and respond to suspected fraud, manipulation, unauthorised activity, misuse, or other suspicious conduct.", "k": "body" }, { "t": "17.4.2 The Marketplace may review Transaction patterns, Account activity, payment activity, communications, Product activity, and Platform Records for such purposes, subject to Applicable Law.", "k": "body" }, { "t": "17.4.3 Where suspicious activity is identified, the Marketplace may suspend or restrict an Account, Transaction, payment, Settlement, Product listing, or Platform functionality in accordance with this Agreement and Applicable Law.", "k": "body" }, { "t": "17.5 Unauthorised and Suspicious Activity", "k": "h2" }, { "t": "17.5.1 The Participant shall immediately notify the Marketplace upon becoming aware of any suspected unauthorised access, Account compromise, fraudulent Transaction, misuse of credentials, suspicious payment instruction, or other security incident involving its Account.", "k": "body" }, { "t": "17.5.2 The Participant shall reasonably cooperate with the Marketplace in investigating and resolving such activity.", "k": "body" }, { "t": "17.6 Prohibited Transactions and Activities", "k": "h2" }, { "t": "17.6.1 A Participant shall not initiate, facilitate, participate in, or attempt to complete any Transaction involving Products or activities prohibited under Applicable Law or the Policies.", "k": "body" }, { "t": "17.6.2 A Participant shall not manipulate Orders, pricing, ratings, Transaction records, payment status, delivery status, Product availability, or other Platform information for an improper purpose.", "k": "body" }, { "t": "17.6.3 A Participant shall not use another person's or entity's identity, GSTIN, Account, credentials, documents, or business information without lawful authority.", "k": "body" }, { "t": "17.7 Anti-Money Laundering and Related Requirements", "k": "h2" }, { "t": "17.7.1 Each Participant shall comply with Applicable Law relating to money laundering, proceeds of crime, fraud, sanctions, prohibited transactions, and other financial or commercial misconduct, to the extent applicable to the Participant.", "k": "body" }, { "t": "17.7.2 The Marketplace may take reasonable preventive or protective measures where it reasonably suspects that a Transaction or Account may involve unlawful funds, prohibited activity, fraud, or other regulatory risk.", "k": "body" }, { "t": "17.7.3 Nothing in this Agreement shall require the Marketplace to undertake any regulatory function that is not imposed upon it by Applicable Law.", "k": "body" }, { "t": "17.8 Sanctions and Restricted Parties", "k": "h2" }, { "t": "17.8.1 A Participant shall not use the Platform in connection with any transaction or activity prohibited by Applicable Law relating to sanctions, embargoes, restricted persons, restricted entities, or restricted jurisdictions.", "k": "body" }, { "t": "17.8.2 The Marketplace may restrict or reject a Transaction or Account where reasonably necessary to comply with Applicable Law or applicable governmental or regulatory directions.", "k": "body" }, { "t": "17.9 Regulatory Cooperation", "k": "h2" }, { "t": "17.9.1 Each Participant shall reasonably cooperate with lawful requests from the Marketplace relating to compliance, fraud investigation, security incidents, disputes, audits, or regulatory requirements.", "k": "body" }, { "t": "17.9.2 The Marketplace may disclose relevant information, Platform Records, Transaction information, or Account information to governmental, regulatory, judicial, law-enforcement, tax, or other competent authorities where required or permitted under Applicable Law.", "k": "body" }, { "t": "17.10 Audit and Investigation", "k": "h2" }, { "t": "17.10.1 The Marketplace may review Platform Records and other information available to it for the purpose of investigating suspected violations of this Agreement, Policies, Applicable Law, fraud, security incidents, or other material misconduct.", "k": "body" }, { "t": "17.10.2 The Participant shall provide reasonable cooperation and information required for such investigation, subject to Applicable Law.", "k": "body" }, { "t": "17.11 Compliance-Related Restrictions", "k": "h2" }, { "t": "17.11.1 Where reasonably necessary for compliance, security, fraud prevention, or risk management, the Marketplace may impose temporary or continuing restrictions on:\n(a) Account access;\n(b) Buyer or Seller functionality;\n(c) Product listings;\n(d) Orders or Transactions;\n(e) payment processing;\n(f) Settlement;\n(g) Wallet usage; or\n(h) other Platform functionality.", "k": "body" }, { "t": "17.11.2 Such restrictions may remain in place until the relevant concern has been resolved or the Marketplace determines that the restriction is no longer necessary, subject to Applicable Law.", "k": "body" }, { "t": "17.12 No Guarantee of Compliance Status", "k": "h2" }, { "t": "17.12.1 Verification, approval, registration, or continued access to the Platform shall not constitute a certification by the Marketplace that a Participant is compliant with all Applicable Laws or that any Product or Transaction is legally permissible.", "k": "body" }, { "t": "17.12.2 Each Participant remains independently responsible for its own legal, regulatory, tax, licensing, product, and business compliance.", "k": "body" }, { "t": "17.13 Participant Responsibility", "k": "h2" }, { "t": "17.13.1 Each Participant shall be responsible for ensuring that its employees, representatives, agents, contractors, Account users, and other persons acting on its behalf comply with this Agreement and Applicable Law.", "k": "body" }, { "t": "17.13.2 Any breach by such persons that occurs in connection with the Participant's Account or activities may be treated as a breach by the Participant.", "k": "body" }, { "t": "17.14 Consequences of Non-Compliance", "k": "h2" }, { "t": "17.14.1 Without prejudice to any other rights under this Agreement, the Marketplace may take appropriate action where a Participant fails to comply with this Section.", "k": "body" }, { "t": "17.14.2 Such action may include warning, restriction, suspension, cancellation, removal of Products, withholding or adjustment of Settlement, termination of the Account, recovery of amounts due, or other measures permitted under this Agreement or Applicable Law.", "k": "body" }, { "t": "17.14.3 The Marketplace's exercise or non-exercise of any compliance measure in one instance shall not prevent it from taking action in another instance.", "k": "body" }, { "t": "17.15 Continuing Compliance", "k": "h2" }, { "t": "17.15.1 The Participant's obligations under this Section shall continue throughout the period in which the Participant has an Account, accesses the Platform, or has outstanding Transactions or obligations under this Agreement.", "k": "body" }, { "t": "17.15.2 Obligations relating to Transactions, records, investigations, payments, statutory compliance, and other matters arising before termination shall survive termination to the extent necessary to give them effect.", "k": "body" }, { "t": "18. REPRESENTATIONS, WARRANTIES AND UNDERTAKINGS", "k": "h1" }, { "t": "18.1 Participant Representations", "k": "h2" }, { "t": "18.1.1 The Participant represents and warrants that:\n(a) it is duly constituted, validly existing, and authorised to conduct its business, where applicable;\n(b) it has full legal capacity and authority to enter into and perform this Agreement;\n(c) the person accepting this Agreement on its behalf is duly authorised to do so;\n(d) all information provided to the Marketplace is true, accurate, complete, and current;\n(e) its GSTIN and other registration details provided to the Marketplace, where applicable, are valid and belong to the Participant;\n(f) its participation in the Platform and its Transactions do not violate any Applicable Law or contractual obligation binding upon it;\n(g) it has all licences, registrations, approvals, permissions, and authorisations required for its business and Products;\n(h) it has the legal right and authority to sell Products when acting as Seller and to purchase Products when acting as Buyer;\n(i) Products offered, sold, supplied, or purchased by it comply with Applicable Law and applicable contractual requirements; and\n(j) it shall not use the Platform for any fraudulent, unlawful, misleading, or unauthorised purpose.", "k": "body" }, { "t": "18.2 Seller Representations", "k": "h2" }, { "t": "18.2.1 When acting as Seller, the Participant represents and warrants that:\n(a) it has good and marketable title to the Products or otherwise has lawful authority to sell and supply them;\n(b) the Products conform to the description, specifications, quantity, quality, grade, condition, and other representations provided to the Buyer;\n(c) the Products are not counterfeit, unlawfully sourced, adulterated, misrepresented, or otherwise prohibited;\n(d) the Products are appropriately packaged, labelled, stored, handled, and transported as required under Applicable Law and the applicable Transaction;\n(e) all invoices, tax documents, Product documents, certificates, declarations, and other information supplied by it are accurate and authentic; and\n(f) it shall fulfil accepted Orders in accordance with the applicable Transaction terms.", "k": "body" }, { "t": "18.3 Buyer Representations", "k": "h2" }, { "t": "18.3.1 When acting as Buyer, the Participant represents and warrants that:\n(a) it is purchasing Products for lawful business purposes;\n(b) it has authority to place Orders, issue POs, make payments, and otherwise bind itself in connection with Transactions;\n(c) information provided to the Seller or Marketplace for a Transaction is accurate and complete;\n(d) it shall make payments in accordance with agreed payment terms; and\n(e) it shall not misuse, reject, dispute, or reverse a Transaction or payment dishonestly or without a legitimate basis.", "k": "body" }, { "t": "18.4 Authority of Representatives", "k": "h2" }, { "t": "18.4.1 The Participant shall ensure that its employees, representatives, agents, contractors, and other authorised users have appropriate authority to access the Platform and undertake activities on its behalf.", "k": "body" }, { "t": "18.4.2 The Participant shall be responsible for Orders, POs, SOs, Quotations, payment instructions, communications, confirmations, and other actions undertaken through its Account by persons authorised or permitted by it.", "k": "body" }, { "t": "18.5 Accuracy of Representations", "k": "h2" }, { "t": "18.5.1 The Participant shall immediately notify the Marketplace if any representation, information, registration detail, or other material information previously provided becomes materially inaccurate, incomplete, invalid, or misleading.", "k": "body" }, { "t": "18.5.2 The Marketplace may suspend or restrict the relevant Account, Transaction, Product, payment, or Settlement where reasonably necessary until the matter is clarified or corrected.", "k": "body" }, { "t": "18.6 No Reliance on Marketplace Verification", "k": "h2" }, { "t": "18.6.1 The Participant acknowledges that registration, GST verification, Account approval, Product listing, Transaction facilitation, or other Marketplace processes do not constitute a representation, warranty, certification, endorsement, or guarantee by the Marketplace regarding the Participant, another Participant, any Product, or any Transaction.", "k": "body" }, { "t": "18.7 Participant's Continuing Undertakings", "k": "h2" }, { "t": "18.7.1 The Participant undertakes throughout the term of this Agreement to:\n(a) maintain the accuracy of information provided to the Marketplace;\n(b) comply with Applicable Law and the Policies;\n(c) maintain all registrations, licences, approvals, and permissions required for its activities;\n(d) perform its Transaction obligations in good faith;\n(e) cooperate reasonably with the Marketplace in relation to disputes, investigations, compliance matters, and security issues; and\n(f) promptly address any material breach of its representations, warranties, or undertakings.", "k": "body" }, { "t": "18.8 No Unauthorised Representation", "k": "h2" }, { "t": "18.8.1 The Participant shall not represent that it is an employee, agent, partner, representative, franchisee, or authorised representative of the Marketplace unless expressly authorised in writing.", "k": "body" }, { "t": "18.8.2 The Participant shall not make any representation, commitment, guarantee, or undertaking on behalf of the Marketplace to another Participant or third party without prior written authorisation.", "k": "body" }, { "t": "18.9 Consequences of Breach", "k": "h2" }, { "t": "18.9.1 A material breach of any representation, warranty, or undertaking under this Section may constitute a breach of this Agreement and may entitle the Marketplace to exercise the rights and remedies available under this Agreement, the Policies, and Applicable Law.", "k": "body" }, { "t": "18.9.2 The Participant shall remain responsible for any loss, liability, claim, penalty, cost, or expense arising from a false, misleading, or materially inaccurate representation or warranty made by it, subject to the applicable provisions of this Agreement.", "k": "body" }, { "t": "18.10 Survival", "k": "h2" }, { "t": "18.10.1 Representations, warranties, and undertakings which by their nature relate to Transactions, payments, Products, statutory obligations, intellectual property, confidentiality, indemnification, disputes, or other matters arising before termination shall survive termination to the extent necessary to give effect to the rights and obligations of the Parties.", "k": "body" }, { "t": "19. COMMUNICATIONS, NOTICES AND ELECTRONIC RECORDS", "k": "h1" }, { "t": "19.1 Electronic Communications", "k": "h2" }, { "t": "19.1.1 The Participant agrees that the Marketplace may communicate with the Participant electronically through the Platform, verified email address, registered mobile number, SMS, messaging services, notifications, or other communication channels made available by the Marketplace.", "k": "body" }, { "t": "19.1.2 Electronic communications may include Account-related information, Orders, Quotations, Transactions, payment and Settlement information, Policy updates, dispute communications, compliance notices, security alerts, and other operational communications.", "k": "body" }, { "t": "19.2 Official Communication Details", "k": "h2" }, { "t": "19.2.1 The verified email address and mobile number associated with the Participant's Account shall be treated as the Participant's official communication details for purposes of this Agreement and Platform activities.", "k": "body" }, { "t": "19.2.2 The Participant shall ensure that such communication details remain accurate, active, accessible, and under its control.", "k": "body" }, { "t": "19.2.3 The Participant shall promptly update its communication details through the prescribed Platform process if they change.", "k": "body" }, { "t": "19.3 Notices by Marketplace", "k": "h2" }, { "t": "19.3.1 The Marketplace may provide notices to the Participant by:\n(a) posting the notice on the Platform;\n(b) sending it to the Participant's verified email address;\n(c) sending it to the Participant's verified mobile number;\n(d) displaying it through the Participant's Account or dashboard; or\n(e) using any other communication method reasonably adopted by the Marketplace.", "k": "body" }, { "t": "19.3.2 A notice shall be considered properly communicated when delivered or made available through any permitted communication method, subject to Applicable Law.", "k": "body" }, { "t": "19.4 Notices by Participant", "k": "h2" }, { "t": "19.4.1 The Participant shall send notices or formal communications to the Marketplace through the official contact details or communication channels designated by the Marketplace from time to time.", "k": "body" }, { "t": "19.4.2 Communications sent through unofficial channels or to unauthorised persons shall not be considered valid notice to the Marketplace unless expressly acknowledged by the Marketplace.", "k": "body" }, { "t": "19.5 Electronic Records", "k": "h2" }, { "t": "19.5.1 The Participant agrees that Orders, POs, SOs, Quotations, confirmations, payment records, Settlement records, communications, notifications, Account activity, and other electronic records generated, submitted, stored, or maintained through the Platform may constitute records of the relevant activity.", "k": "body" }, { "t": "19.5.2 Subject to Applicable Law, electronic records maintained by the Marketplace may be relied upon as evidence of the relevant communication, instruction, activity, or Transaction.", "k": "body" }, { "t": "19.6 Electronic Acceptance and Instructions", "k": "h2" }, { "t": "19.6.1 Clicking, selecting, confirming, submitting, accepting, approving, authorising, or otherwise electronically indicating consent through the Platform may constitute a valid electronic act or instruction by the Participant.", "k": "body" }, { "t": "19.6.2 The Participant shall be responsible for ensuring that persons using its Account have appropriate authority to provide such instructions.", "k": "body" }, { "t": "19.7 Delivery of Communications", "k": "h2" }, { "t": "19.7.1 The Participant acknowledges that electronic communications may be delayed, blocked, filtered, or otherwise affected by internet connectivity, telecommunications networks, email providers, device settings, or other third-party infrastructure.", "k": "body" }, { "t": "19.7.2 The Marketplace shall not be responsible for failure to receive a communication where the Marketplace has sent or made the communication available through the applicable communication channel and the failure is attributable to circumstances outside the Marketplace's reasonable control.", "k": "body" }, { "t": "19.8 Participant's Duty to Monitor", "k": "h2" }, { "t": "19.8.1 The Participant shall regularly monitor its Account, verified email address, registered mobile number, Platform notifications, Orders, Transactions, payment information, Settlement information, and other relevant communications.", "k": "body" }, { "t": "19.8.2 Failure by the Participant to review a communication, notification, Order, Transaction record, or other information shall not by itself invalidate an action that was otherwise validly communicated or recorded in accordance with this Agreement.", "k": "body" }, { "t": "19.9 Changes to Communication Details", "k": "h2" }, { "t": "19.9.1 The Participant shall promptly notify the Marketplace of any change in its authorised representative, email address, mobile number, billing details, or other information relevant to official communications.", "k": "body" }, { "t": "19.9.2 Until such change is successfully updated in the Platform records, the Marketplace may rely on the previously recorded communication details.", "k": "body" }, { "t": "19.10 Records of Communications", "k": "h2" }, { "t": "19.10.1 The Marketplace may retain records of communications, notifications, instructions, confirmations, and other electronic interactions for operational, contractual, dispute-resolution, security, compliance, accounting, audit, and legal purposes.", "k": "body" }, { "t": "19.10.2 Such records may be used in accordance with this Agreement, the Policies, and Applicable Law.", "k": "body" }, { "t": "19.11 Language and Interpretation", "k": "h2" }, { "t": "19.11.1 The Marketplace may provide Platform communications, notices, Policies, and other information in English or such other languages as the Marketplace may make available.", "k": "body" }, { "t": "19.11.2 Where multiple versions of a communication are provided, the Marketplace may specify the version that shall govern in the event of any inconsistency, subject to Applicable Law.", "k": "body" }, { "t": "19.12 Emergency and Security Communications", "k": "h2" }, { "t": "19.12.1 The Marketplace may send urgent communications concerning Account security, suspected fraud, payment issues, Transaction risks, Platform disruptions, or other matters requiring immediate attention.", "k": "body" }, { "t": "19.12.2 The Participant shall reasonably cooperate with and act upon such communications where necessary to protect its Account, Transactions, or other Participants.", "k": "body" }, { "t": "19.13 Legal Notices", "k": "h2" }, { "t": "19.13.1 Any notice required to be given under this Agreement shall be provided through the communication method specified in this Section unless this Agreement expressly provides otherwise.", "k": "body" }, { "t": "19.13.2 Nothing in this Section shall prevent either Party from providing notice in any additional manner required by Applicable Law.", "k": "body" }, { "t": "20. GENERAL RELATIONSHIP BETWEEN THE PARTIES", "k": "h1" }, { "t": "20.1 Independent Parties", "k": "h2" }, { "t": "20.1.1 The Parties are independent contracting parties. Nothing in this Agreement shall be construed as creating any partnership, joint venture, agency, employment, franchise, fiduciary, or other similar relationship between the Marketplace and the Participant.", "k": "body" }, { "t": "20.1.2 The Participant shall remain solely responsible for its business, employees, representatives, agents, contractors, Products, Transactions, customers, suppliers, tax obligations, statutory compliance, and commercial decisions.", "k": "body" }, { "t": "20.2 Marketplace Does Not Act as Buyer or Seller", "k": "h2" }, { "t": "20.2.1 Except where expressly agreed in writing for a specific Transaction, the Marketplace does not purchase, own, resell, manufacture, supply, or take title to Products traded between Participants.", "k": "body" }, { "t": "20.2.2 The Marketplace's facilitation of a Transaction, including providing Platform functionality, communication, payment facilitation, Settlement administration, logistics facilitation, or dispute assistance, shall not make the Marketplace a Buyer or Seller in that Transaction.", "k": "body" }, { "t": "20.3 No Authority to Bind Marketplace", "k": "h2" }, { "t": "20.3.1 The Participant shall not have authority to enter into any agreement, incur any liability, make any representation, or otherwise bind the Marketplace without the Marketplace's prior express written authorisation.", "k": "body" }, { "t": "20.3.2 No communication, representation, quotation, commitment, or undertaking made by the Participant to another person shall create any obligation on behalf of the Marketplace unless expressly authorised by the Marketplace.", "k": "body" }, { "t": "20.4 No Employment Relationship", "k": "h2" }, { "t": "20.4.1 Nothing in this Agreement creates an employment, principal-agent, or employer-employee relationship between the Marketplace and the Participant or any of the Participant's personnel.", "k": "body" }, { "t": "20.4.2 The Participant shall be solely responsible for the employment, remuneration, benefits, taxes, insurance, statutory contributions, and other obligations relating to its personnel.", "k": "body" }, { "t": "20.5 Participant's Commercial Independence", "k": "h2" }, { "t": "20.5.1 Each Participant independently determines its commercial activities, including Products offered or purchased, pricing, quantities, credit arrangements, business relationships, and Transaction decisions, subject to the Agreement, Policies, and Applicable Law.", "k": "body" }, { "t": "20.5.2 The Marketplace does not guarantee that participation in the Platform will result in any minimum number or value of Orders, Transactions, customers, suppliers, revenue, profit, or other commercial outcome.", "k": "body" }, { "t": "20.6 Dealings Between Participants", "k": "h2" }, { "t": "20.6.1 Transactions between Participants are commercial arrangements between the relevant Buyer and Seller.", "k": "body" }, { "t": "20.6.2 Each Participant shall independently assess the identity, authority, capability, creditworthiness, Products, pricing, commercial terms, and other risks associated with another Participant before entering into a Transaction, except to the extent information is expressly verified or represented by the Marketplace.", "k": "body" }, { "t": "20.7 No Fiduciary Duty", "k": "h2" }, { "t": "20.7.1 Nothing in this Agreement creates a fiduciary duty or similar special relationship between the Marketplace and any Participant.", "k": "body" }, { "t": "20.7.2 The Marketplace may exercise its contractual rights, administrative functions, risk controls, and commercial discretion in accordance with this Agreement without assuming fiduciary responsibility toward any Participant.", "k": "body" }, { "t": "20.8 Third-Party Service Providers", "k": "h2" }, { "t": "20.8.1 The Marketplace may engage employees, affiliates, contractors, technology providers, payment service providers, logistics providers, professional advisers, and other third parties to provide or support Marketplace Services.", "k": "body" }, { "t": "20.8.2 Engagement of any such third party shall not alter the independent commercial relationship between the Marketplace and the Participant.", "k": "body" }, { "t": "20.9 No Exclusivity", "k": "h2" }, { "t": "20.9.1 Unless expressly agreed otherwise in writing, neither Party is required to deal exclusively with the other.", "k": "body" }, { "t": "20.9.2 The Participant may conduct business outside the Platform, subject to the anti-circumvention, confidentiality, intellectual property, and other obligations contained in this Agreement.", "k": "body" }, { "t": "20.10 No Minimum Commitment", "k": "h2" }, { "t": "20.10.1 Unless expressly agreed in applicable Commercial Terms, the Marketplace does not guarantee any minimum Transaction volume, Product availability, sales opportunity, purchase opportunity, revenue, or other business opportunity to a Participant.", "k": "body" }, { "t": "20.10.2 The Participant is not required to enter into any Transaction merely because it has registered on or uses the Platform, except for obligations arising from Transactions already accepted or otherwise concluded.", "k": "body" }, { "t": "20.11 No Waiver of Contractual Rights", "k": "h2" }, { "t": "20.11.1 The Marketplace's assistance, intervention, communication, or administrative action in relation to a Transaction shall not constitute an assumption of the commercial obligations of the Buyer or Seller.", "k": "body" }, { "t": "20.11.2 Any action taken by the Marketplace to facilitate a resolution or protect a Participant shall not constitute a waiver of any right or remedy available to the Marketplace under this Agreement.", "k": "body" }, { "t": "20.12 Continuing Effect", "k": "h2" }, { "t": "20.12.1 The relationship principles set out in this Section shall apply to all activities undertaken through the Platform and shall continue to the extent necessary after termination to give effect to rights and obligations accrued before termination.", "k": "body" }, { "t": "21. ASSIGNMENT, SUBCONTRACTING AND DELEGATION", "k": "h1" }, { "t": "21.1 Assignment by Participant", "k": "h2" }, { "t": "21.1.1 The Participant shall not assign, transfer, novate, delegate, subcontract, or otherwise dispose of any of its rights or obligations under this Agreement, whether in whole or in part, without the Marketplace's prior written consent.", "k": "body" }, { "t": "21.1.2 Any attempted assignment, transfer, or delegation in violation of this Section shall have no effect to the extent permitted by Applicable Law.", "k": "body" }, { "t": "21.2 Permitted Internal Arrangements", "k": "h2" }, { "t": "21.2.1 The Participant may engage its employees, representatives, agents, contractors, or service providers to perform its obligations, provided that the Participant remains fully responsible for their acts and omissions.", "k": "body" }, { "t": "21.2.2 Such delegation shall not release the Participant from any obligation, liability, representation, warranty, or undertaking under this Agreement.", "k": "body" }, { "t": "21.3 Assignment by Marketplace", "k": "h2" }, { "t": "21.3.1 The Marketplace may assign, transfer, novate, or otherwise deal with this Agreement or any of its rights or obligations to:\n(a) an affiliate or group company;\n(b) a successor entity;\n(c) an entity acquiring all or substantially all of the relevant business or assets of the Marketplace;\n(d) a successor to the Platform or Marketplace Services; or\n(e) any other person or entity where reasonably required for corporate restructuring, merger, acquisition, financing, business transfer, or operational purposes.", "k": "body" }, { "t": "21.3.2 The Marketplace may also appoint or engage third-party service providers, contractors, agents, or other persons to perform or support any part of the Marketplace Services without requiring the Participant's consent.", "k": "body" }, { "t": "21.4 Subcontracting by Marketplace", "k": "h2" }, { "t": "21.4.1 The Marketplace may subcontract or delegate operational, technical, administrative, payment facilitation, logistics facilitation, customer support, verification, data processing, or other functions to third-party service providers.", "k": "body" }, { "t": "21.4.2 Such subcontracting shall not relieve the Marketplace of obligations that it is required to perform under this Agreement or Applicable Law.", "k": "body" }, { "t": "21.5 Change in Control of Participant", "k": "h2" }, { "t": "21.5.1 Where a change in ownership, control, constitution, legal status, or management of the Participant materially affects its ability to perform this Agreement, the Participant shall promptly notify the Marketplace.", "k": "body" }, { "t": "21.5.2 The Marketplace may require the Participant to complete such verification, Account update, GST verification, or other compliance process as may reasonably be necessary following such change.", "k": "body" }, { "t": "21.6 Continuing Liability", "k": "h2" }, { "t": "21.6.1 Unless expressly released in writing by the Marketplace, the Participant shall remain responsible for all obligations and liabilities arising before or in connection with any permitted delegation, subcontracting, restructuring, or change in control.", "k": "body" }, { "t": "21.7 No Third-Party Rights", "k": "h2" }, { "t": "21.7.1 Except as expressly provided in this Agreement, no person who is not a Party to this Agreement shall have any right to enforce any provision of this Agreement.", "k": "body" }, { "t": "21.7.2 The rights of the Marketplace's directors, officers, employees, affiliates, contractors, service providers, and permitted assigns under the indemnification and liability provisions shall be subject to the terms of this Agreement.", "k": "body" }, { "t": "22. AMENDMENTS, POLICIES AND CHANGES TO THE AGREEMENT", "k": "h1" }, { "t": "22.1 Right to Amend", "k": "h2" }, { "t": "22.1.1 The Marketplace may amend, modify, update, supplement, or replace this Agreement, the Policies, operational procedures, or other Platform terms from time to time, subject to Applicable Law.", "k": "body" }, { "t": "22.1.2 Amendments may be made to reflect changes in the Platform, Marketplace Services, business practices, technology, security requirements, commercial arrangements, regulatory requirements, or Applicable Law.", "k": "body" }, { "t": "22.2 Notice of Material Changes", "k": "h2" }, { "t": "22.2.1 Where reasonably required, the Marketplace shall provide notice of material amendments through the Platform, verified email address, registered mobile number, or other official communication channel.", "k": "body" }, { "t": "22.2.2 The notice may specify the effective date of the amendment and any action required from the Participant.", "k": "body" }, { "t": "22.3 Acceptance of Amendments", "k": "h2" }, { "t": "22.3.1 Unless otherwise specified by the Marketplace or required by Applicable Law, continued access to or use of the Platform after the effective date of an amendment shall constitute acceptance of the amended Agreement or Policy.", "k": "body" }, { "t": "22.3.2 Where Applicable Law requires affirmative acceptance, the Participant shall provide such acceptance through the method prescribed by the Marketplace.", "k": "body" }, { "t": "22.4 Participant's Responsibility to Review", "k": "h2" }, { "t": "22.4.1 The Participant shall periodically review the Agreement, Policies, and other applicable Platform terms made available by the Marketplace.", "k": "body" }, { "t": "22.4.2 The Participant shall remain responsible for complying with the version applicable to its activities and Transactions.", "k": "body" }, { "t": "22.5 Policy Changes", "k": "h2" }, { "t": "22.5.1 The Marketplace may introduce, modify, suspend, or withdraw Policies, procedures, guidelines, operating requirements, Product restrictions, Transaction rules, payment procedures, Settlement procedures, security requirements, or other operational requirements.", "k": "body" }, { "t": "22.5.2 Such Policies shall form part of the contractual framework governing use of the Platform to the extent expressly incorporated into this Agreement or applicable to the relevant activity.", "k": "body" }, { "t": "22.6 Transaction-Specific Terms", "k": "h2" }, { "t": "22.6.1 Changes to general Platform terms shall not automatically modify commercial terms of a Transaction that has already been concluded, unless:\n(a) the relevant Transaction terms expressly permit such change;\n(b) the Parties mutually agree to the change;\n(c) the change is necessary to comply with Applicable Law; or\n(d) the change is necessary to address fraud, security, operational, or other circumstances expressly permitted under this Agreement.", "k": "body" }, { "t": "22.7 No Retroactive Modification", "k": "h2" }, { "t": "22.7.1 Except where required by Applicable Law or expressly permitted under this Agreement, an amendment shall not retrospectively alter rights or obligations that have already accrued before its effective date.", "k": "body" }, { "t": "22.8 Inconsistency", "k": "h2" }, { "t": "22.8.1 In the event of inconsistency between this Agreement and a Policy, this Agreement shall prevail unless this Agreement expressly provides that the relevant Policy or Commercial Terms shall prevail for the particular matter.", "k": "body" }, { "t": "22.8.2 In the event of inconsistency between general Platform terms and a Transaction-specific commercial agreement expressly accepted by the relevant Participants, the Transaction-specific terms shall govern that Transaction to the extent expressly stated and legally permissible.", "k": "body" }, { "t": "22.9 Changes Required by Law", "k": "h2" }, { "t": "22.9.1 Where an amendment is required to comply with Applicable Law, governmental direction, regulatory requirement, court order, or other binding legal requirement, the Marketplace may implement such amendment with immediate or such other effect as may be legally required.", "k": "body" }, { "t": "22.10 Invalid or Unenforceable Amendments", "k": "h2" }, { "t": "22.10.1 If any amendment or provision is determined to be invalid or unenforceable, the remaining provisions of this Agreement shall continue in accordance with Section 25 relating to severability, to the extent permitted by Applicable Law.", "k": "body" }, { "t": "22.11 Version and Effective Date", "k": "h2" }, { "t": "22.11.1 The Marketplace may maintain electronic versions of this Agreement and the Policies identifying the applicable version and effective date.", "k": "body" }, { "t": "22.11.2 The version applicable to a particular activity or Transaction shall be determined by the effective date and other applicable records maintained by the Marketplace, subject to Applicable Law. 23. GOVERNING LAW AND JURISDICTION", "k": "body" }, { "t": "23.1 Governing Law", "k": "h2" }, { "t": "23.1.1 This Agreement, and the rights and obligations of the Parties arising out of or in connection with this Agreement, shall be governed by and construed in accordance with the laws of India.", "k": "body" }, { "t": "23.1.2 The application of any conflict-of-law principles that would require the application of the laws of another jurisdiction is excluded to the extent permitted by Applicable Law.", "k": "body" }, { "t": "23.2 Jurisdiction", "k": "h2" }, { "t": "23.2.1 Subject to the dispute resolution provisions of this Agreement, the courts and competent authorities having jurisdiction at Rajkot, Gujarat, India shall have exclusive jurisdiction over disputes, proceedings, claims, or matters arising out of or in connection with this Agreement or the Participant's use of the Platform, to the extent permitted by Applicable Law.", "k": "body" }, { "t": "23.2.2 The Participant irrevocably submits to such jurisdiction for such purposes.", "k": "h2" }, { "t": "23.3 Urgent and Interim Relief", "k": "h2" }, { "t": "23.3.1 Nothing in this Section shall prevent either Party from seeking urgent, interim, injunctive, protective, or conservatory relief from a court or competent authority having jurisdiction, where such relief is necessary to protect its rights or interests pending resolution of a dispute.", "k": "body" }, { "t": "23.4 Regulatory and Statutory Proceedings", "k": "h2" }, { "t": "23.4.1 Nothing in this Agreement shall restrict or prevent any governmental, regulatory, tax, judicial, or statutory authority from exercising any jurisdiction, power, or authority available to it under Applicable Law.", "k": "body" }, { "t": "23.5 Continued Effect", "k": "h2" }, { "t": "23.5.1 The governing law and jurisdiction provisions of this Section shall survive termination or expiry of this Agreement to the extent necessary to determine the rights and obligations of the Parties arising from the Agreement.", "k": "body" }, { "t": "24. DISPUTE RESOLUTION AND ARBITRATION", "k": "h1" }, { "t": "24.1 Good-Faith Resolution", "k": "h2" }, { "t": "24.1.1 The Parties shall, to the extent reasonably practicable, attempt to resolve any dispute, claim, difference, or controversy arising out of or in connection with this Agreement through good-faith discussions before commencing formal legal proceedings.", "k": "body" }, { "t": "24.1.2 This requirement shall not prevent either Party from seeking urgent or interim relief where such relief is reasonably necessary.", "k": "body" }, { "t": "24.2 Disputes Covered", "k": "h2" }, { "t": "24.2.1 This Section shall apply to disputes between the Marketplace and the Participant arising out of or relating to this Agreement, the Participant's Account, Marketplace Services, Fees, payment or Settlement matters, suspension or termination, or any other matter concerning the contractual relationship between the Parties.", "k": "body" }, { "t": "24.2.2 Transaction-level disputes between Participants shall be dealt with in accordance with Section 10 and shall not be treated as disputes between the Marketplace and Participant merely because the Marketplace has facilitated or administratively reviewed such dispute.", "k": "body" }, { "t": "24.3 Notice of Dispute", "k": "h2" }, { "t": "24.3.1 A Party seeking formal resolution of a dispute shall provide written notice to the other Party describing, in reasonable detail, the nature of the dispute, relevant facts, and relief sought.", "k": "body" }, { "t": "24.3.2 The Parties shall use reasonable efforts to resolve the dispute within 30 days from receipt of the notice, unless the Parties agree otherwise.", "k": "body" }, { "t": "24.4 Arbitration", "k": "h2" }, { "t": "24.4.1 Subject to Applicable Law, any dispute between the Marketplace and the Participant that is not resolved under Section 24.3 shall be referred to and finally resolved by arbitration in accordance with the Arbitration and Conciliation Act, 1996, as amended from time to time.", "k": "body" }, { "t": "24.4.2 The arbitration shall be conducted by a sole arbitrator mutually appointed by the Parties.", "k": "h2" }, { "t": "24.4.3 If the Parties are unable to mutually agree upon or appoint the sole arbitrator within the period prescribed under Applicable Law, the arbitrator shall be appointed in accordance with the Arbitration and Conciliation Act, 1996.", "k": "body" }, { "t": "24.5 Seat and Venue of Arbitration", "k": "h2" }, { "t": "24.5.1 The seat of arbitration shall be Rajkot, Gujarat, India.", "k": "h2" }, { "t": "24.5.2 The arbitration proceedings may be conducted physically, virtually, or in such other manner as may be determined by the arbitrator, subject to Applicable Law.", "k": "body" }, { "t": "24.6 Language", "k": "h2" }, { "t": "24.6.1 The arbitration proceedings shall be conducted in English, unless the Parties and the arbitrator agree otherwise.", "k": "body" }, { "t": "24.7 Costs", "k": "h2" }, { "t": "24.7.1 The arbitrator shall have the authority to determine the allocation of arbitration costs, fees, and reasonable expenses between the Parties in accordance with Applicable Law and the circumstances of the dispute.", "k": "body" }, { "t": "24.8 Interim and Protective Relief", "k": "h2" }, { "t": "24.8.1 Nothing in this Agreement shall prevent either Party from seeking interim, emergency, injunctive, protective, or conservatory relief from a competent court or tribunal where such relief is necessary to protect its rights, assets, confidential information, intellectual property, Transaction funds, Platform security, or other legitimate interests.", "k": "body" }, { "t": "24.9 Continued Performance", "k": "h2" }, { "t": "24.9.1 Unless prohibited by Applicable Law or otherwise determined by the competent authority or arbitrator, the existence of a dispute shall not automatically suspend obligations that are capable of being performed pending resolution of the dispute.", "k": "body" }, { "t": "24.9.2 The Participant shall continue to pay undisputed amounts and perform undisputed obligations while a dispute is pending.", "k": "body" }, { "t": "24.10 Finality of Award", "k": "h2" }, { "t": "24.10.1 Subject to Applicable Law, the arbitral award shall be final and binding upon the Parties.", "k": "h2" }, { "t": "24.10.2 Judgment upon the arbitral award may be entered and enforced before any court having jurisdiction.", "k": "body" }, { "t": "24.11 Disputes Not Subject to Arbitration", "k": "h2" }, { "t": "24.11.1 Nothing in this Section shall require arbitration of any matter that cannot legally be referred to arbitration under Applicable Law.", "k": "body" }, { "t": "24.11.2 Any such matter shall be dealt with by the competent court, tribunal, governmental authority, or regulatory authority having jurisdiction.", "k": "body" }, { "t": "24.12 Survival", "k": "h2" }, { "t": "24.12.1 This Section shall survive termination or expiry of this Agreement to the extent necessary to resolve any dispute arising from events, Transactions, obligations, or rights occurring before or in connection with such termination or expiry.", "k": "body" }, { "t": "25. MISCELLANEOUS AND GENERAL PROVISIONS", "k": "h1" }, { "t": "25.1 Entire Agreement", "k": "h2" }, { "t": "25.1.1 This Agreement, together with the applicable Policies, Commercial Terms, and other documents expressly incorporated into it, constitutes the entire agreement between the Parties concerning the Participant's registration and use of the Platform and supersedes all prior discussions, communications, understandings, representations, or arrangements relating to the same subject matter.", "k": "body" }, { "t": "25.1.2 Any additional terms applicable to a particular Transaction shall apply only to that Transaction to the extent expressly agreed or incorporated.", "k": "body" }, { "t": "25.2 Severability", "k": "h2" }, { "t": "25.2.1 If any provision of this Agreement is determined by a competent court, tribunal, or authority to be invalid, illegal, or unenforceable, that provision shall, to the extent necessary, be modified or limited to the minimum extent required to make it enforceable.", "k": "body" }, { "t": "25.2.2 If such modification is not possible, the affected provision shall be severed, and the remaining provisions shall continue in full force and effect to the extent permitted by Applicable Law.", "k": "body" }, { "t": "25.3 Waiver", "k": "h2" }, { "t": "25.3.1 No failure, delay, or omission by either Party in exercising any right, power, or remedy under this Agreement shall operate as a waiver of that right, power, or remedy.", "k": "body" }, { "t": "25.3.2 Any waiver shall be effective only if expressly made by the Party entitled to the relevant right and shall apply only to the specific circumstance for which it is given.", "k": "body" }, { "t": "25.4 Cumulative Remedies", "k": "h2" }, { "t": "25.4.1 The rights and remedies available to either Party under this Agreement are cumulative and are not exclusive of any rights or remedies available under Applicable Law, unless expressly stated otherwise.", "k": "body" }, { "t": "25.5 Further Assurances", "k": "h2" }, { "t": "25.5.1 Each Party shall, where reasonably necessary, execute or provide such additional documents, information, confirmations, or cooperation as may reasonably be required to give effect to this Agreement and the Transactions contemplated by it.", "k": "body" }, { "t": "25.6 No Third-Party Beneficiary", "k": "h2" }, { "t": "25.6.1 Except as expressly provided in this Agreement, this Agreement is entered into solely for the benefit of the Parties and does not create any enforceable right in favour of any third party.", "k": "body" }, { "t": "25.7 Counterparts and Electronic Execution", "k": "h2" }, { "t": "25.7.1 This Agreement may be executed in counterparts, each of which shall be deemed an original and all of which together shall constitute one instrument.", "k": "body" }, { "t": "25.7.2 Where permitted by Applicable Law, acceptance through electronic means, electronic signature, digital signature, or other electronic authentication mechanism approved by the Marketplace may constitute valid execution and acceptance of this Agreement.", "k": "body" }, { "t": "25.8 Electronic Contracting", "k": "h2" }, { "t": "25.8.1 The Participant agrees that this Agreement may be accepted electronically through the Platform or another electronic mechanism designated by the Marketplace.", "k": "body" }, { "t": "25.8.2 Such electronic acceptance shall, to the extent permitted by Applicable Law, have the same contractual effect as a manually executed agreement.", "k": "body" }, { "t": "25.9 Order of Precedence", "k": "h2" }, { "t": "25.9.1 In the event of an inconsistency between provisions applicable to the Participant, the following order of precedence shall apply unless expressly stated otherwise:\n(a) mandatory Applicable Law;\n(b) the specific written terms expressly agreed between the Parties for the relevant matter;\n(c) this Agreement;\n(d) applicable Commercial Terms;\n(e) applicable Policies; and\n(f) general Platform information or operational communications.", "k": "body" }, { "t": "25.9.2 No operational communication shall amend this Agreement unless it expressly states that it is intended to amend the Agreement and is issued through an authorised channel.", "k": "body" }, { "t": "25.10 Headings", "k": "h2" }, { "t": "25.10.1 Section and subsection headings are included for convenience and shall not affect the interpretation of this Agreement.", "k": "body" }, { "t": "25.11 Interpretation", "k": "h2" }, { "t": "25.11.1 This Agreement shall be interpreted reasonably and in accordance with its commercial purpose, subject always to Applicable Law.", "k": "body" }, { "t": "25.11.2 The words “including”, “include”, and similar expressions shall be interpreted as being without limitation unless expressly stated otherwise.", "k": "body" }, { "t": "25.12 No Construction Against Drafter", "k": "h2" }, { "t": "25.12.1 To the extent permitted by Applicable Law, no provision of this Agreement shall be construed adversely against either Party solely because that Party prepared, proposed, or drafted the relevant provision.", "k": "body" }, { "t": "25.13 Binding Effect", "k": "h2" }, { "t": "25.13.1 This Agreement shall be binding upon the Parties and their respective permitted successors and assigns.", "k": "body" }, { "t": "25.14 Notices and Contact Details", "k": "h2" }, { "t": "25.14.1 Notices shall be given in accordance with Section 19.", "k": "h2" }, { "t": "25.14.2 The Marketplace's mailing address for contractual and official communications shall be the address specified in the preamble to this Agreement, unless subsequently notified otherwise.", "k": "body" }, { "t": "25.15 No Presumption of Partnership", "k": "h2" }, { "t": "25.15.1 Nothing in this Agreement shall be interpreted as creating any partnership, joint venture, agency, employment, franchise, or fiduciary relationship except as expressly provided.", "k": "body" }, { "t": "25.16 Survival", "k": "h2" }, { "t": "25.16.1 Any provision which by its nature or express terms is intended to survive termination or expiry of this Agreement shall continue in effect, including provisions relating to payment obligations, Settlement, confidentiality, data, intellectual property, indemnification, limitation of liability, disputes, governing law, records, and accrued rights.", "k": "body" }, { "t": "25.17 Binding Effect of Platform Acceptance", "k": "h2" }, { "t": "25.17.1 By registering for, accessing, or continuing to use the Platform after being provided access to this Agreement, the Participant acknowledges that it has had an opportunity to review the Agreement and agrees to be bound by its applicable terms, subject to Applicable Law.", "k": "body" }, { "t": "25.17.2 Where the Marketplace requires affirmative electronic acceptance, the Participant's acceptance through the prescribed mechanism shall constitute acceptance of this Agreement.", "k": "body" }, { "t": "26. FINAL ACKNOWLEDGEMENT, ACCEPTANCE AND ELECTRONIC EXECUTION", "k": "h1" }, { "t": "26.1 Participant's Acknowledgement", "k": "h2" }, { "t": "26.1.1 The Participant acknowledges that it has read, understood and agreed to the terms and conditions of this Agreement, together with the applicable Policies and other terms expressly incorporated into this Agreement.", "k": "body" }, { "t": "26.1.2 The Participant acknowledges that the Platform is a business-to-business marketplace and that the Participant may act as a Buyer, Seller, or both, depending upon the relevant Transaction.", "k": "body" }, { "t": "26.1.3 The Participant confirms that it has had sufficient opportunity to review this Agreement and obtain such legal, commercial, tax or other professional advice as it considers appropriate before accepting this Agreement.", "k": "body" }, { "t": "26.2 Acceptance of Agreement", "k": "h2" }, { "t": "26.2.1 By electronically accepting this Agreement through the Platform, the Participant agrees to be bound by all terms, conditions, obligations, representations, warranties and restrictions contained in this Agreement.", "k": "body" }, { "t": "26.2.2 Acceptance of this Agreement shall constitute a binding agreement between the Participant and the Marketplace from the Effective Date specified in the Agreement or, where no separate Effective Date is specified, from the date on which the Participant electronically accepts the Agreement through the Platform.", "k": "body" }, { "t": "26.2.3 The Participant's acceptance shall apply to its use of the Platform and to Transactions conducted through the Platform in accordance with this Agreement.", "k": "body" }, { "t": "26.3 Authority of the Person Accepting the Agreement", "k": "h2" }, { "t": "26.3.1 The person electronically accepting this Agreement on behalf of the Participant represents and warrants that such person is duly authorised to accept this Agreement and to bind the Participant to its terms.", "k": "body" }, { "t": "26.3.2 The Participant shall be solely responsible for ensuring that only a duly authorised person accesses its Account and accepts this Agreement or provides any other binding instruction through the Platform.", "k": "body" }, { "t": "26.3.3 The Marketplace shall be entitled to rely upon an electronic acceptance made through the Participant's Account as acceptance by the Participant, unless otherwise required by Applicable Law.", "k": "body" }, { "t": "26.4 Electronic Acceptance and Authentication", "k": "h2" }, { "t": "26.4.1 The Participant may accept this Agreement electronically through the Platform by using the acceptance mechanism designated by the Marketplace, which may include an acceptance checkbox, button, electronic confirmation, OTP-based authentication, Account authentication, or any combination of such mechanisms.", "k": "body" }, { "t": "26.4.2 The Participant's electronic acceptance, together with the authentication or verification associated with its Account, shall constitute evidence of the Participant's intention to enter into and be bound by this Agreement.", "k": "body" }, { "t": "26.4.3 The Marketplace may require the Participant to complete such authentication or verification steps as it considers reasonably necessary before permitting acceptance of this Agreement or access to the Platform.", "k": "body" }, { "t": "26.5 Electronic Acceptance Records", "k": "h2" }, { "t": "26.5.1 The Marketplace may create and maintain electronic records evidencing the Participant's acceptance of this Agreement.", "k": "body" }, { "t": "26.5.2 Such records may include, as applicable:", "k": "h2" }, { "t": "(a) Participant's legal/entity name;", "k": "body" }, { "t": "(b) GSTIN;", "k": "body" }, { "t": "(c) name and designation of the person accepting the Agreement;", "k": "body" }, { "t": "(d) verified official email address;", "k": "body" }, { "t": "(e) verified official mobile number;", "k": "body" }, { "t": "(f) date and time of acceptance;", "k": "body" }, { "t": "(g) Agreement version and effective version date;", "k": "body" }, { "t": "(h) Account or transaction reference;", "k": "body" }, { "t": "(i) authentication or verification records; and", "k": "body" }, { "t": "(j) such other technical or Platform Records as may be reasonably maintained by the Marketplace.", "k": "body" }, { "t": "26.5.3 Such electronic records may be retained by the Marketplace in accordance with its record-retention practices and Applicable Law and may be relied upon as evidence of the Participant's electronic acceptance and related activities on the Platform.", "k": "body" }, { "t": "26.6 No Physical Signature Required", "k": "h2" }, { "t": "26.6.1 Unless otherwise required by Applicable Law or specifically requested by the Marketplace, the Participant shall not be required to print, sign, stamp, scan, upload or physically deliver a copy of this Agreement for the Agreement to become binding.", "k": "body" }, { "t": "26.6.2 Electronic acceptance through the Platform in accordance with this Clause 26 shall be sufficient to evidence the Participant's acceptance of this Agreement, subject to Applicable Law.", "k": "body" }, { "t": "26.6.3 The absence of a handwritten signature or physical company stamp shall not, by itself, affect the validity or enforceability of the Agreement to the extent permitted under Applicable Law.", "k": "body" }, { "t": "26.7 Marketplace Acceptance and Execution", "k": "h2" }, { "t": "26.7.1 The Marketplace may evidence its acceptance and execution of this Agreement through the establishment, operation and maintenance of the Platform and the electronic onboarding and acceptance process made available to the Participant.", "k": "body" }, { "t": "26.7.2 The Marketplace may, where considered necessary or appropriate, additionally execute, electronically sign, digitally sign, or otherwise authenticate this Agreement or a particular version of the Agreement through an authorised representative of the Marketplace.", "k": "body" }, { "t": "26.7.3 The absence of a separate signature by an authorised representative of the Marketplace shall not, by itself, prevent this Agreement from becoming binding upon the Participant following valid electronic acceptance, to the extent permitted by Applicable Law.", "k": "body" }, { "t": "26.8 Agreement Version and Effective Terms", "k": "h2" }, { "t": "26.8.1 The version of the Agreement presented to and accepted by the Participant shall be the version applicable to the Participant from the relevant Effective Date, subject to subsequent amendments made in accordance with Clause 22.", "k": "body" }, { "t": "26.8.2 The Marketplace may maintain records identifying the version of the Agreement accepted by each Participant.", "k": "body" }, { "t": "26.8.3 Where a Participant is required to accept an amended or updated version of the Agreement, the electronic acceptance of such amended or updated version shall constitute acceptance of that version from its applicable effective date.", "k": "body" }, { "t": "26.9 Participant's Continuing Responsibility", "k": "h2" }, { "t": "26.9.1 The Participant shall remain responsible for complying with this Agreement throughout the period during which its Account remains active or it otherwise continues to have obligations under this Agreement.", "k": "body" }, { "t": "26.9.2 The Participant shall ensure that its authorised representatives, employees, agents and other persons accessing or using its Account are informed of and comply with the applicable terms of this Agreement.", "k": "body" }, { "t": "26.9.3 The Participant shall not dispute the validity of its electronic acceptance solely on the ground that the Agreement was accepted electronically rather than through a physical signature, except to the extent such dispute is based upon circumstances recognised under Applicable Law.", "k": "body" }, { "t": "26.10 Counterparts and Electronic Copies", "k": "h2" }, { "t": "26.10.1 Where a copy of this Agreement is generated, downloaded, displayed or otherwise made available electronically, such electronic copy may be retained by the Participant for its records.", "k": "body" }, { "t": "26.10.2 The Marketplace may maintain the executed or accepted electronic version of this Agreement in its electronic records.", "k": "body" }, { "t": "26.10.3 Any electronically generated copy of the Agreement corresponding to the version accepted by the Participant may be used for reference and record purposes, subject to Applicable Law.", "k": "body" }, { "t": "26.11 Effective Date", "k": "h2" }, { "t": "26.11.1 Unless otherwise expressly specified in this Agreement, the Agreement shall become effective upon completion of the Participant's electronic acceptance through the Platform.", "k": "body" }, { "t": "26.11.2 Registration, Account activation, Platform access and electronic acceptance may occur at different times. The Marketplace may determine the applicable onboarding and activation sequence in accordance with its operational requirements and Policies.", "k": "body" }, { "t": "26.12 Final Understanding", "k": "h2" }, { "t": "26.12.1 The Participant confirms that its electronic acceptance of this Agreement is made voluntarily and with the intention to create legally binding obligations between the Participant and the Marketplace.", "k": "body" }, { "t": "26.12.2 The Participant acknowledges that this Agreement, together with the Policies and other documents expressly incorporated herein, constitutes the contractual framework governing the Participant's use of the Platform and its participation in Transactions through the Platform.", "k": "body" }, { "t": "26.12.3 By completing the electronic acceptance process, the Participant confirms that it accepts and agrees to be bound by this Agreement.", "k": "body" }];

